import React, { useState } from 'react';

function StepZero({ onNext, onLoginData, language = 'en' }) {
  const [isLoading, setIsLoading] = useState(false);

  const texts = {
    zh: {
      title: "请注册您的账号",
      footerText: "🌙 开始您的专属AI伴侣之旅",
      buttonText: "点击注册",
      loadingText: "注册中..."
    },
    en: {
      title: "Please register your account",
      footerText: "🌙 Start your AI companion journey",
      buttonText: "Click to register",
      loadingText: "Registering..."
    }
  };

  const t = texts[language] || texts.zh;

  const handleSubmit = async () => {
    setIsLoading(true);
    
    setTimeout(() => {
      onLoginData({}); // No username needed now
      onNext();
      setIsLoading(false);
    }, 1000);
  };

  return (
    <div className="step-container">
      <div className="card">
        <div className="card-header">
          <h2 className="card-title">{t.title}</h2>
        </div>
        <div className="card-content">
          <div className="form-actions">
            <button 
              className="btn-primary" 
              onClick={handleSubmit}
              disabled={isLoading}
            >
              {isLoading ? t.loadingText : `${t.buttonText} ✨`}
            </button>
          </div>

          <div className="footer-text">
            <div>{t.footerText}</div>
          </div>
        </div>
      </div>
      
      <style>{`
        .step-container {
          min-height: 100vh;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 1rem;
          position: relative;
          z-index: 20;
        }
        
        .card {
          width: 100%;
          max-width: 400px;
          background: rgba(255, 255, 255, 0.95);
          backdrop-filter: blur(10px);
          border-radius: 16px;
          box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
          border: 1px solid rgba(255, 255, 255, 0.2);
        }
        
        .card-header {
          text-align: center;
          padding: 3rem 2rem 2rem;
        }
        
        .card-title {
          font-size: 1.5rem;
          font-weight: 700;
          color: #1a1a1a;
          margin: 0;
        }
        
        .card-content {
          padding: 1rem 2rem 2rem;
        }
        
        .form-actions {
          margin-bottom: 1.5rem;
        }
        
        .btn-primary {
          width: 100%;
          padding: 0.875rem;
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          color: white;
          border: none;
          border-radius: 8px;
          font-size: 1rem;
          font-weight: 600;
          cursor: pointer;
          transition: all 0.2s ease;
          min-height: 44px;
        }
        
        .btn-primary:hover:not(:disabled) {
          transform: translateY(-1px);
          box-shadow: 0 4px 12px rgba(102, 126, 234, 0.4);
        }
        
        .btn-primary:active {
          transform: translateY(0);
        }
        
        .btn-primary:disabled {
          background: #ccc;
          cursor: not-allowed;
          transform: none;
          box-shadow: none;
        }
        
        .footer-text {
          text-align: center;
        }
        
        .footer-text div {
          font-size: 0.8rem;
          color: #666;
        }
        
        @media (max-width: 480px) {
          .step-container {
            padding: 0.5rem;
          }
          
          .card {
            border-radius: 12px;
          }
          
          .card-header {
            padding: 2rem 1.5rem 1.5rem;
          }
          
          .card-content {
            padding: 1rem 1.5rem 1.5rem;
          }
          
          .card-title {
            font-size: 1.25rem;
          }
        }
      `}</style>
    </div>
  );
}

export default StepZero;