import React, { useEffect, useState } from 'react';

function LoadingScreen({ onComplete, text, duration = 3000, showMagicalBackground = false, isIndefinite = false }) {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    if (isIndefinite) {
      // 无限loading，不自动完成
      return;
    }

    const interval = setInterval(() => {
      setProgress(prev => {
        const newProgress = prev + (100 / (duration / 100));
        if (newProgress >= 100) {
          clearInterval(interval);
          setTimeout(onComplete, 100);
          return 100;
        }
        return newProgress;
      });
    }, 100);

    return () => clearInterval(interval);
  }, [duration, onComplete, isIndefinite]);

  return (
    <div className="loading-screen">
      {showMagicalBackground && <div className="magical-bg"></div>}
      
      <div className="loading-content">
        <div className="loading-spinner">
          <div className="spinner"></div>
        </div>
        <div className="loading-text">{text}</div>
        {!isIndefinite && (
          <div className="progress-bar">
            <div className="progress-fill" style={{ width: `${progress}%` }}></div>
          </div>
        )}
      </div>

      <style>{`
        .loading-screen {
          position: fixed;
          top: 0;
          left: 0;
          width: 100%;
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
          z-index: 50;
          background: rgba(0, 0, 0, 0.9);
        }
        
        .magical-bg {
          position: absolute;
          top: 0;
          left: 0;
          width: 100%;
          height: 100%;
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          opacity: 0.8;
        }
        
        .loading-content {
          text-align: center;
          position: relative;
          z-index: 10;
        }
        
        .loading-spinner {
          margin-bottom: 2rem;
        }
        
        .spinner {
          width: 60px;
          height: 60px;
          border: 4px solid rgba(255, 255, 255, 0.3);
          border-top: 4px solid #fff;
          border-radius: 50%;
          animation: spin 1s linear infinite;
          margin: 0 auto;
        }
        
        .loading-text {
          color: #fff;
          font-size: 1.2rem;
          font-weight: 500;
          margin-bottom: 2rem;
        }
        
        .progress-bar {
          width: 200px;
          height: 4px;
          background: rgba(255, 255, 255, 0.3);
          border-radius: 2px;
          overflow: hidden;
          margin: 0 auto;
        }
        
        .progress-fill {
          height: 100%;
          background: linear-gradient(90deg, #fff, #f0f0f0);
          border-radius: 2px;
          transition: width 0.1s ease;
        }
        
        @keyframes spin {
          0% { transform: rotate(0deg); }
          100% { transform: rotate(360deg); }
        }
        
        @media (max-width: 480px) {
          .loading-text {
            font-size: 1rem;
            padding: 0 1rem;
          }
          
          .progress-bar {
            width: 150px;
          }
        }
      `}</style>
    </div>
  );
}

export default LoadingScreen;