import React, { useState, useEffect } from 'react';
import { useLanguage } from '../../contexts/LanguageContext';
import { getSmartBackendUrl } from '../../utils/env';
import SystemSettingsModal from '../SystemSettingsModal';
import './ProjectManager.css';

const ProjectManager = ({ onVersionSelect }) => {
  const { t } = useLanguage();
  const [projects, setProjects] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [creating, setCreating] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    researcher: '',
    task: '',
    serialNumber: ''
  });
  const [formErrors, setFormErrors] = useState({});
  const [showSystemSettings, setShowSystemSettings] = useState(false);

  // 用于跟踪组件是否已卸载
  const isMountedRef = React.useRef(true);

  // 加载项目列表
  useEffect(() => {
    loadProjects();
    
    // cleanup函数：组件卸载时设置标记
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  const loadProjects = async () => {
    try {
      if (!isMountedRef.current) return;
      setLoading(true);
      setError(null);
      
      const response = await fetch(`${getSmartBackendUrl()}/api/designer/projects`);
      const data = await response.json();
      
      if (!isMountedRef.current) return;
      
      if (data.success) {
        setProjects(data.projects);
      } else {
        throw new Error(data.error || '获取项目列表失败');
      }
    } catch (err) {
      console.error('加载项目失败:', err);
      if (!isMountedRef.current) return;
      setError(t('designerPage.projectManager.getProjectsFailed') + ': ' + err.message);
    } finally {
      if (isMountedRef.current) {
        setLoading(false);
      }
    }
  };

  // 处理表单输入
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    
    // 清除对应字段的错误
    if (formErrors[name]) {
      setFormErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  // 验证表单
  const validateForm = () => {
    const errors = {};
    
    if (!formData.researcher.trim()) {
      errors.researcher = t('designerPage.projectManager.researcherRequired');
    }
    
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  // 创建新项目
  const handleCreateProject = async (e) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    try {
      if (!isMountedRef.current) return;
      setCreating(true);
      
      const response = await fetch(`${getSmartBackendUrl()}/api/designer/projects`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          name: formData.name && formData.name.trim() ? formData.name : t('designerPage.projectManager.unnamedProject'),
          researcher: formData.researcher,
          task: formData.task || '',
          serialNumber: formData.serialNumber || ''
        })
      });
      
      const data = await response.json();
      
      if (!isMountedRef.current) return;
      
      if (data.success) {
        // 创建成功，关闭表单并直接进入项目
        setShowCreateForm(false);
        setFormData({ name: '', researcher: '', task: '', serialNumber: '' });
        
        // 直接选择新创建的项目
        await handleProjectSelect(data.project);
        
        // 重新加载项目列表
        loadProjects();
      } else {
        throw new Error(data.error || t('designerPage.projectManager.createProjectFailed'));
      }
    } catch (err) {
      console.error('创建项目失败:', err);
      if (!isMountedRef.current) return;
      setError(t('designerPage.projectManager.createProjectFailed') + ': ' + err.message);
    } finally {
      if (isMountedRef.current) {
        setCreating(false);
      }
    }
  };

  // 取消创建项目
  const handleCancelCreate = () => {
    setShowCreateForm(false);
    setFormData({ name: '', researcher: '', task: '', serialNumber: '' });
    setFormErrors({});
  };

  // 选择项目 - 直接进入工具主页面（选择最新版本或创建默认版本）
  const handleProjectSelect = async (project) => {
    try {
      if (!isMountedRef.current) return;
      setLoading(true);
      
      // 加载项目详情
      const response = await fetch(`${getSmartBackendUrl()}/api/designer/project/${project.id}`);
      const data = await response.json();
      
      if (!isMountedRef.current) return;
      
      if (data.success && data.project.versions && data.project.versions.length > 0) {
        // 如果项目有版本，选择最新的版本（versionNumber最大的）
        const latestVersion = data.project.versions.reduce((latest, version) => {
          return version.versionNumber > latest.versionNumber ? version : latest;
        });
        
        console.log('选择项目最新版本:', latestVersion.versionNumber);
        
        // 加载完整的版本数据以检查是否有face元素
        const versionResponse = await fetch(`${getSmartBackendUrl()}/api/designer/project/${project.id}/version/${latestVersion.id}`);
        const versionData = await versionResponse.json();
        
        if (!isMountedRef.current) return;
        
        if (versionData.success) {
          const version = versionData.version;
          
          // 检查是否已有face元素
          const faceElement = version.editorData.svgElements.find(element => 
            element.semanticTag === 'face' || element.name === 'face'
          );
          
          const canvasSize = version.editorData.canvasSize || { width: 800, height: 500 };
          let needsUpdate = false;
          
          // 根据画布类型判断是否需要face元素
          // AI玩具和服务机器人需要face背景，虚拟伴侣不需要
          const getCanvasType = (size) => {
            if (size.width === 852 && size.height === 393) return 'ai-toy';
            if (size.width === 320 && size.height === 200) return 'service-robot';
            if (size.width === 320 && size.height === 320) return 'virtual-companion';
            if (size.width === 800 && size.height === 500) return 'default';
            return 'unknown';
          };
          
          const canvasType = getCanvasType(canvasSize);
          const needsFaceElement = canvasType === 'ai-toy' || canvasType === 'service-robot' || canvasType === 'default';
          
          if (needsFaceElement && !faceElement) {
            // 如果需要face元素但没有，自动添加一个
            const newFaceElement = {
              id: `face_${Date.now()}`,
              type: 'rect',
              x: 0,
              y: 0,
              width: canvasSize.width,
              height: canvasSize.height,
              fill: '#f0f0f0',
              fillOpacity: 0.8,
              stroke: 'none',
              semanticTag: 'face',
              name: 'face'
            };
            
            // 将face元素添加到数组开头，作为背景
            version.editorData.svgElements.unshift(newFaceElement);
            needsUpdate = true;
            console.log(`为${canvasType}画布添加face元素，尺寸:`, canvasSize);
          } else if (needsFaceElement && faceElement && (faceElement.width !== canvasSize.width || faceElement.height !== canvasSize.height)) {
            // 如果需要face元素且已存在，但尺寸与画布不匹配，更新尺寸
            faceElement.width = canvasSize.width;
            faceElement.height = canvasSize.height;
            needsUpdate = true;
            console.log(`更新${canvasType}画布face元素尺寸:`, canvasSize);
          } else if (!needsFaceElement && faceElement) {
            // 虚拟AI伴侣(virtual-companion)模式：保留用户手动添加的face，不自动移除
            if (canvasType === 'virtual-companion') {
              console.log('保留虚拟AI伴侣画布中的face元素（不再自动删除）');
            } else {
              // 其他不需要face的未知画布，仍按原逻辑移除
              const faceIndex = version.editorData.svgElements.findIndex(element => 
                element.semanticTag === 'face' || element.name === 'face'
              );
              if (faceIndex !== -1) {
                version.editorData.svgElements.splice(faceIndex, 1);
                needsUpdate = true;
                console.log(`移除${canvasType}画布的face元素`);
              }
            }
          }
          
          if (needsUpdate) {
            // 保存更新后的版本数据
            const saveResponse = await fetch(`${getSmartBackendUrl()}/api/designer/project/${project.id}/version/${latestVersion.id}`, {
              method: 'PUT',
              headers: {
                'Content-Type': 'application/json'
              },
              body: JSON.stringify(version)
            });
            
            if (!isMountedRef.current) return;
            
            if (saveResponse.ok) {
              console.log('已更新版本的face元素');
            }
          }
          
          onVersionSelect(data.project, version);
        } else {
          throw new Error(versionData.error || t('designerPage.projectManager.loadVersionDetailsFailed'));
        }
      } else {
        // 如果项目没有版本，自动创建一个默认的角色生成版本
        const createResponse = await fetch(`${getSmartBackendUrl()}/api/designer/project/${project.id}/versions`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            type: 'role',
            name: t('designerPage.projectManager.defaultVersion'),
            editorData: {
              svgElements: [
                // 只为非正方形画布添加face元素
                // 800x500是非正方形，所以添加face元素
                {
                  id: `face_${Date.now()}`,
                  type: 'rect',
                  x: 0,
                  y: 0,
                  width: 800,
                  height: 500,
                  fill: '#f0f0f0',
                  fillOpacity: 0.8,
                  stroke: 'none',
                  semanticTag: 'face',
                  name: 'face'
                }
              ],
              canvasSize: { width: 800, height: 500 },
              toolSettings: {}
            },
            designRules: []
          })
        });
        
        const createData = await createResponse.json();
        
        if (!isMountedRef.current) return;
        
        if (createData.success) {
          console.log('为项目创建默认版本:', createData.version.versionNumber);
          onVersionSelect(project, createData.version);
        } else {
          throw new Error(createData.error || t('designerPage.projectManager.createDefaultVersionFailed'));
        }
      }
    } catch (err) {
      console.error('选择项目失败:', err);
      if (!isMountedRef.current) return;
      setError(t('designerPage.projectManager.loadVersionDetailsFailed') + ': ' + err.message);
    } finally {
      if (isMountedRef.current) {
        setLoading(false);
      }
    }
  };

  // 删除项目
  const handleDeleteProject = async (projectId, projectName) => {
    if (!window.confirm(`确定要删除项目"${projectName}"吗？此操作不可恢复，将删除该项目下的所有版本。`)) {
      return;
    }

    try {
      const response = await fetch(`${getSmartBackendUrl()}/api/designer/project/${projectId}`, {
        method: 'DELETE'
      });

      const data = await response.json();

      if (!isMountedRef.current) return;

      if (data.success) {
        alert('项目删除成功！');
        loadProjects(); // 重新加载项目列表
      } else {
        throw new Error(data.error || t('designerPage.projectManager.deleteProjectFailed'));
      }
    } catch (err) {
      console.error('删除项目失败:', err);
      if (!isMountedRef.current) return;
      setError(t('designerPage.projectManager.deleteProjectFailed') + ': ' + err.message);
    }
  };

  // 格式化日期
  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('zh-CN', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  if (loading) {
    return (
      <div className="project-manager">
        <div className="loading">{t('common.loading')}</div>
      </div>
    );
  }

  return (
    <div className="project-manager">
      <div className="project-manager-header">
        <h2>{t('designerPage.projectManager')}</h2>
        <div className="header-actions">
          <button 
            className="settings-btn"
            onClick={() => setShowSystemSettings(true)}
            title={t('common.systemSettings')}
          >
            ⚙️
          </button>
          <button 
            className="create-project-btn"
            onClick={() => setShowCreateForm(true)}
          >
{t('designerPage.projectManager.createProject')}
          </button>
        </div>
      </div>

      {error && (
        <div className="error-message">
          {error}
        </div>
      )}

      {/* 新建项目表单 */}
      {showCreateForm && (
        <div className="create-project-form">
          <h3>{t('designerPage.createProject')}</h3>
          <form onSubmit={handleCreateProject}>
            <div className="form-group">
              <label htmlFor="serialNumber">编号</label>
              <input
                type="text"
                id="serialNumber"
                name="serialNumber"
                value={formData.serialNumber}
                onChange={handleInputChange}
              />
            </div>
            <div className="form-group">
              <label htmlFor="name">项目名称</label>
              <input
                type="text"
                id="name"
                name="name"
                value={formData.name}
                onChange={handleInputChange}
                placeholder={t('designerPage.projectManager.projectNamePlaceholder')}
              />
            </div>

            <div className="form-group">
              <label htmlFor="researcher">研究者姓名</label>
              <input
                type="text"
                id="researcher"
                name="researcher"
                value={formData.researcher}
                onChange={handleInputChange}
                className={formErrors.researcher ? 'error' : ''}
              />
              {formErrors.researcher && <span className="error-text">{formErrors.researcher}</span>}
            </div>

            <div className="form-group">
              <label htmlFor="task">任务描述</label>
              <textarea
                id="task"
                name="task"
                value={formData.task}
                onChange={handleInputChange}
                rows="3"
                placeholder="（可选）"
              />
            </div>

            <div className="form-actions">
              <button 
                type="button" 
                className="cancel-btn"
                onClick={handleCancelCreate}
              >
{t('common.cancel')}
              </button>
              <button 
                type="submit" 
                className="submit-btn"
                disabled={creating}
              >
{creating ? t('designerPage.projectManager.creating') : t('designerPage.projectManager.createProject')}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* 项目列表 */}
      <div className="projects-list">
        {projects.length === 0 ? (
          <div className="empty-state">
            <p>{t('designerPage.projectManager.noProjects')}</p>
          </div>
        ) : (
          <div className="projects-grid">
            {projects.map(project => (
              <div 
                key={project.id} 
                className="project-card"
              >
                <div className="project-card-content" onClick={() => handleProjectSelect(project)}>
                  <div className="project-header">
                    <h3>{project.name}</h3>
                    <span className="version-count-badge">
                      {project.versionCount || 0} 个版本
                    </span>
                  </div>
                  <div className="project-info">
                    {project.serialNumber && (
                      <p><strong>编号:</strong> {project.serialNumber}</p>
                    )}
                    <p><strong>研究者:</strong> {project.researcher}</p>
                    <p><strong>任务:</strong> {project.task}</p>
                    <p><strong>创建时间:</strong> {formatDate(project.createdAt)}</p>
                  </div>
                </div>
                <div className="project-actions">
                  <button 
                    className="delete-btn"
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteProject(project.id, project.name);
                    }}
                    title={t('designerPage.projectManager.deleteProject')}
                  >
                    ×
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* 系统设置模态框 */}
      <SystemSettingsModal
        isOpen={showSystemSettings}
        onClose={() => setShowSystemSettings(false)}
      />
    </div>
  );
};

export default ProjectManager;
