import React, { useRef, useImperativeHandle } from 'react';
import { useLanguage } from '../../contexts/LanguageContext';
import HorizontalTestInterface from './HorizontalTestInterface';
import './BottomPanel.css';

function BottomPanel({ 
  isCollapsed, 
  onToggle, 
  project, 
  version, 
  currentEditorData, 
  onTestComplete,
  onBeforeTest,
  expressionMode
}) {
  const { t, language } = useLanguage();
  const testInterfaceRef = useRef(null);
  // 移除拖拽相关逻辑，嵌入式面板不需要拖拽功能

  return (
    <div className={`bottom-panel ${isCollapsed ? 'collapsed' : ''}`}>
      {/* 移除拖拽手柄，嵌入式面板不需要 */}

      {/* 面板标题栏 */}
      {!isCollapsed && (
        <div className="bottom-panel-header">
          <div className="panel-title-simple">
            <span className="panel-title-text">{t('designerPage.testPanel.title')}</span>
          </div>
          <div className="panel-header-actions">
            {/* Device Deploy按钮 - 在Basic Expression和Change Expression模式下都显示 */}
            {(expressionMode === 'basic' || expressionMode === 'change') && (
              <button 
                className="device-deploy-btn"
                onClick={(e) => {
                  e.stopPropagation();
                  // 根据画布尺寸判断调用哪个测试函数
                  // 桌面AI玩具画布: 852x393
                  // 服务机器人画布: 320x200
                  // 虚拟AI伴侣画布: 320x320
                  const canvasWidth = currentEditorData?.canvasSize?.width;
                  const canvasHeight = currentEditorData?.canvasSize?.height;
                  const isDesktopAIToy = canvasWidth === 852 && canvasHeight === 393;
                  const isServiceRobot = canvasWidth === 320 && canvasHeight === 200;
                  const isVirtualAICompanion = canvasWidth === 320 && canvasHeight === 320;
                  
                  if (testInterfaceRef.current) {
                    if (isDesktopAIToy && testInterfaceRef.current.handleRealDeviceTest) {
                      // 桌面AI玩具模式
                      testInterfaceRef.current.handleRealDeviceTest();
                    } else if (isServiceRobot && testInterfaceRef.current.handleServiceRobotTest) {
                      // 服务机器人模式
                      testInterfaceRef.current.handleServiceRobotTest();
                    } else if (isVirtualAICompanion && testInterfaceRef.current.handleAICompanionTest) {
                      // 虚拟AI伴侣模式
                      testInterfaceRef.current.handleAICompanionTest();
                    } else {
                      console.warn('Device Deploy: No matching test handler for current canvas size');
                    }
                  } else {
                    console.warn('Device Deploy: testInterfaceRef not available');
                  }
                }}
                title={
                  currentEditorData?.canvasSize?.width === 852 && currentEditorData?.canvasSize?.height === 393
                    ? "Deploy to Desktop AI Toy"
                    : currentEditorData?.canvasSize?.width === 320 && currentEditorData?.canvasSize?.height === 200
                    ? "Deploy to Service Robot"
                    : currentEditorData?.canvasSize?.width === 320 && currentEditorData?.canvasSize?.height === 320
                    ? "Deploy to Virtual AI Companion"
                    : "Deploy to Device"
                }
              >
                Device Deploy
              </button>
            )}
            <button 
              className="panel-collapse-btn"
              onClick={onToggle}
              title={t('designerPage.testPanel.collapseTitle')}
            >
              <span style={{ fontSize: '14px', color: '#858CA0' }}>▼</span>
            </button>
          </div>
        </div>
      )}

      {/* 测试界面内容 */}
      {!isCollapsed && project && version && (
        <div className="bottom-panel-content">
          <HorizontalTestInterface
            ref={testInterfaceRef}
            project={project}
            version={version}
            currentEditorData={currentEditorData}
            onTestComplete={onTestComplete}
            onBeforeTest={onBeforeTest}
            expressionMode={expressionMode}
          />
        </div>
      )}

      {/* 折叠状态下的简化信息 */}
      {isCollapsed && (
        <div className="collapsed-info" onClick={onToggle} title={t('designerPage.testPanel.expandTitle')}>
          <div className="collapsed-left">
            <span className="collapsed-text">{t('designerPage.testPanel.collapsedText')}</span>
          </div>
          <button 
            className="panel-expand-btn"
            onClick={(e) => {
              e.stopPropagation(); // 防止事件冒泡
              onToggle();
            }}
            title={t('designerPage.testPanel.expandTitle')}
          >
            {t('designerPage.testPanel.expand')}
          </button>
        </div>
      )}
    </div>
  );
}

export default BottomPanel;