import React, { useState, useEffect } from 'react';
import './ChatInterface.css';
import { getSmartBackendUrl } from '../utils/env';

// 确保API基础URL正确格式化
const API_BASE_URL = getSmartBackendUrl();

// 调试信息
const debug = {
  log: (action, message, data = null) => {
    console.log(`[${new Date().toISOString()}] ${action}:`, message, data);
  },
  error: (action, error, context = null) => {
    console.error(
      `[${new Date().toISOString()}] Error in ${action}:`,
      '\nError:', error,
      '\nContext:', context
    );
  }
};

// 添加调试信息
debug.log('Config', '使用的API基础URL', API_BASE_URL);

const PromptTestChat = () => {
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [extendedThinking, setExtendedThinking] = useState(false);
  const [provider, setProvider] = useState('claude');
  const [model, setModel] = useState('');
  const [thinking, setThinking] = useState(null);

  // 根据提供商设置默认模型
  useEffect(() => {
    setModel(provider === 'claude' ? 'claude-sonnet-4-6' : 'mistral-medium');
  }, [provider]);

  // 在组件挂载时验证API URL
  useEffect(() => {
    debug.log('Config', 'API Base URL', API_BASE_URL);
    if (!API_BASE_URL) {
      debug.error('Config', 'API Base URL is not configured');
      setError('Backend URL is not configured');
    }
    try {
      new URL(API_BASE_URL); // 验证URL格式
    } catch (e) {
      debug.error('Config', 'Invalid API Base URL', { url: API_BASE_URL, error: e });
      setError('Invalid backend URL configuration');
    }
  }, []);

  const handleSendMessage = async (e) => {
    e.preventDefault();
    if (inputMessage.trim() && !loading) {
      setLoading(true);
      setError(null);
      setThinking(null);
      
      debug.log('Send', 'Preparing to send message', {
        messageLength: inputMessage.length,
        existingMessages: messages.length
      });

      // 创建新的用户消息
      const userMessage = {
        role: 'user',
        content: inputMessage,
        timestamp: new Date().toISOString()
      };

      // 添加用户消息到界面
      setMessages(prevMessages => [...prevMessages, userMessage]);
      setInputMessage('');

      try {
        if (!API_BASE_URL) {
          throw new Error('Backend URL is not configured');
        }

        const response = await fetch(`${API_BASE_URL}/api/prompt-test`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            messages: [...messages, userMessage],
            extendedThinking,
            provider,
            model
          })
        });

        debug.log('Response', 'Received response', {
          status: response.status,
          ok: response.ok
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const data = await response.json();
        debug.log('Response', 'Parsed response data', {
          messageLength: data.message.length,
          processingTime: data.processingTime,
          hasThinking: !!data.thinking
        });
        
        // 保存思考过程（如果有）
        if (data.thinking) {
          setThinking(data.thinking);
        }
        
        // 添加助手回复到消息历史
        const assistantMessage = {
          role: 'assistant',
          content: data.message,
          timestamp: new Date().toISOString()
        };
        setMessages(prevMessages => [...prevMessages, assistantMessage]);

      } catch (error) {
        debug.error('Request', error, {
          url: `${API_BASE_URL}/api/prompt-test`,
          inputLength: inputMessage.length,
          messagesCount: messages.length
        });
        
        setError(error.message);
        setMessages(prevMessages => [
          ...prevMessages,
          { 
            role: 'assistant', 
            content: 'Sorry, failed to send message.',
            timestamp: new Date().toISOString()
          }
        ]);
      } finally {
        setLoading(false);
      }
    }
  };

  return (
    <div className="chat-interface">
      <div className="chat-header">
        <h2>Prompt Testing Interface</h2>
        <div className="session-info">
          <div>API URL: {API_BASE_URL || 'Not configured'}</div>
          <div>Messages: {messages.length}</div>
          <div className="provider-selector">
            <select
              value={provider}
              onChange={(e) => setProvider(e.target.value)}
              disabled={loading}
            >
              <option value="claude">Claude</option>
              <option value="mistral">Mistral</option>
            </select>
            <select
              value={model}
              onChange={(e) => setModel(e.target.value)}
              disabled={loading}
            >
              {provider === 'claude' ? (
                <>
                  <option value="claude-sonnet-4-6">Claude Sonnet 4-6</option>
                  <option value="claude-opus-4-6">Claude Opus 4-6</option>
                </>
              ) : (
                <>
                  <option value="mistral-small">Mistral Small</option>
                  <option value="mistral-medium">Mistral Medium</option>
                  <option value="mistral-large">Mistral Large</option>
                </>
              )}
            </select>
          </div>
          <div className="extended-thinking-toggle">
            <label>
              <input
                type="checkbox"
                checked={extendedThinking}
                onChange={(e) => setExtendedThinking(e.target.checked)}
                disabled={provider === 'mistral'} // Mistral 不支持 Extended Thinking
              />
              Enable Extended Thinking
            </label>
          </div>
          {error && <div className="error-message">Error: {error}</div>}
        </div>
      </div>
      
      <div className="messages-container">
        {messages.map((message, index) => (
          <div
            key={index}
            className={`message ${message.role === 'user' ? 'user-message' : 'bot-message'}`}
          >
            <div className="message-content">{message.content}</div>
            <div className="message-timestamp">{new Date(message.timestamp).toLocaleTimeString()}</div>
          </div>
        ))}
        {loading && (
          <div className="message bot-message loading">
            Thinking...
          </div>
        )}
        {thinking && (
          <div className="message thinking-message">
            <div className="thinking-header">Extended Thinking:</div>
            <div className="thinking-content">{thinking}</div>
          </div>
        )}
      </div>

      <form className="input-container" onSubmit={handleSendMessage}>
        <textarea
          value={inputMessage}
          onChange={(e) => setInputMessage(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault();
              handleSendMessage(e);
            }
          }}
          placeholder="Type your prompt here... (Shift+Enter for new line)"
          className="message-input"
          disabled={loading || !!error}
          rows="3"
        />
        <button 
          type="submit" 
          className="send-button"
          disabled={loading || !!error}
        >
          {loading ? 'Sending...' : 'Send'}
        </button>
      </form>
    </div>
  );
};

export default PromptTestChat; 