import React, { useState } from 'react';
import { getSmartBackendUrl } from '../utils/env';

const API_BASE_URL = getSmartBackendUrl();

function TemiVoiceTestPage() {
  const [status, setStatus] = useState(null);
  const [listenLoading, setListenLoading] = useState(false);
  const [listenResult, setListenResult] = useState('');
  const [listenError, setListenError] = useState('');
  const [speakText, setSpeakText] = useState('你好，我是Temi，我在这里。');
  const [speakResult, setSpeakResult] = useState('');
  const [speakError, setSpeakError] = useState('');

  const refreshStatus = async () => {
    try {
      const resp = await fetch(`${API_BASE_URL}/api/temi/status`);
      const json = await resp.json();
      setStatus(json);
    } catch (e) {
      setStatus({ success: false, error: e.message });
    }
  };

  const handleListenOnce = async () => {
    setListenLoading(true);
    setListenError('');
    setListenResult('');
    try {
      const resp = await fetch(`${API_BASE_URL}/api/voiceInput`, { method: 'POST' });
      const text = await resp.text();
      let json = null;
      try { json = JSON.parse(text); } catch {}
      if (!resp.ok) {
        setListenError(`HTTP ${resp.status}: ${text}`);
      } else {
        const result = json?.result ?? text;
        setListenResult(typeof result === 'string' ? result : JSON.stringify(result));
      }
    } catch (e) {
      setListenError(e.message);
    } finally {
      setListenLoading(false);
    }
  };

  const handleSpeak = async () => {
    setSpeakResult('');
    setSpeakError('');
    try {
      const resp = await fetch(`${API_BASE_URL}/api/speak`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: speakText })
      });
      const text = await resp.text();
      if (!resp.ok) {
        setSpeakError(`HTTP ${resp.status}: ${text}`);
      } else {
        setSpeakResult(text);
      }
    } catch (e) {
      setSpeakError(e.message);
    }
  };

  const handleDisplaySelf = async () => {
    try {
      const url = `${window.location.origin}/temi-voice-test`;
      const resp = await fetch(`${API_BASE_URL}/api/temi/display`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url })
      });
      if (!resp.ok) {
        const t = await resp.text();
        alert(`Display failed: ${resp.status} ${t}`);
      } else {
        alert('已请求Temi显示当前测试页面');
      }
    } catch (e) {
      alert(`Display failed: ${e.message}`);
    }
  };

  return (
    <div style={{ minHeight: '100vh', padding: '16px', background: '#0b1022', color: '#fff' }}>
      <h2>Temi 语音回复测试</h2>
      <p>用于独立验证 Temi 的语音输入是否正确返回，以及播报是否可用。</p>

      <div style={{ marginTop: '16px', background: '#151b34', borderRadius: '8px', padding: '12px' }}>
        <div style={{ display: 'flex', gap: '8px', alignItems: 'center' }}>
          <button onClick={refreshStatus} style={{ padding: '8px 12px' }}>刷新 Temi 状态</button>
          <button onClick={handleDisplaySelf} style={{ padding: '8px 12px' }}>在 Temi 上显示本页</button>
        </div>
        <pre style={{ marginTop: '8px', whiteSpace: 'pre-wrap' }}>{JSON.stringify(status, null, 2)}</pre>
      </div>

      <div style={{ marginTop: '16px', background: '#151b34', borderRadius: '8px', padding: '12px' }}>
        <h3>1) 监听一次（30秒超时）</h3>
        <button onClick={handleListenOnce} disabled={listenLoading} style={{ padding: '8px 12px' }}>
          {listenLoading ? '正在等待语音输入…' : '开始监听一次'}
        </button>
        {listenResult && (
          <div style={{ marginTop: '8px', color: '#34d399' }}>识别结果: {listenResult}</div>
        )}
        {listenError && (
          <div style={{ marginTop: '8px', color: '#f87171' }}>错误: {listenError}</div>
        )}
        <div style={{ marginTop: '8px', fontSize: '12px', color: '#cbd5e1' }}>
          提示：点击后请在 30 秒内对 Temi 说话；超时将显示“语音输入超时”。
        </div>
      </div>

      <div style={{ marginTop: '16px', background: '#151b34', borderRadius: '8px', padding: '12px' }}>
        <h3>2) 播报测试</h3>
        <div style={{ display: 'flex', gap: '8px' }}>
          <input 
            value={speakText} 
            onChange={(e) => setSpeakText(e.target.value)} 
            style={{ flex: 1, padding: '8px', borderRadius: '6px', border: '1px solid #314160', color: '#fff', background: '#0b1022' }}
          />
          <button onClick={handleSpeak} style={{ padding: '8px 12px' }}>播报</button>
        </div>
        {speakResult && (
          <div style={{ marginTop: '8px', color: '#34d399' }}>已发送: {speakResult}</div>
        )}
        {speakError && (
          <div style={{ marginTop: '8px', color: '#f87171' }}>错误: {speakError}</div>
        )}
      </div>
    </div>
  );
}

export default TemiVoiceTestPage;

