  const handleElementOrderChange = useCallback((elementId, direction) => {
    setSvgElements(prev => {
      saveToHistory(prev);
      
      const currentIndex = prev.findIndex(el => el.id === elementId);
      if (currentIndex === -1) return prev;
      
      const newElements = [...prev];
      const element = newElements[currentIndex];
      
      switch (direction) {
        case 'up':
          // 上移一层（索引增加）
          if (currentIndex < newElements.length - 1) {
            newElements[currentIndex] = newElements[currentIndex + 1];
            newElements[currentIndex + 1] = element;
          }
          break;
        case 'down':
          // 下移一层（索引减少）
          if (currentIndex > 0) {
            newElements[currentIndex] = newElements[currentIndex - 1];
            newElements[currentIndex - 1] = element;
          }
          break;
        case 'top':
          // 置于顶层（移到数组末尾）
          if (currentIndex < newElements.length - 1) {
            newElements.splice(currentIndex, 1);
            newElements.push(element);
          }
          break;
        case 'bottom':
          // 置于底层（移到数组开头）
          if (currentIndex > 0) {
            newElements.splice(currentIndex, 1);
            newElements.unshift(element);
          }
          break;
        default:
          return prev;
      }
      
      return newElements;
    });
    
    // 🚀 触发实时自动保存
    setHasUnsavedChanges(true);
    debouncedAutoSave('change_layer_order');
  }, [saveToHistory, debouncedAutoSave]);

