    if (selectedElementIds.length < 2) return;
    
    // 创建新组合
    const groupId = `group_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    
    const newGroups = new Map(groups);
    const newGroupedElements = new Map(groupedElements);
    
    // 计算组合边界
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    selectedElementIds.forEach(elementId => {
      const element = svgElements.find(el => el.id === elementId);
      if (!element) return;
      
      let x, y, width, height;
      switch (element.type) {
        case 'rect':
          x = element.x;
          y = element.y;
          width = element.width;
          height = element.height;
          break;
        case 'circle':
          x = element.cx - element.r;
          y = element.cy - element.r;
          width = element.r * 2;
          height = element.r * 2;
          break;
        case 'ellipse':
          x = element.cx - element.rx;
          y = element.cy - element.ry;
          width = element.rx * 2;
          height = element.ry * 2;
          break;
        default:
          x = element.x || 0;
          y = element.y || 0;
          width = element.width || 0;
          height = element.height || 0;
      }
      
      minX = Math.min(minX, x);
      minY = Math.min(minY, y);
      maxX = Math.max(maxX, x + width);
      maxY = Math.max(maxY, y + height);
    });
    
    // 添加到组合映射
    selectedElementIds.forEach(elementId => {
      newGroupedElements.set(elementId, groupId);
    });
    
    newGroups.set(groupId, {
      elements: selectedElementIds,
      bounds: {
        x: minX,
        y: minY,
        width: maxX - minX,
        height: maxY - minY,
        centerX: (minX + maxX) / 2,
        centerY: (minY + maxY) / 2
      }
    });
    
    // 更新状态
    setGroups(newGroups);
    setGroupedElements(newGroupedElements);
    setSelectedGroupId(groupId);
    setSelectedElementIds([]);
    
    // 🚀 触发实时自动保存
    setHasUnsavedChanges(true);
    debouncedAutoSave('group_elements');
