// 🚨 LEGACY COMPONENT 🚨
// This TestInterface is now legacy. The primary testing functionality has moved to HorizontalTestInterface in BottomPanel.
// This component is kept for backward compatibility but should not be used for new features.
// Use HorizontalTestInterface in BottomPanel for all new testing functionality.

import React, { useState, useCallback, useEffect } from 'react';
import { useLanguage } from '../../contexts/LanguageContext';
import { getSmartBackendUrl } from '../../utils/env';
import systemSettings from '../../utils/SystemSettings';
import './TestInterface.css';

function TestInterface({ project, version, currentEditorData, onTestComplete, onBeforeTest }) {
  const { t, language } = useLanguage();
  
  // Helper function to get display name based on current language
  const getContextDisplayName = (name) => {
    const translations = {
      '环境氛围': { zh: '环境氛围', en: 'Atmosphere' },
      '用户情绪': { zh: '用户情绪', en: 'User Emotion' },
      '伴侣能量值': { zh: '伴侣能量值', en: 'Agent Energy' },
      '伴侣互动状态': { zh: '伴侣互动状态', en: 'Agent Interaction State' },
      '任务类型': { zh: '任务类型', en: 'Task Type' },
      '任务紧急度': { zh: '任务紧急度', en: 'Task Urgency' },
      // Also handle reverse mapping (English to translations)
      'Atmosphere': { zh: '环境氛围', en: 'Atmosphere' },
      'User Emotion': { zh: '用户情绪', en: 'User Emotion' },
      'Agent Energy': { zh: '伴侣能量值', en: 'Agent Energy' },
      'Agent Interaction State': { zh: '伴侣互动状态', en: 'Agent Interaction State' },
      'Task Type': { zh: '任务类型', en: 'Task Type' },
      'Task Urgency': { zh: '任务紧急度', en: 'Task Urgency' }
    };
    
    const translation = translations[name];
    if (translation) {
      return language === 'zh-CN' ? translation.zh : translation.en;
    }
    return name;
  };
  
  const [testInput, setTestInput] = useState('');
  const [contextInputs, setContextInputs] = useState({}); // 上下文输入
  const [testHistory, setTestHistory] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showSystemPrompt, setShowSystemPrompt] = useState(false);
  const [systemPrompt, setSystemPrompt] = useState('');
  const [showSvgCode, setShowSvgCode] = useState(false);
  const [selectedSvgCode, setSelectedSvgCode] = useState('');
  
  // 获取当前系统设置的LLM配置
  const [currentLLMConfig, setCurrentLLMConfig] = useState(systemSettings.getLLMSettings());

  // 获取角色生成配置
  const roleConfig = version?.roleGenerationConfig;
  const isRoleContextMode = version?.type === 'role' && roleConfig?.mode === 'context';
  
  // 🔧 获取表情生成配置
  const expressionConfig = version?.expressionGenerationConfig;
  const isExpressionContextMode = version?.type === 'expression' && expressionConfig?.mode === 'context';
  
  // 组合的上下文模式判断
  const isContextMode = isRoleContextMode || isExpressionContextMode;
  
  // 上下文输入变更处理
  const handleContextInputChange = useCallback((contextId, value) => {
    setContextInputs(prev => ({
      ...prev,
      [contextId]: value
    }));
  }, []);

  // 🔧 检查输入是否有效 - 支持表情变换模式
  const isInputValid = useCallback(() => {
    if (version?.type === 'role') {
      if (isRoleContextMode) {
        // 角色上下文模式：检查是否所有上下文都有输入
        return roleConfig?.contextDefinitions?.every(def => 
          contextInputs[def.id] && contextInputs[def.id].trim()
        ) || false;
      } else {
        // 角色直接输入模式
        return testInput.trim();
      }
    } else if (version?.type === 'expression') {
      if (isExpressionContextMode) {
        // 表情上下文模式：检查是否所有上下文都有输入
        return expressionConfig?.contextDefinitions?.every(def => 
          contextInputs[def.id] && contextInputs[def.id].trim()
        ) || false;
      } else {
        // 表情直接输入模式
        return testInput.trim();
      }
    }
    return false;
  }, [version, testInput, contextInputs, isRoleContextMode, roleConfig, isExpressionContextMode, expressionConfig]);


  // 监听系统设置变更
  useEffect(() => {
    const unsubscribe = systemSettings.addChangeListener((newSettings) => {
      setCurrentLLMConfig(newSettings.llm);
    });
    
    return unsubscribe;
  }, []);

  // 获取系统提示词
  const handleViewSystemPrompt = useCallback(async () => {
    try {
      // 🔧 准备测试输入数据 - 支持表情变换模式
      let testInputData;
      
      if (version?.type === 'role') {
        if (isRoleContextMode) {
          // 角色上下文模式
          const hasValidInputs = roleConfig?.contextDefinitions?.some(def => 
            contextInputs[def.id] && contextInputs[def.id].trim()
          );
          
          if (hasValidInputs) {
            testInputData = {
              mode: 'context',
              contextInputs: contextInputs,
              contextDefinitions: roleConfig?.contextDefinitions || [],
              contextMappingRules: roleConfig?.contextMappingRules || ''
            };
          } else {
            // 使用示例数据
            const exampleInputs = {};
            roleConfig?.contextDefinitions?.forEach(def => {
              exampleInputs[def.id] = `示例${def.name}`;
            });
            testInputData = {
              mode: 'context',
              contextInputs: exampleInputs,
              contextDefinitions: roleConfig?.contextDefinitions || [],
              contextMappingRules: roleConfig?.contextMappingRules || ''
            };
          }
        } else {
          // 角色直接输入模式
          testInputData = {
            mode: 'direct',
            content: testInput.trim() || '生成一个友善可爱的卡通角色，默认具有自然的肉色皮肤色调，生动的面部表情和丰富的细节特征'
          };
        }
      } else if (version?.type === 'expression') {
        if (isExpressionContextMode) {
          // 表情上下文模式
          const hasValidInputs = expressionConfig?.contextDefinitions?.some(def => 
            contextInputs[def.id] && contextInputs[def.id].trim()
          );
          
          if (hasValidInputs) {
            testInputData = {
              mode: 'context',
              contextInputs: contextInputs,
              contextDefinitions: expressionConfig?.contextDefinitions || [],
              contextMappingRules: expressionConfig?.contextMappingRules || ''
            };
          } else {
            // 使用示例数据
            const exampleInputs = {};
            expressionConfig?.contextDefinitions?.forEach(def => {
              exampleInputs[def.id] = `示例${def.name}`;
            });
            testInputData = {
              mode: 'context',
              contextInputs: exampleInputs,
              contextDefinitions: expressionConfig?.contextDefinitions || [],
              contextMappingRules: expressionConfig?.contextMappingRules || ''
            };
          }
        } else {
          // 表情直接输入模式
          testInputData = {
            mode: 'direct',
            content: testInput.trim() || '展现开心愉悦的表情'
          };
        }
      }

      const response = await fetch(`${getSmartBackendUrl()}/api/designer/system-prompt`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          projectId: project.id,
          versionId: version.id,
          testInput: testInputData,
          currentEditorData: currentEditorData
        })
      });

      if (!response.ok) {
        throw new Error(`获取系统提示词失败: ${response.status}`);
      }

      const result = await response.json();
      if (result.success) {
        setSystemPrompt(result.systemPrompt);
        setShowSystemPrompt(true);
      } else {
        throw new Error(result.error || '获取系统提示词失败');
      }
    } catch (error) {
      console.error('获取系统提示词失败:', error);
      alert(`获取系统提示词失败: ${error.message}`);
    }
  }, [project, version, testInput, contextInputs, isContextMode, roleConfig, currentEditorData]);

  // 🔧 执行测试（流式版本）- 支持表情变换模式
  const handleRunTest = useCallback(async () => {
    if (!isInputValid()) {
      const alertMessage = (isRoleContextMode || isExpressionContextMode) ? 
        '请填写所有上下文信息' : '请输入测试内容';
      alert(alertMessage);
      return;
    }

    // 🔥 测试前保存当前编辑状态
    if (onBeforeTest) {
      try {
        await onBeforeTest();
      } catch (error) {
        console.error('测试前保存失败:', error);
        // 继续执行测试，但提醒用户
        alert('保存编辑状态时出现警告，测试将继续进行');
      }
    }

    setIsLoading(true);
    const testStartTime = Date.now();

    // 🔧 构建测试记录的输入显示文本 - 支持表情变换模式
    let inputDisplay;
    if (isRoleContextMode) {
      const contextSummary = Object.entries(contextInputs)
        .map(([contextId, value]) => {
          const definition = roleConfig?.contextDefinitions?.find(def => def.id === contextId);
          return `${definition?.name || contextId}: ${value?.slice(0, 50)}${value?.length > 50 ? '...' : ''}`;
        })
        .join('; ');
      inputDisplay = `[角色上下文模式] ${contextSummary}`;
    } else if (isExpressionContextMode) {
      const contextSummary = Object.entries(contextInputs)
        .map(([contextId, value]) => {
          const definition = expressionConfig?.contextDefinitions?.find(def => def.id === contextId);
          return `${definition?.name || contextId}: ${value?.slice(0, 50)}${value?.length > 50 ? '...' : ''}`;
        })
        .join('; ');
      inputDisplay = `[表情上下文模式] ${contextSummary}`;
    } else {
      inputDisplay = testInput.trim();
    }

    // 立即创建test-record并添加到历史记录
    const testRecord = {
      id: `test_${Date.now()}`,
      input: inputDisplay,
      output: '', // 初始为空，流式更新
      svgResult: '', // 初始为空，流式更新
      provider: currentLLMConfig.provider,
      model: currentLLMConfig.model,
      duration: null, // 完成时填充
      timestamp: new Date().toISOString(),
      success: null, // 完成时填充
      status: 'running', // 添加状态标识
      progress: '开始生成...'
    };

    // 立即将记录添加到历史，这样用户可以看到测试开始了
    setTestHistory(prev => [testRecord, ...prev]);

    try {
      // 准备测试输入数据
      let testInputData;
      if (isContextMode) {
        // 上下文模式：组织上下文数据
        testInputData = {
          mode: 'context',
          contextInputs: contextInputs,
          contextDefinitions: roleConfig?.contextDefinitions || [],
          contextMappingRules: roleConfig?.contextMappingRules || ''
        };
      } else {
        // 直接输入模式
        testInputData = {
          mode: 'direct',
          content: testInput.trim()
        };
      }

      const testData = {
        projectId: project.id,
        versionId: version.id,
        testInput: testInputData,
        provider: currentLLMConfig.provider,
        model: currentLLMConfig.model,
        type: 'role',
        timestamp: new Date().toISOString(),
        currentEditorData: currentEditorData
      };

      // 使用流式传输接口
      const response = await fetch(`${getSmartBackendUrl()}/api/designer/test-current-stream`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(testData)
      });

      if (!response.ok) {
        throw new Error(`测试请求失败: ${response.status}`);
      }

      // 处理流式响应
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let currentSvg = '';

      while (true) {
        const { done, value } = await reader.read();
        
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        const lines = chunk.split('\n');

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = line.slice(6).trim();
            
            if (data === '[DONE]') {
              continue;
            }

            try {
              const parsed = JSON.parse(data);
              
              if (parsed.type === 'start') {
                // 更新进度
                setTestHistory(prev => prev.map(record => 
                  record.id === testRecord.id 
                    ? { ...record, progress: parsed.message }
                    : record
                ));
              } else if (parsed.type === 'progress') {
                // 更新进度
                setTestHistory(prev => prev.map(record => 
                  record.id === testRecord.id 
                    ? { ...record, progress: parsed.message }
                    : record
                ));
              } else if (parsed.type === 'svg_chunk') {
                // 累积SVG内容并实时更新
                currentSvg += parsed.chunk;
                setTestHistory(prev => prev.map(record => 
                  record.id === testRecord.id 
                    ? { 
                        ...record, 
                        svgResult: currentSvg,
                        output: currentSvg,
                        progress: parsed.message || '实时生成SVG中...'
                      }
                    : record
                ));
              } else if (parsed.type === 'complete') {
                // 完成
                const testDuration = Date.now() - testStartTime;
                setTestHistory(prev => prev.map(record => 
                  record.id === testRecord.id 
                    ? { 
                        ...record, 
                        output: parsed.output,
                        svgResult: parsed.svgResult,
                        duration: testDuration,
                        success: parsed.success,
                        status: 'completed',
                        progress: parsed.message || '生成完成'
                      }
                    : record
                ));

                // 通知父组件测试完成
                if (onTestComplete) {
                  onTestComplete({
                    ...testRecord,
                    output: parsed.output,
                    svgResult: parsed.svgResult,
                    duration: testDuration,
                    success: parsed.success
                  });
                }
              } else if (parsed.type === 'error') {
                // 错误处理
                setTestHistory(prev => prev.map(record => 
                  record.id === testRecord.id 
                    ? { 
                        ...record, 
                        success: false,
                        status: 'error',
                        progress: parsed.message || '生成失败',
                        error: parsed.error
                      }
                    : record
                ));
              }
            } catch (parseError) {
              console.warn('解析流式数据失败:', parseError);
            }
          }
        }
      }

      // 清空输入框
      if (isContextMode) {
        setContextInputs({});
      } else {
        setTestInput('');
      }

    } catch (error) {
      console.error('流式测试执行失败:', error);
      
      // 更新测试记录为失败状态
      setTestHistory(prev => prev.map(record => 
        record.id === testRecord.id 
          ? { 
              ...record, 
              success: false,
              status: 'error',
              progress: `测试失败: ${error.message}`,
              error: error.message,
              duration: Date.now() - testStartTime
            }
          : record
      ));
    } finally {
      setIsLoading(false);
    }
  }, [testInput, contextInputs, isContextMode, roleConfig, project, version, currentLLMConfig.provider, currentLLMConfig.model, onTestComplete, currentEditorData, isInputValid, onBeforeTest]);

  // 清空测试历史
  const handleClearHistory = useCallback(() => {
    if (window.confirm('确定要清空测试历史吗？')) {
      setTestHistory([]);
    }
  }, []);

  // 格式化时间显示
  const formatTime = useCallback((timestamp) => {
    return new Date(timestamp).toLocaleString('zh-CN', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    });
  }, []);

  // 查看SVG代码
  const handleViewSvgCode = useCallback((svgCode) => {
    setSelectedSvgCode(svgCode);
    setShowSvgCode(true);
  }, []);

  // 关闭SVG代码查看
  const handleCloseSvgCode = useCallback(() => {
    setShowSvgCode(false);
    setSelectedSvgCode('');
  }, []);

  // 查看测试用例的系统提示词
  const handleViewTestPrompt = useCallback((systemPrompt) => {
    setSystemPrompt(systemPrompt);
    setShowSystemPrompt(true);
  }, []);

  return (
    <div className="test-interface">
      <div className="test-header">
        <div className="test-title">
          <h3>测试模式</h3>
          <p>项目: {project.name} - 版本 {version.versionNumber}</p>
        </div>
        <div className="test-stats">
          <span className="stat-item">总测试: {testHistory.length}</span>
          <span className="stat-item">成功: {testHistory.filter(t => t.success).length}</span>
          <span className="stat-item">失败: {testHistory.filter(t => !t.success).length}</span>
        </div>
      </div>

      <div className="test-content">
        {/* 测试输入区域 */}
        <div className="test-input-section">
          <div className="input-header">
            <h4>测试输入</h4>
            <div className="current-model-display">
              <span className="model-info-label">当前使用模型：</span>
              <span className="model-info-value">
                {currentLLMConfig.model}
                <span className="model-provider">({currentLLMConfig.provider})</span>
              </span>
            </div>
          </div>
          
          {/* 🔧 动态输入区域 - 支持表情变换模式 */}
          {isRoleContextMode ? (
            // 角色上下文模式：多个输入框
            <div className="context-inputs">
              <div className="context-inputs-header">
                <span className="context-inputs-label">请填写以下角色上下文信息：</span>
              </div>
              {roleConfig?.contextDefinitions?.map((definition) => (
                <div key={definition.id} className="context-input-item">
                  <label className="context-label">{getContextDisplayName(definition.name)}:</label>
                  <textarea
                    value={contextInputs[definition.id] || ''}
                    onChange={(e) => handleContextInputChange(definition.id, e.target.value)}
                    placeholder={language === 'zh-CN' ? `输入${getContextDisplayName(definition.name)}相关信息...` : `Enter ${getContextDisplayName(definition.name)} related information...`}
                    className="context-textarea"
                    rows={3}
                    disabled={isLoading}
                  />
                </div>
              ))}
              {(!roleConfig?.contextDefinitions || roleConfig.contextDefinitions.length === 0) && (
                <div className="no-context-hint">
                  请先在规则编辑器中配置角色上下文定义
                </div>
              )}
            </div>
          ) : isExpressionContextMode ? (
            // 表情上下文模式：多个输入框
            <div className="context-inputs">
              <div className="context-inputs-header">
                <span className="context-inputs-label">请填写以下表情上下文信息：</span>
              </div>
              {expressionConfig?.contextDefinitions?.map((definition) => (
                <div key={definition.id} className="context-input-item">
                  <label className="context-label">{getContextDisplayName(definition.name)}:</label>
                  <textarea
                    value={contextInputs[definition.id] || ''}
                    onChange={(e) => handleContextInputChange(definition.id, e.target.value)}
                    placeholder={language === 'zh-CN' ? `输入${getContextDisplayName(definition.name)}相关信息...` : `Enter ${getContextDisplayName(definition.name)} related information...`}
                    className="context-textarea"
                    rows={3}
                    disabled={isLoading}
                  />
                </div>
              ))}
              {(!expressionConfig?.contextDefinitions || expressionConfig.contextDefinitions.length === 0) && (
                <div className="no-context-hint">
                  请先在规则编辑器中配置表情上下文定义
                </div>
              )}
            </div>
          ) : (
            // 🔧 直接输入模式 - 根据版本类型显示不同提示
            <textarea
              value={testInput}
              onChange={(e) => setTestInput(e.target.value)}
              placeholder={version?.type === 'role' ? 
                '输入角色描述，例如：一个友善的圣诞老人，有着温暖的笑容' : 
                '输入情感描述，例如：开心、生气、惊讶、悲伤等表情状态'
              }
              className="test-input"
              rows={4}
              disabled={isLoading}
            />
          )}
          
          <div className="input-actions">
            <div className="action-buttons">
              <button 
                onClick={handleRunTest} 
                className="run-test-btn"
                disabled={isLoading || !isInputValid()}
              >
                {isLoading ? '测试中...' : '运行测试'}
              </button>
              <button 
                onClick={handleViewSystemPrompt} 
                className="view-prompt-btn"
                disabled={isLoading}
              >
                查看系统提示词
              </button>
            </div>
            {!isContextMode && (
              <span className="input-counter">
                {testInput.length} 字符
              </span>
            )}
          </div>
        </div>

        {/* 测试历史区域 */}
        <div className="test-history-section">
          <div className="history-header">
            <h4>测试历史</h4>
            {testHistory.length > 0 && (
              <button 
                onClick={handleClearHistory} 
                className="clear-history-btn"
              >
                清空历史
              </button>
            )}
          </div>
          
          <div className="test-history">
            {testHistory.length === 0 ? (
              <div className="empty-history">
                <p>暂无测试记录</p>
                <p>运行测试后，结果将在这里显示</p>
              </div>
            ) : (
              testHistory.map(test => (
                <div key={test.id} className={`test-record ${
                  test.status === 'running' ? 'running' : 
                  test.status === 'error' ? 'error' : 
                  test.success === true ? 'success' : 
                  test.success === false ? 'error' : 'running'
                }`}>
                  <div className="record-header">
                    <div className="record-info">
                      <span className="record-time">{formatTime(test.timestamp)}</span>
                      <span className="record-model">{test.model}</span>
                      <span className="record-duration">
                        {test.duration ? `${test.duration}ms` : '进行中...'}
                      </span>
                      <span className={`record-status ${
                        test.status === 'running' ? 'running' : 
                        test.status === 'error' ? 'error' : 
                        test.success === true ? 'success' : 
                        test.success === false ? 'error' : 'running'
                      }`}>
                        {test.status === 'running' ? '生成中...' : 
                         test.status === 'error' ? '失败' :
                         test.success === true ? '成功' : 
                         test.success === false ? '失败' : '生成中...'}
                      </span>
                    </div>
                    {/* 显示实时进度 */}
                    {(test.status === 'running' || test.progress) && (
                      <div className="record-progress">
                        <span className="progress-text">{test.progress}</span>
                        <div className="progress-bar">
                          <div className="progress-fill"></div>
                        </div>
                      </div>
                    )}
                  </div>
                  
                  <div className="record-content">
                    <div className="record-input">
                      <strong>输入:</strong>
                      <p>{test.input}</p>
                    </div>
                    
                    {/* 根据状态显示不同内容 */}
                    {test.status === 'running' ? (
                      <div className="record-loading">
                        <strong>状态:</strong>
                        <p>正在生成中，请稍候...</p>
                        {test.svgResult && (
                          <div className="record-svg streaming">
                            <div className="svg-header">
                              <strong>SVG预览 (实时生成):</strong>
                            </div>
                            <div className="svg-preview streaming" dangerouslySetInnerHTML={{ __html: test.svgResult }} />
                          </div>
                        )}
                      </div>
                    ) : test.status === 'error' || test.success === false ? (
                      <div className="record-error">
                        <strong>错误:</strong>
                        <p>{test.error || '生成失败'}</p>
                      </div>
                    ) : test.success === true ? (
                      <>
                        <div className="record-output">
                          <strong>输出:</strong>
                          <p>{test.output}</p>
                        </div>
                        {test.svgResult && (
                          <div className="record-svg">
                            <div className="svg-header">
                              <strong>SVG结果:</strong>
                              <div className="svg-header-buttons">
                                <button 
                                  onClick={() => handleViewSvgCode(test.svgResult)}
                                  className="view-svg-code-btn"
                                  title="查看SVG代码"
                                >
                                  查看SVG代码
                                </button>
                                {test.systemPrompt && (
                                  <button 
                                    onClick={() => handleViewTestPrompt(test.systemPrompt)}
                                    className="view-test-prompt-btn"
                                    title="查看此测试用例的系统提示词"
                                  >
                                    查看提示词
                                  </button>
                                )}
                              </div>
                            </div>
                            <div className="svg-preview" dangerouslySetInnerHTML={{ __html: test.svgResult }} />
                          </div>
                        )}
                      </>
                    ) : (
                      <div className="record-pending">
                        <strong>状态:</strong>
                        <p>准备中...</p>
                      </div>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>

      {/* 系统提示词模态框 */}
      {showSystemPrompt && (
        <div className="modal-overlay" onClick={() => setShowSystemPrompt(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>系统提示词预览</h3>
              <button 
                onClick={() => setShowSystemPrompt(false)}
                className="modal-close-btn"
              >
                ×
              </button>
            </div>
            <div className="modal-body">
              <div className="prompt-info">
                <div className="prompt-meta">
                  <span>项目: {project.name}</span>
                  <span>版本: {version.versionNumber}</span>
                  <span>版本号: {version.versionNumber}</span>
                </div>
              </div>
              <div className="prompt-content">
                <pre>{systemPrompt}</pre>
              </div>
              <div className="modal-actions">
                <button 
                  onClick={() => {
                    navigator.clipboard.writeText(systemPrompt);
                    alert('系统提示词已复制到剪贴板');
                  }}
                  className="copy-btn"
                >
                  复制提示词
                </button>
                <button 
                  onClick={() => setShowSystemPrompt(false)}
                  className="close-btn"
                >
                  关闭
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* SVG代码查看模态框 */}
      {showSvgCode && (
        <div className="modal-overlay" onClick={handleCloseSvgCode}>
          <div className="modal-content svg-code-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>SVG代码预览</h3>
              <button 
                onClick={handleCloseSvgCode}
                className="modal-close-btn"
              >
                ×
              </button>
            </div>
            <div className="modal-body">
              <div className="svg-code-content">
                <div className="code-section">
                  <h4>SVG代码</h4>
                  <pre className="svg-code"><code>{selectedSvgCode}</code></pre>
                </div>
                <div className="preview-section">
                  <h4>预览效果</h4>
                  <div className="svg-preview-large" dangerouslySetInnerHTML={{ __html: selectedSvgCode }} />
                </div>
              </div>
              <div className="modal-actions">
                <button 
                  onClick={() => {
                    navigator.clipboard.writeText(selectedSvgCode);
                    alert('SVG代码已复制到剪贴板');
                  }}
                  className="copy-btn"
                >
                  复制SVG代码
                </button>
                <button 
                  onClick={handleCloseSvgCode}
                  className="close-btn"
                >
                  关闭
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default TestInterface;
