    const parentWidth = parentElement.clientWidth;
    const parentHeight = parentElement.clientHeight;
    
    // 计算宽度和高度的缩放比例
    const widthRatio = parentWidth / containerWidth;
    const heightRatio = parentHeight / containerHeight;
    
    // 使用较小的比例确保完全适应窗口
