import React, { useEffect, useRef, useState } from 'react';
import { getSmartBackendUrl } from '../utils/env';
import './TemiPage.css';
import CustomizePopup from '../components/CustomizePopup';

const API_BASE_URL = getSmartBackendUrl();

function ServiceRobotPage() {
  const [config, setConfig] = useState(null);
  const [currentSvg, setCurrentSvg] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [chatMessages, setChatMessages] = useState([]);
  const [showCustomize, setShowCustomize] = useState(false);
  const [voiceError, setVoiceError] = useState('');
  const containerRef = useRef(null);

  // 拉伸SVG以填满容器（不保持比例）
  const stretchSvgContent = (svg) => {
    if (typeof svg !== 'string' || svg.indexOf('<svg') === -1) return svg;
    let out = svg;
    // 规范化开标签：强制 width/height=100% 且 preserveAspectRatio="none"
    out = out.replace(/<svg([^>]*)>/i, (m, attrs) => {
      let a = attrs;
      // 去掉多余空白
      a = a.replace(/\s+/g, ' ').trim();
      // width/height 统一为100%
      if (/\bwidth\s*=\s*"[^"]*"/i.test(a)) a = a.replace(/\bwidth\s*=\s*"[^"]*"/i, 'width="100%"');
      else a += ' width="100%"';
      if (/\bheight\s*=\s*"[^"]*"/i.test(a)) a = a.replace(/\bheight\s*=\s*"[^"]*"/i, 'height="100%"');
      else a += ' height="100%"';
      // preserveAspectRatio 设置为 none
      if (/\bpreserveAspectRatio\s*=\s*"[^"]*"/i.test(a)) a = a.replace(/\bpreserveAspectRatio\s*=\s*"[^"]*"/i, 'preserveAspectRatio="none"');
      else a += ' preserveAspectRatio="none"';
      return `<svg ${a}>`;
    });
    return out;
  };

  // Load current-device-config
  useEffect(() => {
    const loadConfig = async () => {
      try {
        const resp = await fetch(`${API_BASE_URL}/api/designer/current-device-config`);
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const data = await resp.json();
        if (!data.config) throw new Error('No configuration');
        setConfig(data.config);
        if (Array.isArray(data.config.chatMessages)) setChatMessages(data.config.chatMessages);
      } catch (e) {
        console.error('Failed to load device config:', e);
      }
    };
    loadConfig();
  }, []);

  // Generate base expression using direct mode role description
  useEffect(() => {
    const run = async () => {
      if (!config || currentSvg) return;
      try {
        setIsProcessing(true);
        const roleConfig = config.systemPrompts?.roleConfig;
        const inputText = config.systemPrompts?.basicTestInput || 'Generate a friendly and cute service robot with clear expressions and details';

        const body = {
          projectId: config.project?.id,
          versionId: config.version?.id,
          testInput: roleConfig?.mode === 'direct' ? inputText : inputText,
          provider: config.llmConfig?.provider || 'claude',
          model: config.llmConfig?.model || 'claude-sonnet-4-6',
          temperature: config.llmConfig?.temperature || 0,
          currentEditorData: config.currentEditorData,
          type: 'role'
        };

        const response = await fetch(`${API_BASE_URL}/api/designer/test-current-stream`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body)
        });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);

        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';
        let finalSvg = '';
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';
          for (const line of lines) {
            if (line.startsWith('data: ') && !line.includes('[DONE]')) {
              try {
                const data = JSON.parse(line.slice(6));
                if (data.type === 'final_result' && data.svgCode) {
                  finalSvg = data.svgCode;
                  // 最终结果到达时也及时渲染
                  setCurrentSvg(stretchSvgContent(finalSvg));
                } else if (data.type === 'complete' && data.success && (data.svg_result || data.svgCode)) {
                  // 兼容complete事件
                  finalSvg = data.svg_result || data.svgCode;
                  setCurrentSvg(stretchSvgContent(finalSvg));
                } else if (data.type === 'svg_partial' && data.content) {
                  // 实时渲染流式SVG
                  finalSvg = data.content;
                  setCurrentSvg(stretchSvgContent(finalSvg));
                }
              } catch {}
            }
          }
        }
        // 兜底：若未在循环中渲染，则在结束时渲染最终内容
        if (finalSvg) setCurrentSvg(stretchSvgContent(finalSvg));
      } catch (e) {
        console.error('Failed to generate base expression:', e);
      } finally {
        setIsProcessing(false);
      }
    };
    run();
  }, [config, currentSvg]);

  // 使用Temi语音API进行交互（与 /temi 一致的交互思路）
  const handleMicClick = async () => {
    try {
      setIsListening(true);
      setVoiceError('');
      const resp = await fetch(`${API_BASE_URL}/api/voiceInput`, { method: 'POST' });
      if (!resp.ok) {
        const t = await resp.text().catch(() => '');
        throw new Error(`HTTP ${resp.status} ${t}`);
      }
      const data = await resp.json();
      const text = data?.result || '';
      if (text) await handleChatAndVary(text);
    } catch (e) {
      console.error('Temi voice interface failed:', e);
      setVoiceError(e.message || String(e));
    } finally {
      setIsListening(false);
    }
  };

  const handleChatAndVary = async (text) => {
    if (!config || !currentSvg || isProcessing) return;
    setIsProcessing(true);
    try {
      const userMessage = { role: 'user', content: text };
      let dialogue = [...chatMessages, userMessage];

      // 先获取AI回复
      const chatResp = await fetch(`${API_BASE_URL}/api/designer/chat`, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          messages: dialogue,
          provider: config.llmConfig?.provider || 'claude',
          model: config.llmConfig?.model || 'claude-sonnet-4-6',
          extendedThinking: false,
          temperature: config.llmConfig?.temperature ?? 0.7
        })
      });
      if (!chatResp.ok) throw new Error(`chat HTTP ${chatResp.status}`);
      const chatJson = await chatResp.json();
      const aiText = chatJson?.message || '';
      dialogue = [...dialogue, { role: 'assistant', content: aiText }];
      setChatMessages(prev => [...prev, userMessage, { type: 'assistant', content: aiText }]);
      // 播报AI回复
      try {
        await fetch(`${API_BASE_URL}/api/speak`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: aiText }) });
      } catch {}

      // 再进行表情变化
      const response = await fetch(`${API_BASE_URL}/api/designer/test-expression-vary-stream`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          projectId: config.project?.id,
          versionId: config.version?.id,
          messages: dialogue,
          baseExpression: currentSvg,
          provider: config.llmConfig?.provider || 'claude',
          model: config.llmConfig?.model || 'claude-sonnet-4-6',
          temperature: config.llmConfig?.temperature ?? 0,
          currentEditorData: config.currentEditorData,
          expressionMode: 'dialogue-context',
          expressionGenerationConfig: {
            mode: 'context',
            contextMappingRules: 'Understand dialogue context and emotions to generate corresponding facial expression changes',
            contextDefinitions: [{ id: 'dialogue', name: 'Dialogue content' }]
          }
        })
      });
      if (!response.ok) throw new Error(`vary HTTP ${response.status}`);

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let finalSvg = '';
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';
        for (const line of lines) {
          if (line.startsWith('data: ') && !line.includes('[DONE]')) {
            try {
              const data = JSON.parse(line.slice(6));
              if (data.type === 'final_result' && data.svgCode) {
                finalSvg = data.svgCode;
                // 最终结果也同步渲染
                setCurrentSvg(stretchSvgContent(finalSvg));
              } else if (data.type === 'complete' && data.success && (data.svg_result || data.svgCode)) {
                // 兼容complete事件
                finalSvg = data.svg_result || data.svgCode;
                setCurrentSvg(stretchSvgContent(finalSvg));
              } else if (data.type === 'svg_partial' && data.content) {
                // 实时渲染流式片段（完整SVG快照）
                finalSvg = data.content;
                setCurrentSvg(stretchSvgContent(finalSvg));
              }
            } catch {}
          }
        }
      }
      if (finalSvg) setCurrentSvg(stretchSvgContent(finalSvg));
    } catch (e) {
      console.error('Expression change failed:', e);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleExpressionGenerated = (expression) => {
    if (expression?.code) setCurrentSvg(stretchSvgContent(expression.code));
  };

  return (
    <div className="temi-page service-robot" ref={containerRef}>
      <div className="canvas-container">
        {currentSvg ? (
          <div className="svg-container" dangerouslySetInnerHTML={{ __html: currentSvg }} />
        ) : (
          <div style={{ color: '#fff' }}>Generating base expression...</div>
        )}
      </div>

      <div className="bottom-controls">
        <button
          className={`voice-button ${isListening ? 'listening' : ''}`}
          onClick={handleMicClick}
          disabled={isProcessing}
          title={isListening ? 'Listening' : 'Click to speak'}
        >
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
            <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zm5.91-3c-.49 0-.9.36-.98.85C16.52 14.2 14.47 16 12 16s-4.52-1.8-4.93-4.15c-.08-.49-.49-.85-.98-.85-.61 0-1.09.54-1 1.14.49 3 2.89 5.35 5.91 5.78V20c0 .55.45 1 1 1s1-.45 1-1v-2.08c3.02-.43 5.42-2.78 5.91-5.78.1-.6-.39-1.14-1-1.14z"/>
          </svg>
          {isListening && <span className="pulse-animation"></span>}
        </button>

        <button className="customize-button" onClick={() => setShowCustomize(true)} title="Customize role">
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
            <path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04a1.004 1.004 0 0 0 0-1.42L18.37 3.29a1.004 1.004 0 1 0-1.42 1.42l2.34 2.33c.39.39 1.03.39 1.42 0z"/>
          </svg>
        </button>
      </div>

      {voiceError && (
        <div className="voice-error">{voiceError}</div>
      )}

      {showCustomize && (
        <CustomizePopup
          onClose={() => setShowCustomize(false)}
          onExpressionGenerated={handleExpressionGenerated}
          customGenerate={async (text) => {
            // 调用设计师pipeline生成基础表情
            if (!config) throw new Error('Config not loaded');
            const body = {
              projectId: config.project?.id,
              versionId: config.version?.id,
              testInput: text,
              provider: config.llmConfig?.provider || 'claude',
              model: config.llmConfig?.model || 'claude-sonnet-4-6',
              temperature: config.llmConfig?.temperature || 0,
              currentEditorData: config.currentEditorData,
              type: 'role'
            };
            const response = await fetch(`${API_BASE_URL}/api/designer/test-current-stream`, {
              method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
            });
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            const reader = response.body.getReader();
            const decoder = new TextDecoder();
            let buffer = '';
            let finalSvg = '';
            while (true) {
              const { done, value } = await reader.read();
              if (done) break;
              buffer += decoder.decode(value, { stream: true });
              const lines = buffer.split('\n');
              buffer = lines.pop() || '';
              for (const line of lines) {
                if (line.startsWith('data: ') && !line.includes('[DONE]')) {
                  try {
                    const data = JSON.parse(line.slice(6));
                    if (data.type === 'final_result' && data.svgCode) {
                      finalSvg = data.svgCode;
                      // 最终结果也立即渲染
                      setCurrentSvg(stretchSvgContent(finalSvg));
                    } else if (data.type === 'svg_partial' && data.content) {
                      finalSvg = data.content;
                      // 实时渲染生成中的SVG，便于预览
                      setCurrentSvg(stretchSvgContent(finalSvg));
                    }
                  } catch {}
                }
              }
            }
            if (finalSvg) return { code: stretchSvgContent(finalSvg) };
            throw new Error('Failed to generate SVG');
          }}
        />
      )}
      {/* 强制覆盖TemiPage.css中的contain行为，改为拉伸填满 */}
      <style>{`
        .service-robot .svg-container svg {
          width: 100% !important;
          height: 100% !important;
        }
      `}</style>
    </div>
  );
}

export default ServiceRobotPage;
