import React, { useState, useEffect, useRef } from 'react';
import { useLanguage } from '../contexts/LanguageContext';
import './ExpressionDisplay.css';
import { getSmartBackendUrl } from '../utils/env';
import CodePopup from './CodePopup';

// 确保API基础URL正确格式化
const API_BASE_URL = getSmartBackendUrl();

// 调试信息
const debug = {
  log: (action, message, data = null) => {
    console.log(`[${new Date().toISOString()}] ${action}:`, message, data);
  },
  error: (action, error, context = null) => {
    console.error(
      `[${new Date().toISOString()}] Error in ${action}:`,
      '\nError:', error,
      '\nContext:', context
    );
  }
};

// 添加调试信息
debug.log('Config', '使用的API基础URL', API_BASE_URL);

// 默认SVG表情
const DEFAULT_SVG_EXPRESSION = `
<svg width="400" height="250" viewBox="0 0 400 250" fill="none" xmlns="http://www.w3.org/2000/svg">
  <defs>
    <radialGradient id="honeyGradient" cx="50%" cy="50%">
      <stop offset="0%" style="stop-color:#FFD700"/>
      <stop offset="100%" style="stop-color:#FFA500"/>
    </radialGradient>
    <filter id="furTexture">
      <feTurbulence type="fractalNoise" baseFrequency="0.08" numOctaves="1" result="turbulence"/>
      <feColorMatrix in="turbulence" type="saturate" values="0"/>
      <feComponentTransfer>
        <feFuncA type="discrete" tableValues="0 0.1 0.1 0.1 0.1"/>
      </feComponentTransfer>
      <feComposite operator="over" in2="SourceGraphic"/>
    </filter>
  </defs>

  <g id="robot face">
    <rect id="background" width="400" height="250" fill="url(#honeyGradient)" filter="url(#furTexture)"/>

    <g id="vest">
      <path d="M 0 200 L 0 250 L 400 250 L 400 200 L 300 200 L 250 220 L 200 230 L 150 220 L 100 200 Z" fill="#DC143C"/>
      <path d="M 100 200 L 150 220 L 200 230 L 250 220 L 300 200" stroke="#8B0000" stroke-width="2" fill="none"/>
    </g>

    <g id="face">
      <path id="mouth" d="M 170 195 Q 200 205 230 195" stroke="#8B4513" stroke-width="3" fill="none" stroke-linecap="round"/>
      
      <circle id="lefteye" cx="110.5" cy="108.5" r="37.5" fill="#000000"/>
      <circle cx="120" cy="100" r="8" fill="white"/>

      <circle id="righteye" cx="290.5" cy="108.5" r="37.5" fill="#000000"/>
      <circle cx="300" cy="100" r="8" fill="white"/>

      <circle id="nose" cx="200.5" cy="145.5" r="15" fill="#000000"/>
    </g>
  </g>
</svg>
`;

const SVGExpressionDisplay = () => {
  const { t } = useLanguage();
  const [currentExpression, setCurrentExpression] = useState({ code: DEFAULT_SVG_EXPRESSION });
  const [defaultExpression, setDefaultExpression] = useState({ code: DEFAULT_SVG_EXPRESSION });
  const [loading, setLoading] = useState(false);
  const [styleInput, setStyleInput] = useState('');
  const [error, setError] = useState(null);
  const [showCodeModal, setShowCodeModal] = useState(false);
  const [editingCode, setEditingCode] = useState('');
  const [isCodeModified, setIsCodeModified] = useState(false);
  const [extendedThinking, setExtendedThinking] = useState(false);
  const [thinking, setThinking] = useState(null);
  const [provider, setProvider] = useState('claude');
  const [model, setModel] = useState('');
  const [generationMode, setGenerationMode] = useState('角色初始化');
  const containerRef = useRef(null);

  // 根据提供商设置默认模型
  useEffect(() => {
    setModel(provider === 'claude' ? 'claude-sonnet-4-6' : 'mistral-medium');
  }, [provider]);

  // 计算并应用缩放比例
  const updateScaleFactor = () => {
    if (!containerRef.current) return;
    
    const containerWidth = 400;
    const containerHeight = 250;
    
    // 获取父容器的实际尺寸
    const parentElement = containerRef.current.parentElement;
    const parentWidth = parentElement.clientWidth;
    const parentHeight = parentElement.clientHeight;
    
    // 计算宽度和高度的缩放比例
    const widthRatio = parentWidth / containerWidth;
    const heightRatio = parentHeight / containerHeight;
    
    // 使用较小的比例确保完全适应窗口
    const scaleFactor = Math.min(widthRatio, heightRatio, 3); // 最大为3倍放大
    
    // 直接应用缩放到canvas-wrapper元素
    const canvasWrapper = containerRef.current;
    canvasWrapper.style.transform = `scale(${scaleFactor})`;
    
    // 调整容器高度以适应缩放后的内容
    if (parentElement) {
      parentElement.style.minHeight = `${250 * scaleFactor}px`;
    }
    
    console.log(`SVG Scaling: ${scaleFactor}, Parent: ${parentWidth}x${parentHeight}`);
  };

  // 监听窗口大小变化
  useEffect(() => {
    updateScaleFactor();
    window.addEventListener('resize', updateScaleFactor);
    return () => window.removeEventListener('resize', updateScaleFactor);
  }, []);

  // 验证API URL
  useEffect(() => {
    debug.log('Config', 'API Base URL', API_BASE_URL);
    if (!API_BASE_URL) {
      debug.error('Config', 'API Base URL is not configured');
      setError('Backend URL is not configured');
    }
    try {
      new URL(API_BASE_URL);
    } catch (e) {
      debug.error('Config', 'Invalid API Base URL', { url: API_BASE_URL, error: e });
      setError('Invalid backend URL configuration');
    }
  }, []);

  // 更新表情的函数
  const updateExpression = (newExpression) => {
    if (newExpression?.code) {
      debug.log('Expression Update', 'Updating expression with new SVG code', {
        codeLength: newExpression.code.length,
        provider,
        model
      });
      setCurrentExpression(newExpression);
    } else {
      debug.error('Expression Update', 'Invalid expression data received', {
        receivedData: newExpression
      });
    }
  };

  // 当打开模态窗口时，初始化编辑代码
  useEffect(() => {
    if (showCodeModal && currentExpression) {
      setEditingCode(currentExpression.code);
      setIsCodeModified(false);
    }
  }, [showCodeModal, currentExpression]);

  // 处理代码更改
  const handleCodeChange = (e) => {
    const newCode = e.target.value;
    setEditingCode(newCode);
    setIsCodeModified(newCode !== currentExpression?.code);
  };

  // 应用代码更改
  const applyCodeChanges = () => {
    if (isCodeModified && editingCode.trim()) {
      setCurrentExpression({
        ...currentExpression,
        code: editingCode
      });
      setShowCodeModal(false);
    }
  };

  // 生成新表情的函数
  const generateExpression = async () => {
    if (!styleInput.trim()) {
      setError('Please enter a style description');
      return;
    }

    if (!API_BASE_URL) {
      setError('Backend URL is not configured');
      return;
    }

    setLoading(true);
    setError(null);
    setThinking(null);

    try {
      debug.log('Request', 'Sending SVG expression request to', { 
        url: `${API_BASE_URL}/api/svg-expression`,
        extendedThinking,
        provider,
        model
      });

      const response = await fetch(`${API_BASE_URL}/api/svg-expression`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ 
          style: styleInput,
          extendedThinking,
          provider,
          model,
          generationMode,
          canvasSize: { width: 400, height: 250 } // 默认画布尺寸
        })
      });

      debug.log('Response', 'Received response', {
        status: response.status,
        ok: response.ok
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const data = await response.json();
      debug.log('Response', 'Parsed response data', {
        codeLength: data.expression.code.length,
        processingTime: data.processingTime,
        hasThinking: !!data.thinking
      });

      setCurrentExpression(data.expression);
      setDefaultExpression(data.expression);
      
      // 保存思考过程（如果有）
      if (data.thinking) {
        setThinking(data.thinking);
      }
    } catch (err) {
      debug.error('Request', err, {
        url: `${API_BASE_URL}/api/svg-expression`,
        input: styleInput
      });
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // 暴露更新表情的方法给父组件
  useEffect(() => {
    if (window) {
      window.updateExpression = updateExpression;
      window.getCurrentExpression = () => currentExpression;
      window.getDefaultExpression = () => defaultExpression;
      window.getExtendedThinking = () => extendedThinking;
      window.getExpressionProvider = () => provider;
      window.getExpressionModel = () => model;
    }
    return () => {
      if (window) {
        delete window.updateExpression;
        delete window.getCurrentExpression;
        delete window.getDefaultExpression;
        delete window.getExtendedThinking;
        delete window.getExpressionProvider;
        delete window.getExpressionModel;
      }
    };
  }, [currentExpression, defaultExpression, extendedThinking, provider, model]);

  return (
    <div className="expression-display">
      <div className="expression-header">
        <h2>SVG Expression Display</h2>
        <div className="expression-controls">
          <div className="model-selector">
            <select
              value={provider}
              onChange={(e) => setProvider(e.target.value)}
              disabled={loading}
            >
              <option value="claude">Claude</option>
              <option value="mistral">Mistral</option>
            </select>
            <select
              value={model}
              onChange={(e) => setModel(e.target.value)}
              disabled={loading}
            >
              {provider === 'claude' ? (
                <>
                  <option value="claude-sonnet-4-6">Claude Sonnet 4-6</option>
                  <option value="claude-opus-4-6">Claude Opus 4-6</option>
                </>
              ) : (
                <>
                  <option value="mistral-small">Mistral Small</option>
                  <option value="mistral-medium">Mistral Medium</option>
                  <option value="mistral-large">Mistral Large</option>
                  <option value="codestral-2501">Codestral 2501</option>
                </>
              )}
            </select>
          </div>
          <div className="extended-thinking-toggle">
            <label>
              <input
                type="checkbox"
                checked={extendedThinking}
                onChange={(e) => setExtendedThinking(e.target.checked)}
              />
              Enable Extended Thinking
            </label>
          </div>
          <div className="generation-mode-selector">
            <label>Generation Mode:</label>
            <select
              value={generationMode}
              onChange={(e) => setGenerationMode(e.target.value)}
            >
              <option value="角色初始化">角色初始化</option>
              <option value="表情变化">表情变化</option>
            </select>
          </div>
        </div>
      </div>
      
      <div className="style-input-container">
        <input
          type="text"
          value={styleInput}
          onChange={(e) => setStyleInput(e.target.value)}
          placeholder="Enter character description (e.g., 'SpongeBob', 'Santa Claus')"
          className="style-input"
          disabled={loading}
        />
        <button 
          onClick={generateExpression}
          className="generate-button"
          disabled={loading}
        >
          {loading ? t('expressionDisplay.generating') : 'Generate'}
        </button>
      </div>

      {error && (
        <div className="error-message">
          {error}
        </div>
      )}
      
      {thinking && (
        <div className="thinking-container">
          <div className="thinking-header">Extended Thinking:</div>
          <div className="thinking-content">{thinking}</div>
        </div>
      )}
      
      <div className="expression-container">
        <div className="canvas-wrapper" ref={containerRef}>
          <div 
            className="svg-container"
            dangerouslySetInnerHTML={{ __html: currentExpression.code }}
          />
          {loading && (
            <div className="loading-overlay">
              <div className="loading">{t('expressionDisplay.generating')}</div>
            </div>
          )}
        </div>
      </div>

      <div className="expression-controls">
        <div className="expression-status">
          Status: {loading ? t('expressionDisplay.generating') : currentExpression ? 'Ready' : 'Waiting for input'}
        </div>
        {currentExpression && (
          <button 
            onClick={() => setShowCodeModal(true)}
            className="view-code-button"
          >
            View Code
          </button>
        )}
      </div>

      {showCodeModal && (
        <CodePopup
          title="SVG Expression Code"
          code={editingCode}
          onClose={() => setShowCodeModal(false)}
          editable={true}
          onCodeChange={handleCodeChange}
          onApply={applyCodeChanges}
          isCodeModified={isCodeModified}
        />
      )}
    </div>
  );
};

export default SVGExpressionDisplay;