import React, { useState, useCallback, useRef, useEffect } from 'react';
import './SplitResizeHandle.css';

const SplitResizeHandle = ({ onResize, initialTopPercent = 50, minTopPercent = 20, maxTopPercent = 80 }) => {
  const [isDragging, setIsDragging] = useState(false);
  const [topPercent, setTopPercent] = useState(initialTopPercent);
  const startYRef = useRef(0);
  const startPercentRef = useRef(initialTopPercent);

  // 处理拖拽移动
  const handleMouseMove = useCallback((e) => {
    if (!isDragging) return;

    // 获取工作区域容器
    const workspace = document.querySelector('.designer-workspace.with-bottom-panel');
    if (!workspace) return;

    const containerRect = workspace.getBoundingClientRect();
    const containerHeight = containerRect.height;
    
    if (containerHeight === 0) return;

    const deltaY = e.clientY - startYRef.current;
    const deltaPercent = (deltaY / containerHeight) * 100;
    const newPercent = Math.min(
      Math.max(startPercentRef.current + deltaPercent, minTopPercent),
      maxTopPercent
    );

    setTopPercent(newPercent);
    onResize?.(newPercent);
  }, [isDragging, onResize, minTopPercent, maxTopPercent]);

  // 处理拖拽结束
  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
  }, []);

  // 处理拖拽开始
  const handleMouseDown = useCallback((e) => {
    e.preventDefault();
    setIsDragging(true);
    startYRef.current = e.clientY;
    startPercentRef.current = topPercent;
  }, [topPercent]);

  // 全局事件监听器
  useEffect(() => {
    if (isDragging) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'ns-resize';
      document.body.style.userSelect = 'none';
    } else {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    }

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };
  }, [isDragging, handleMouseMove, handleMouseUp]);

  return (
    <div 
      className={`split-resize-handle ${isDragging ? 'dragging' : ''}`}
      onMouseDown={handleMouseDown}
      title="拖拽调整画布与测试区域的高度比例"
    >
      <div className="resize-handle-indicator">
        <div className="resize-handle-line"></div>
        <div className="resize-handle-line"></div>
        <div className="resize-handle-line"></div>
      </div>
      <div className="resize-handle-hint">
        拖拽调整高度比例 ({Math.round(topPercent)}% : {Math.round(100 - topPercent)}%)
      </div>
    </div>
  );
};

export default SplitResizeHandle;