/**
 * 系统设置管理器
 * 用于管理LLM模型参数等系统设置的持久化存储
 */

// 默认设置
const DEFAULT_SETTINGS = {
  llm: {
    provider: 'claude',
    model: 'claude-sonnet-4-6',
    temperature: 0.7,
    maxTokens: 4000
  },
  ui: {
    theme: 'light',
    language: 'zh-CN'
  },
  advanced: {
    streamingEnabled: true, // 默认启用流式传输
    debugMode: false
  }
};

// 可用的模型配置
export const MODEL_OPTIONS = {
  claude: [
    { value: 'claude-sonnet-4-6', label: 'Claude Sonnet 4-6', description: '平衡性能，默认推荐' },
    { value: 'claude-opus-4-6', label: 'Claude Opus 4-6', description: '最强性能，适合复杂任务' }
  ],
  mistral: [
    { value: 'mistral-small', label: 'Mistral Small', description: '轻量级模型，快速响应' },
    { value: 'mistral-medium', label: 'Mistral Medium', description: '中等性能模型' },
    { value: 'mistral-large', label: 'Mistral Large', description: '高性能模型' },
    { value: 'codestral-2501', label: 'Codestral 2501', description: '专注代码生成' }
  ]
};

// 存储键名
const STORAGE_KEY = 'generative_facial_expression_settings';

/**
 * 系统设置管理器类
 */
class SystemSettings {
  constructor() {
    this.settings = this.loadSettings();
    this.listeners = [];
  }

  /**
   * 从本地存储加载设置
   */
  loadSettings() {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        // 合并默认设置和存储的设置，确保新增的设置项有默认值
        return this.mergeWithDefaults(parsed, DEFAULT_SETTINGS);
      }
    } catch (error) {
      console.warn('加载系统设置失败:', error);
    }
    return { ...DEFAULT_SETTINGS };
  }

  /**
   * 保存设置到本地存储
   */
  saveSettings() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.settings));
      console.log('系统设置已保存:', this.settings);
      
      // 通知所有监听器
      this.listeners.forEach(listener => {
        try {
          listener(this.settings);
        } catch (error) {
          console.error('设置变更通知失败:', error);
        }
      });
    } catch (error) {
      console.error('保存系统设置失败:', error);
      throw new Error('设置保存失败，请检查浏览器存储空间');
    }
  }

  /**
   * 深度合并设置对象
   */
  mergeWithDefaults(stored, defaults) {
    const result = { ...defaults };
    
    for (const key in stored) {
      if (stored.hasOwnProperty(key)) {
        if (typeof stored[key] === 'object' && stored[key] !== null && !Array.isArray(stored[key])) {
          result[key] = this.mergeWithDefaults(stored[key] || {}, defaults[key] || {});
        } else {
          result[key] = stored[key];
        }
      }
    }
    
    return result;
  }

  /**
   * 获取所有设置
   */
  getAllSettings() {
    return { ...this.settings };
  }

  /**
   * 获取LLM设置
   */
  getLLMSettings() {
    return { ...this.settings.llm };
  }

  /**
   * 更新LLM设置
   */
  updateLLMSettings(updates) {
    this.settings.llm = { ...this.settings.llm, ...updates };
    this.saveSettings();
  }

  /**
   * 获取UI设置
   */
  getUISettings() {
    return { ...this.settings.ui };
  }

  /**
   * 更新UI设置
   */
  updateUISettings(updates) {
    this.settings.ui = { ...this.settings.ui, ...updates };
    
    // 如果更新了语言设置，也同步到localStorage的ui_language键
    if (updates.language) {
      localStorage.setItem('ui_language', updates.language);
    }
    
    this.saveSettings();
  }

  /**
   * 获取高级设置
   */
  getAdvancedSettings() {
    return { ...this.settings.advanced };
  }

  /**
   * 更新高级设置
   */
  updateAdvancedSettings(updates) {
    this.settings.advanced = { ...this.settings.advanced, ...updates };
    this.saveSettings();
  }

  /**
   * 重置为默认设置
   */
  resetToDefaults() {
    this.settings = { ...DEFAULT_SETTINGS };
    this.saveSettings();
  }

  /**
   * 添加设置变更监听器
   */
  addChangeListener(listener) {
    this.listeners.push(listener);
    return () => {
      const index = this.listeners.indexOf(listener);
      if (index > -1) {
        this.listeners.splice(index, 1);
      }
    };
  }

  /**
   * 获取当前模型的显示名称
   */
  getCurrentModelLabel() {
    const { provider, model } = this.settings.llm;
    const options = MODEL_OPTIONS[provider] || [];
    const option = options.find(opt => opt.value === model);
    return option ? option.label : model;
  }

  /**
   * 获取当前模型的完整信息
   */
  getCurrentModelInfo() {
    const { provider, model } = this.settings.llm;
    const options = MODEL_OPTIONS[provider] || [];
    const option = options.find(opt => opt.value === model);
    return {
      provider,
      model,
      label: option ? option.label : model,
      description: option ? option.description : '自定义模型'
    };
  }

  /**
   * 验证模型配置是否有效
   */
  validateModelConfig(provider, model) {
    if (!provider || !model) {
      return false;
    }
    
    const options = MODEL_OPTIONS[provider];
    if (!options) {
      return false;
    }
    
    return options.some(opt => opt.value === model);
  }

  /**
   * 导出设置
   */
  exportSettings() {
    return JSON.stringify(this.settings, null, 2);
  }

  /**
   * 导入设置
   */
  importSettings(settingsJson) {
    try {
      const imported = JSON.parse(settingsJson);
      this.settings = this.mergeWithDefaults(imported, DEFAULT_SETTINGS);
      this.saveSettings();
      return true;
    } catch (error) {
      console.error('导入设置失败:', error);
      return false;
    }
  }
}

// 创建全局单例实例
const systemSettings = new SystemSettings();

export default systemSettings;

// 导出便捷方法
export const getLLMSettings = () => systemSettings.getLLMSettings();
export const updateLLMSettings = (updates) => systemSettings.updateLLMSettings(updates);
export const getAdvancedSettings = () => systemSettings.getAdvancedSettings();
export const updateAdvancedSettings = (updates) => systemSettings.updateAdvancedSettings(updates);
export const getCurrentModelInfo = () => systemSettings.getCurrentModelInfo();
export const addSettingsChangeListener = (listener) => systemSettings.addChangeListener(listener);