import React, { useState, useEffect, useCallback } from 'react';
import systemSettings, { MODEL_OPTIONS } from '../utils/SystemSettings';
import { useLanguage } from '../contexts/LanguageContext';
import './SystemSettingsModal.css';

function SystemSettingsModal({ isOpen, onClose }) {
  const { t, changeLanguage } = useLanguage();
  const [settings, setSettings] = useState(systemSettings.getAllSettings());
  const [hasChanges, setHasChanges] = useState(false);
  const [activeTab, setActiveTab] = useState('llm');

  // 加载当前设置
  useEffect(() => {
    if (isOpen) {
      setSettings(systemSettings.getAllSettings());
      setHasChanges(false);
    }
  }, [isOpen]);

  // 处理设置变更
  const handleSettingChange = useCallback((category, key, value) => {
    setSettings(prev => ({
      ...prev,
      [category]: {
        ...prev[category],
        [key]: value
      }
    }));
    setHasChanges(true);
    
    // 如果是语言设置变更，立即应用
    if (category === 'ui' && key === 'language') {
      changeLanguage(value);
    }
  }, [changeLanguage]);

  // 处理提供商变更
  const handleProviderChange = useCallback((provider) => {
    const defaultModel = MODEL_OPTIONS[provider]?.[0]?.value || '';
    setSettings(prev => ({
      ...prev,
      llm: {
        ...prev.llm,
        provider,
        model: defaultModel
      }
    }));
    setHasChanges(true);
  }, []);

  // 保存设置
  const handleSave = useCallback(() => {
    try {
      systemSettings.updateLLMSettings(settings.llm);
      systemSettings.updateUISettings(settings.ui);
      systemSettings.updateAdvancedSettings(settings.advanced);
      setHasChanges(false);
      onClose();
    } catch (error) {
      alert(`${t('systemSettings.alerts.saveFailed')} ${error.message}`);
    }
  }, [settings, onClose, t]);

  // 重置设置
  const handleReset = useCallback(() => {
    if (window.confirm(t('systemSettings.alerts.resetConfirm'))) {
      systemSettings.resetToDefaults();
      setSettings(systemSettings.getAllSettings());
      setHasChanges(false);
    }
  }, [t]);

  // 导出设置
  const handleExport = useCallback(() => {
    const settingsData = systemSettings.exportSettings();
    const blob = new Blob([settingsData], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `generative_facial_expression_settings_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  }, []);

  // 导入设置
  const handleImport = useCallback((event) => {
    const file = event.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const success = systemSettings.importSettings(e.target.result);
        if (success) {
          setSettings(systemSettings.getAllSettings());
          setHasChanges(false);
          alert(t('systemSettings.alerts.importSuccess'));
        } else {
          alert(t('systemSettings.alerts.importFailed'));
        }
      } catch (error) {
        alert(`${t('systemSettings.alerts.importError')} ${error.message}`);
      }
    };
    reader.readAsText(file);
  }, [t]);

  if (!isOpen) {
    return null;
  }

  const currentProvider = settings.llm.provider;
  const availableModels = MODEL_OPTIONS[currentProvider] || [];

  return (
    <div className="modal-overlay settings-modal-overlay" onClick={onClose}>
      <div className="modal-content settings-modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header settings-modal-header">
          <h3>{t('systemSettings.title')}</h3>
          <button className="close-btn" onClick={onClose}>×</button>
        </div>

        <div className="settings-modal-body">
          {/* 标签导航 */}
          <div className="settings-tabs">
            <button 
              className={`settings-tab ${activeTab === 'llm' ? 'active' : ''}`}
              onClick={() => setActiveTab('llm')}
            >
              <span className="tab-icon">🤖</span>
              {t('systemSettings.tabs.llm')}
            </button>
            <button 
              className={`settings-tab ${activeTab === 'ui' ? 'active' : ''}`}
              onClick={() => setActiveTab('ui')}
            >
              <span className="tab-icon">🎨</span>
              {t('systemSettings.tabs.ui')}
            </button>
            <button 
              className={`settings-tab ${activeTab === 'advanced' ? 'active' : ''}`}
              onClick={() => setActiveTab('advanced')}
            >
              <span className="tab-icon">⚙️</span>
              {t('systemSettings.tabs.advanced')}
            </button>
          </div>

          {/* 标签内容 */}
          <div className="settings-tab-content">
            {activeTab === 'llm' && (
              <div className="settings-section">
                <h4>{t('systemSettings.llmSettings.title')}</h4>
                <div className="settings-description">
                  {t('systemSettings.llmSettings.description')}
                </div>

                {/* 提供商选择 */}
                <div className="setting-group">
                  <label className="setting-label">
                    <span className="label-text">{t('systemSettings.llmSettings.provider.label')}</span>
                    <span className="label-description">{t('systemSettings.llmSettings.provider.description')}</span>
                  </label>
                  <div className="provider-selection">
                    <button 
                      className={`provider-option ${currentProvider === 'claude' ? 'active' : ''}`}
                      onClick={() => handleProviderChange('claude')}
                    >
                      <div className="provider-icon">🏛️</div>
                      <div className="provider-info">
                        <div className="provider-name">{t('systemSettings.llmSettings.provider.claude.name')}</div>
                        <div className="provider-desc">{t('systemSettings.llmSettings.provider.claude.description')}</div>
                      </div>
                    </button>
                    <button 
                      className={`provider-option ${currentProvider === 'mistral' ? 'active' : ''}`}
                      onClick={() => handleProviderChange('mistral')}
                    >
                      <div className="provider-icon">🌟</div>
                      <div className="provider-info">
                        <div className="provider-name">{t('systemSettings.llmSettings.provider.mistral.name')}</div>
                        <div className="provider-desc">{t('systemSettings.llmSettings.provider.mistral.description')}</div>
                      </div>
                    </button>
                  </div>
                </div>

                {/* 模型选择 */}
                <div className="setting-group">
                  <label className="setting-label">
                    <span className="label-text">{t('systemSettings.llmSettings.model.label')}</span>
                    <span className="label-description">{t('systemSettings.llmSettings.model.description')}</span>
                  </label>
                  <div className="model-selection">
                    {availableModels.map(model => (
                      <label key={model.value} className="model-option">
                        <input
                          type="radio"
                          name="model"
                          value={model.value}
                          checked={settings.llm.model === model.value}
                          onChange={(e) => handleSettingChange('llm', 'model', e.target.value)}
                        />
                        <div className="model-info">
                          <div className="model-name">{model.label}</div>
                          <div className="model-description">{model.description}</div>
                        </div>
                      </label>
                    ))}
                  </div>
                  {/* 自定义模型名称输入 */}
                  <div className="custom-model-input" style={{ marginTop: '8px' }}>
                    <label style={{ display: 'block', marginBottom: '6px', color: '#888' }}>
                      自定义模型名称（将直接作为后端调用值）
                    </label>
                    <input
                      type="text"
                      value={settings.llm.model || ''}
                      onChange={(e) => handleSettingChange('llm', 'model', e.target.value)}
                      placeholder="例如：claude-sonnet-4-6 或自定义标识"
                      style={{ width: '100%', padding: '8px', borderRadius: '6px', border: '1px solid #ccc' }}
                    />
                    <div style={{ marginTop: '6px', fontSize: '12px', color: '#888' }}>
                      实际调用模型：<code>{settings.llm.model || '未设置'}</code>
                    </div>
                  </div>
                </div>

                {/* 温度参数 */}
                <div className="setting-group">
                  <label className="setting-label">
                    <span className="label-text">{t('systemSettings.llmSettings.temperature.label')}</span>
                    <span className="label-description">{t('systemSettings.llmSettings.temperature.description')}</span>
                  </label>
                  <div className="temperature-control">
                    <input
                      type="range"
                      min="0"
                      max="1"
                      step="0.1"
                      value={settings.llm.temperature}
                      onChange={(e) => handleSettingChange('llm', 'temperature', parseFloat(e.target.value))}
                      className="temperature-slider"
                    />
                    <div className="temperature-labels">
                      <span className="temp-label">{t('systemSettings.llmSettings.temperature.conservative')}</span>
                      <span className="temp-value">{settings.llm.temperature.toFixed(1)}</span>
                      <span className="temp-label">{t('systemSettings.llmSettings.temperature.creative')}</span>
                    </div>
                  </div>
                </div>

                {/* 最大令牌数 */}
                <div className="setting-group">
                  <label className="setting-label">
                    <span className="label-text">{t('systemSettings.llmSettings.maxTokens.label')}</span>
                    <span className="label-description">{t('systemSettings.llmSettings.maxTokens.description')}</span>
                  </label>
                  <input
                    type="number"
                    min="1000"
                    max="8000"
                    step="100"
                    value={settings.llm.maxTokens}
                    onChange={(e) => handleSettingChange('llm', 'maxTokens', parseInt(e.target.value))}
                    className="max-tokens-input"
                  />
                </div>
              </div>
            )}

            {activeTab === 'ui' && (
              <div className="settings-section">
                <h4>{t('systemSettings.uiSettings.title')}</h4>
                <div className="settings-description">
                  {t('systemSettings.uiSettings.description')}
                </div>

                {/* 主题设置 */}
                <div className="setting-group">
                  <label className="setting-label">
                    <span className="label-text">{t('systemSettings.uiSettings.theme.label')}</span>
                    <span className="label-description">{t('systemSettings.uiSettings.theme.description')}</span>
                  </label>
                  <div className="theme-selection">
                    <label className="theme-option">
                      <input
                        type="radio"
                        name="theme"
                        value="light"
                        checked={settings.ui.theme === 'light'}
                        onChange={(e) => handleSettingChange('ui', 'theme', e.target.value)}
                      />
                      <div className="theme-preview light-theme">{t('systemSettings.uiSettings.theme.light')}</div>
                    </label>
                    <label className="theme-option">
                      <input
                        type="radio"
                        name="theme"
                        value="dark"
                        checked={settings.ui.theme === 'dark'}
                        onChange={(e) => handleSettingChange('ui', 'theme', e.target.value)}
                      />
                      <div className="theme-preview dark-theme">{t('systemSettings.uiSettings.theme.dark')}</div>
                    </label>
                  </div>
                </div>

                {/* 语言设置 */}
                <div className="setting-group">
                  <label className="setting-label">
                    <span className="label-text">{t('systemSettings.uiSettings.language.label')}</span>
                    <span className="label-description">{t('systemSettings.uiSettings.language.description')}</span>
                  </label>
                  <select
                    value={settings.ui.language}
                    onChange={(e) => handleSettingChange('ui', 'language', e.target.value)}
                    className="language-select"
                  >
                    <option value="zh-CN">{t('systemSettings.uiSettings.language.zhCN')}</option>
                    <option value="en-US">{t('systemSettings.uiSettings.language.enUS')}</option>
                  </select>
                </div>
              </div>
            )}

            {activeTab === 'advanced' && (
              <div className="settings-section">
                <h4>{t('systemSettings.advancedSettings.title')}</h4>
                <div className="settings-description">
                  {t('systemSettings.advancedSettings.description')}
                </div>

                {/* 流式传输设置 */}
                <div className="setting-group">
                  <label className="setting-label">
                    <span className="label-text">{t('systemSettings.advancedSettings.streaming.label')}</span>
                    <span className="label-description">{t('systemSettings.advancedSettings.streaming.description')}</span>
                  </label>
                  <div className="switch-container">
                    <label className="switch">
                      <input
                        type="checkbox"
                        checked={settings.advanced?.streamingEnabled || false}
                        onChange={(e) => handleSettingChange('advanced', 'streamingEnabled', e.target.checked)}
                      />
                      <span className="slider round"></span>
                    </label>
                    <span className="switch-label">
                      {settings.advanced?.streamingEnabled ? t('systemSettings.advancedSettings.streaming.enabled') : t('systemSettings.advancedSettings.streaming.disabled')}
                    </span>
                  </div>
                  <div className="setting-note">
                    {settings.advanced?.streamingEnabled ? (
                      <span className="note-success">{t('systemSettings.advancedSettings.streaming.enabledNote')}</span>
                    ) : (
                      <span className="note-info">{t('systemSettings.advancedSettings.streaming.disabledNote')}</span>
                    )}
                  </div>
                </div>

                {/* 调试模式 */}
                <div className="setting-group">
                  <label className="setting-label">
                    <span className="label-text">{t('systemSettings.advancedSettings.debugMode.label')}</span>
                    <span className="label-description">{t('systemSettings.advancedSettings.debugMode.description')}</span>
                  </label>
                  <div className="switch-container">
                    <label className="switch">
                      <input
                        type="checkbox"
                        checked={settings.advanced?.debugMode || false}
                        onChange={(e) => handleSettingChange('advanced', 'debugMode', e.target.checked)}
                      />
                      <span className="slider round"></span>
                    </label>
                    <span className="switch-label">
                      {settings.advanced?.debugMode ? t('systemSettings.advancedSettings.streaming.enabled') : t('systemSettings.advancedSettings.streaming.disabled')}
                    </span>
                  </div>
                </div>

                {/* 当前配置信息 */}
                <div className="setting-group">
                  <label className="setting-label">
                    <span className="label-text">{t('systemSettings.advancedSettings.currentConfig.label')}</span>
                    <span className="label-description">{t('systemSettings.advancedSettings.currentConfig.description')}</span>
                  </label>
                  <div className="current-config">
                    <div className="config-item">
                      <span className="config-label">{t('systemSettings.advancedSettings.currentConfig.provider')}</span>
                      <span className="config-value">{currentProvider === 'claude' ? t('systemSettings.llmSettings.provider.claude.name') : t('systemSettings.llmSettings.provider.mistral.name')}</span>
                    </div>
                    <div className="config-item">
                      <span className="config-label">{t('systemSettings.advancedSettings.currentConfig.model')}</span>
                      <span className="config-value">{settings.llm.model}</span>
                    </div>
                    <div className="config-item">
                      <span className="config-label">{t('systemSettings.advancedSettings.currentConfig.creativity')}</span>
                      <span className="config-value">{settings.llm.temperature}</span>
                    </div>
                  </div>
                </div>

                {/* 导入导出 */}
                <div className="setting-group">
                  <label className="setting-label">
                    <span className="label-text">{t('systemSettings.advancedSettings.settingsManagement.label')}</span>
                    <span className="label-description">{t('systemSettings.advancedSettings.settingsManagement.description')}</span>
                  </label>
                  <div className="settings-management">
                    <button onClick={handleExport} className="management-btn export-btn">
                      {t('systemSettings.advancedSettings.settingsManagement.export')}
                    </button>
                    <label className="management-btn import-btn">
                      {t('systemSettings.advancedSettings.settingsManagement.import')}
                      <input
                        type="file"
                        accept=".json"
                        onChange={handleImport}
                        style={{ display: 'none' }}
                      />
                    </label>
                  </div>
                </div>

                {/* 重置设置 */}
                <div className="setting-group danger-zone">
                  <label className="setting-label">
                    <span className="label-text">{t('systemSettings.advancedSettings.dangerZone.label')}</span>
                    <span className="label-description">{t('systemSettings.advancedSettings.dangerZone.description')}</span>
                  </label>
                  <button onClick={handleReset} className="reset-btn danger-btn">
                    {t('systemSettings.advancedSettings.dangerZone.reset')}
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="settings-modal-footer">
          <div className="footer-left">
            {hasChanges && (
              <span className="unsaved-indicator">
                {t('systemSettings.footer.unsavedChanges')}
              </span>
            )}
          </div>
          <div className="footer-right">
            <button onClick={onClose} className="cancel-btn">
              {t('systemSettings.footer.cancel')}
            </button>
            <button 
              onClick={handleSave} 
              className="save-btn"
              disabled={!hasChanges}
            >
              {t('systemSettings.footer.save')}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

export default SystemSettingsModal;
