export const getBackendUrl = () => {
  const backendDomain = process.env.REACT_APP_BACKEND_DOMAIN;
  if (backendDomain) {
    return backendDomain.replace(/\/$/, '');
  }

  const backendUrl = process.env.REACT_APP_BACKEND_URL;
  const backendPort = process.env.REACT_APP_BACKEND_PORT;
  
  if (!backendUrl) {
    console.error('Error: REACT_APP_BACKEND_URL environment variable is not defined!');
    console.error('Please make sure you have set REACT_APP_BACKEND_URL in your .env file');
    throw new Error('REACT_APP_BACKEND_URL is not defined');
  }
  
  if (!backendPort) {
    console.error('Error: REACT_APP_BACKEND_PORT environment variable is not defined!');
    console.error('Please make sure you have set REACT_APP_BACKEND_PORT in your .env file');
    throw new Error('REACT_APP_BACKEND_PORT is not defined');
  }
  
  return `${backendUrl.replace(/\/$/, '')}:${backendPort}`;
};

// 获取HTTPS后端URL（用于真机测试）
export const getHTTPSBackendUrl = () => {
  const httpsUrl = process.env.REACT_APP_HTTPS_URL;
  const httpsPort = process.env.REACT_APP_HTTPS_PORT;
  
  if (!httpsUrl || !httpsPort) {
    console.warn('HTTPS配置未完整，将使用HTTP URL');
    return getBackendUrl();
  }
  
  return `${httpsUrl.replace(/\/$/, '')}:${httpsPort}`;
};

// 检测是否在HTTPS环境中
export const isHTTPS = () => {
  return window.location.protocol === 'https:';
};

// 智能获取后端URL（根据当前协议自动选择）
export const getSmartBackendUrl = () => {
  if (isHTTPS()) {
    return getHTTPSBackendUrl();
  }
  return getBackendUrl();
}; 