import React, { useState, useCallback, useRef, useEffect } from 'react';
import './SidebarResizeHandle.css';

function SidebarResizeHandle({ side, onResize, currentWidth }) {
  const [isDragging, setIsDragging] = useState(false);
  const dragStartX = useRef(0);
  const dragStartWidth = useRef(0);

  // 拖拽处理函数 - 完全按照底部面板的模式
  const handleMouseMove = useCallback((e) => {
    const deltaX = e.clientX - dragStartX.current;
    let newWidth;

    if (side === 'left') {
      // 左侧面板：向右拖动增加宽度
      newWidth = dragStartWidth.current + deltaX;
    } else {
      // 右侧面板：向左拖动增加宽度  
      newWidth = dragStartWidth.current - deltaX;
    }
    
    // 限制宽度范围
    const minWidth = 288; // 360 * 0.8 = 288  
    const maxWidth = side === 'left' ? 750 : 840; // 左侧: 500 * 1.5 = 750, 右侧: 560 * 1.5 = 840
    newWidth = Math.min(Math.max(newWidth, minWidth), maxWidth);
    
    onResize(newWidth);
  }, [side, onResize]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
    document.removeEventListener('mousemove', handleMouseMove);
    document.removeEventListener('mouseup', handleMouseUp);
  }, [handleMouseMove]);

  // 开始拖拽
  const handleMouseDown = useCallback((e) => {
    setIsDragging(true);
    dragStartX.current = e.clientX;
    dragStartWidth.current = currentWidth;
    
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
    
    e.preventDefault();
  }, [currentWidth, handleMouseMove, handleMouseUp]);

  // 清理事件监听器
  useEffect(() => {
    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  return (
    <div 
      className={`sidebar-resize-handle ${side} ${isDragging ? 'dragging' : ''}`}
      onMouseDown={handleMouseDown}
      title={`拖拽调整${side === 'left' ? '左侧' : '右侧'}面板宽度`}
    >
      <div className="sidebar-drag-indicator"></div>
      <span className="drag-hint">拖拽调整宽度</span>
    </div>
  );
}

export default SidebarResizeHandle;