import React, { useState, useEffect } from 'react';
import { t } from '../../utils/i18n';

function StepOne({ userProfile, testConfig, onNext, onUpdate, language = 'en' }) {
  const trans = t(language);
  const [formData, setFormData] = useState({
    name: userProfile.name || "",
  });
  const [contextFields, setContextFields] = useState([]);

  // 解析设计师定义的角色塑造上下文，生成动态表单字段
  const parseContextFields = (contextDefinitions) => {
    const fields = [];

    // 如果没有上下文定义，返回空数组（严格按照定义，不提供默认字段）
    if (!contextDefinitions || contextDefinitions.length === 0) {
      console.log('⚠️ No role shaping context fields defined');
      return fields;
    }

    // 根据设计师定义的上下文生成字段
    contextDefinitions.forEach(definition => {
      const fieldName = definition.name.toLowerCase();
      const fieldKey = definition.id; // 使用定义的id作为键，确保与后端匹配
      
      if (fieldName.includes('年龄') || fieldName.includes('age')) {
        fields.push({
          key: fieldKey,
          label: definition.name,
          type: 'select',
          required: true,
          options: ['18-25', '26-30', '31-35', '36-40', '40+']
        });
      } else if (fieldName.includes('职业') || fieldName.includes('occupation') || fieldName.includes('工作')) {
        fields.push({
          key: fieldKey,
          label: definition.name,
          type: 'select',
          required: true,
          options: [trans('student'), trans('employee'), trans('freelancer'), trans('entrepreneur'), trans('retired'), trans('other')]
        });
      } else if (fieldName.includes('兴趣') || fieldName.includes('爱好') || fieldName.includes('hobby')) {
        fields.push({
          key: fieldKey,
          label: definition.name,
          type: 'multiselect',
          required: true,
          options: [trans('sports'), trans('travel'), trans('reading'), trans('gaming'), trans('cooking'), trans('art'), trans('technology'), trans('music'), trans('movies'), trans('photography'), trans('fitness'), trans('nature')]
        });
      } else if (fieldName.includes('性格') || fieldName.includes('personality')) {
        fields.push({
          key: fieldKey,
          label: definition.name,
          type: 'select',
          required: true,
          options: [trans('introverted'), trans('extroverted'), trans('rational'), trans('emotional'), trans('optimistic'), trans('calm'), trans('lively'), trans('steady')]
        });
      } else if (fieldName.includes('mbti')) {
        fields.push({
          key: fieldKey,
          label: definition.name,
          type: 'select',
          required: true,
          options: [
            trans('INTJ (建筑师)'), trans('INTP (思想家)'), trans('ENTJ (指挥官)'), trans('ENTP (辩论家)'),
            trans('INFJ (提倡者)'), trans('INFP (调停者)'), trans('ENFJ (主角)'), trans('ENFP (竞选者)'),
            trans('ISTJ (物流师)'), trans('ISFJ (守护者)'), trans('ESTJ (总经理)'), trans('ESFJ (执政官)'),
            trans('ISTP (鉴赏家)'), trans('ISFP (探险家)'), trans('ESTP (企业家)'), trans('ESFP (表演者)')
          ]
        });
      } else if (fieldName.includes('喜好') || fieldName.includes('偏好') || fieldName.includes('preference')) {
        fields.push({
          key: fieldKey,
          label: definition.name,
          type: 'textarea',
          required: false,
          placeholder: `${trans('describeYour')} ${definition.name}...`
        });
      } else {
        // 通用文本字段
        fields.push({
          key: fieldKey,
          label: definition.name,
          type: 'text',
          required: true,
          placeholder: `${trans('pleaseInput')} ${definition.name}`
        });
      }
    });

    return fields;
  };

  useEffect(() => {
    console.log('🔍 StepOne Debug - testConfig:', testConfig);
    
    // 解析设计师定义的角色塑造上下文，生成动态表单字段
    let contextDefinitions = [];
    if (testConfig?.version?.roleGenerationConfig?.contextDefinitions) {
      contextDefinitions = testConfig.version.roleGenerationConfig.contextDefinitions;
      console.log('✅ Found role shaping context definitions:', contextDefinitions);
    } else {
      console.log('⚠️ Role shaping context definitions not found');
    }
    
    const fields = parseContextFields(contextDefinitions);
    console.log('📝 Generated form fields:', fields);
    setContextFields(fields);
    
    // 初始化表单数据
    const initialData = { name: userProfile.name || "" };
    fields.forEach(field => {
      if (field.defaultValue) {
        initialData[field.key] = field.defaultValue;
      } else if (field.type === 'multiselect') {
        initialData[field.key] = [];
      } else {
        initialData[field.key] = '';
      }
    });
    setFormData(initialData);
    console.log('🎯 Initialized form data:', initialData);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [testConfig, userProfile.name]);

  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleMultiSelectToggle = (field, option) => {
    setFormData(prev => ({
      ...prev,
      [field]: prev[field].includes(option)
        ? prev[field].filter(item => item !== option)
        : [...prev[field], option]
    }));
  };

  const handleSubmit = () => {
    // 检查必填字段
    const requiredFields = contextFields.filter(field => field.required);
    const isValid = requiredFields.every(field => {
      const value = formData[field.key];
      if (field.type === 'multiselect') {
        return value && value.length > 0;
      }
      return value && value.toString().trim().length > 0;
    });

    if (isValid) {
      onUpdate(formData);
      onNext(formData);
    } else {
      alert(trans('allRequiredFields'));
    }
  };

  const isFormValid = () => {
    const requiredFields = contextFields.filter(field => field.required);
    return requiredFields.every(field => {
      const value = formData[field.key];
      if (field.type === 'multiselect') {
        return value && value.length > 0;
      }
      return value && value.toString().trim().length > 0;
    });
  };

  const renderField = (field) => {
    const value = formData[field.key] || (field.type === 'multiselect' ? [] : '');

    switch (field.type) {
      case 'text':
        return (
          <div key={field.key} className="form-field">
            <label>
              {field.label} {field.required && <span className="required">*</span>}
            </label>
            <input
              type="text"
              value={value}
              onChange={(e) => handleInputChange(field.key, e.target.value)}
              placeholder={field.placeholder || `${trans('pleaseInput')} ${field.label}`}
            />
          </div>
        );

      case 'select':
        return (
          <div key={field.key} className="form-field">
            <label>
              {field.label} {field.required && <span className="required">*</span>}
            </label>
            <select
              value={value}
              onChange={(e) => handleInputChange(field.key, e.target.value)}
            >
              <option value="">{trans('pleaseSelectField')} {field.label}</option>
              {field.options.map(option => (
                <option key={option} value={option}>{option}</option>
              ))}
            </select>
          </div>
        );

      case 'multiselect':
        return (
          <div key={field.key} className="form-field">
            <label>
              {field.label} {field.required && <span className="required">*</span>}
            </label>
            <div className="multiselect-grid">
              {field.options.map(option => (
                <button
                  key={option}
                  type="button"
                  onClick={() => handleMultiSelectToggle(field.key, option)}
                  className={`multiselect-option ${value.includes(option) ? 'selected' : ''}`}
                >
                  {value.includes(option) && <span className="checkmark">✓</span>}
                  <span>{option}</span>
                </button>
              ))}
            </div>
          </div>
        );

      case 'textarea':
        return (
          <div key={field.key} className="form-field">
            <label>
              {field.label} {field.required && <span className="required">*</span>}
            </label>
            <textarea
              value={value}
              onChange={(e) => handleInputChange(field.key, e.target.value)}
              placeholder={field.placeholder || `${trans('pleaseInput')} ${field.label}`}
              rows={3}
            />
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="step-container">
      <div className="card">
        <div className="card-header">
          <h2 className="card-title">{trans('createProfile')}</h2>
          <p className="card-description">
            {trans('letAIKnowYou')}
          </p>
        </div>
        <div className="card-content">
          <div className="form-fields">
            {contextFields.length > 0 ? (
              contextFields.map(field => renderField(field))
            ) : (
              <div className="no-context-message">
                <p>{trans('noContextMessage1')}</p>
                <p>{trans('noContextMessage2')}</p>
              </div>
            )}
          </div>
        </div>
        
        <div className="fixed-bottom">
          <button 
            className="btn-primary" 
            onClick={handleSubmit}
            disabled={!isFormValid()}
          >
            {trans('nextStep')}
          </button>
        </div>
      </div>
      
      <style>{`
        .step-container {
          min-height: 100vh;
          display: flex;
          align-items: center;
          justify-content: center;
          padding: 1rem;
          position: relative;
          z-index: 20;
        }
        
        .card {
          width: 100%;
          max-width: 500px;
          background: rgba(255, 255, 255, 0.95);
          backdrop-filter: blur(10px);
          border-radius: 16px;
          box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
          border: 1px solid rgba(255, 255, 255, 0.2);
          max-height: 90vh;
          display: flex;
          flex-direction: column;
        }
        
        .card-header {
          text-align: center;
          padding: 2rem 2rem 1rem;
          flex-shrink: 0;
        }
        
        .card-title {
          font-size: 1.5rem;
          font-weight: 700;
          color: #1a1a1a;
          margin: 0 0 0.5rem;
        }
        
        .card-description {
          color: #666;
          font-size: 0.9rem;
          margin: 0;
        }
        
        .card-content {
          padding: 1rem 2rem;
          overflow-y: auto;
          flex-grow: 1;
          min-height: 0;
        }
        
        .form-fields {
          display: flex;
          flex-direction: column;
          gap: 1.5rem;
          padding-bottom: 80px; /* Space for fixed button */
        }
        
        .form-field {
          display: flex;
          flex-direction: column;
          gap: 0.5rem;
        }
        
        .form-field label {
          font-size: 0.9rem;
          font-weight: 600;
          color: #333;
        }
        
        .required {
          color: #e74c3c;
        }
        
        .form-field input,
        .form-field select,
        .form-field textarea {
          padding: 0.75rem;
          border: 2px solid #e1e5e9;
          border-radius: 8px;
          font-size: 1rem;
          background: white;
          transition: border-color 0.2s ease;
        }
        
        .form-field input:focus,
        .form-field select:focus,
        .form-field textarea:focus {
          outline: none;
          border-color: #667eea;
        }
        
        .form-field textarea {
          resize: vertical;
          min-height: 80px;
        }
        
        .multiselect-grid {
          display: grid;
          grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
          gap: 0.5rem;
        }
        
        .multiselect-option {
          padding: 0.5rem;
          border: 2px solid #e1e5e9;
          border-radius: 6px;
          background: white;
          cursor: pointer;
          transition: all 0.2s ease;
          display: flex;
          align-items: center;
          justify-content: center;
          gap: 0.25rem;
          font-size: 0.85rem;
          min-height: 44px;
        }
        
        .multiselect-option:hover {
          border-color: #667eea;
        }
        
        .multiselect-option.selected {
          border-color: #667eea;
          background: rgba(102, 126, 234, 0.1);
          color: #667eea;
        }
        
        .checkmark {
          font-size: 0.75rem;
          color: #667eea;
        }
        
        .no-context-message {
          text-align: center;
          padding: 2rem;
          color: #666;
          line-height: 1.6;
        }
        
        .no-context-message p {
          margin: 0.5rem 0;
        }
        
        .fixed-bottom {
          position: fixed;
          bottom: 0;
          left: 0;
          right: 0;
          padding: 1rem;
          background: rgba(255, 255, 255, 0.95);
          backdrop-filter: blur(10px);
          border-top: 1px solid rgba(0, 0, 0, 0.1);
          z-index: 30;
        }
        
        .btn-primary {
          width: 100%;
          max-width: 500px;
          margin: 0 auto;
          display: block;
          padding: 0.875rem;
          background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
          color: white;
          border: none;
          border-radius: 8px;
          font-size: 1rem;
          font-weight: 600;
          cursor: pointer;
          transition: all 0.2s ease;
          min-height: 44px;
        }
        
        .btn-primary:hover:not(:disabled) {
          transform: translateY(-1px);
          box-shadow: 0 4px 12px rgba(102, 126, 234, 0.4);
        }
        
        .btn-primary:disabled {
          background: #ccc;
          cursor: not-allowed;
          transform: none;
          box-shadow: none;
        }
        
        @media (max-width: 480px) {
          .step-container {
            padding: 0.5rem;
          }
          
          .card {
            border-radius: 12px;
            max-height: 100vh;
          }
          
          .card-header {
            padding: 1.5rem 1.5rem 1rem;
          }
          
          .card-content {
            padding: 1rem 1.5rem;
          }
          
          .multiselect-grid {
            grid-template-columns: repeat(2, 1fr);
          }
          
          .multiselect-option {
            font-size: 0.8rem;
            padding: 0.4rem;
          }
        }
      `}</style>
    </div>
  );
}

export default StepOne;