import React, { useState, useEffect, useCallback } from 'react';
import { getSmartBackendUrl } from '../../utils/env';
import './DebugPanel.css';

function DebugPanel({ 
  currentProject, 
  currentVersion, 
  isVisible, 
  onClose,
  hasUnsavedChanges,
  autoSaveEnabled,
  saving,
  svgElements,
  designRules 
}) {
  const [debugData, setDebugData] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [lastRefresh, setLastRefresh] = useState(null);
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [refreshInterval, setRefreshInterval] = useState(null);

  // 获取后端存储数据
  const fetchStorageData = useCallback(async () => {
    if (!currentProject || !currentVersion) return;

    try {
      setIsLoading(true);
      const response = await fetch(
        `${getSmartBackendUrl()}/api/designer/project/${currentProject.id}/version/${currentVersion.id}/debug-storage`
      );
      
      if (!response.ok) {
        throw new Error(`获取存储数据失败: ${response.status}`);
      }

      const data = await response.json();
      if (data.success) {
        setDebugData(data.debug);
        setLastRefresh(new Date());
      }
    } catch (error) {
      console.error('获取调试数据失败:', error);
      setDebugData({ error: error.message });
    } finally {
      setIsLoading(false);
    }
  }, [currentProject, currentVersion]);

  // 自动刷新功能
  useEffect(() => {
    if (autoRefresh && isVisible && currentProject && currentVersion) {
      // 立即获取一次数据
      fetchStorageData();
      
      // 设置定时刷新
      const interval = setInterval(fetchStorageData, 3000); // 每3秒刷新
      setRefreshInterval(interval);
      
      return () => {
        if (interval) {
          clearInterval(interval);
        }
      };
    } else if (refreshInterval) {
      clearInterval(refreshInterval);
      setRefreshInterval(null);
    }
  }, [autoRefresh, isVisible, currentProject, currentVersion, fetchStorageData]);

  // 手动刷新
  const handleManualRefresh = useCallback(() => {
    fetchStorageData();
  }, [fetchStorageData]);

  if (!isVisible) return null;

  return (
    <div className="debug-panel-overlay">
      <div className="debug-panel">
        <div className="debug-header">
          <h3>🔍 存储调试面板</h3>
          <div className="debug-controls">
            <label className="auto-refresh-toggle">
              <input
                type="checkbox"
                checked={autoRefresh}
                onChange={(e) => setAutoRefresh(e.target.checked)}
              />
              自动刷新
            </label>
            <button 
              onClick={handleManualRefresh} 
              disabled={isLoading}
              className="refresh-btn"
            >
              {isLoading ? '刷新中...' : '手动刷新'}
            </button>
            <button onClick={onClose} className="close-btn">×</button>
          </div>
        </div>

        <div className="debug-content">
          {/* 当前状态 */}
          <div className="debug-section">
            <h4>🎛️ 前端状态</h4>
            <div className="status-grid">
              <div className="status-item">
                <span className="label">项目:</span>
                <span className="value">{currentProject?.name || 'N/A'}</span>
              </div>
              <div className="status-item">
                <span className="label">版本:</span>
                <span className="value">v{currentVersion?.versionNumber || 'N/A'} ({currentVersion?.type || 'N/A'})</span>
              </div>
              <div className="status-item">
                <span className="label">SVG元素:</span>
                <span className="value">{svgElements?.length || 0} 个</span>
              </div>
              <div className="status-item">
                <span className="label">设计规则:</span>
                <span className="value">{designRules?.length || 0} 个</span>
              </div>
              <div className="status-item">
                <span className="label">未保存更改:</span>
                <span className={`value ${hasUnsavedChanges ? 'warning' : 'success'}`}>
                  {hasUnsavedChanges ? '✗ 是' : '✓ 否'}
                </span>
              </div>
              <div className="status-item">
                <span className="label">自动保存:</span>
                <span className={`value ${autoSaveEnabled ? 'success' : 'warning'}`}>
                  {autoSaveEnabled ? '✓ 开启' : '✗ 关闭'}
                </span>
              </div>
              <div className="status-item">
                <span className="label">保存中:</span>
                <span className={`value ${saving ? 'warning' : 'success'}`}>
                  {saving ? '✗ 是' : '✓ 否'}
                </span>
              </div>
            </div>
          </div>

          {/* 后端存储数据 */}
          <div className="debug-section">
            <h4>💾 后端存储数据</h4>
            {lastRefresh && (
              <div className="refresh-info">
                最后刷新: {lastRefresh.toLocaleString()}
              </div>
            )}
            
            {debugData ? (
              debugData.error ? (
                <div className="error-info">
                  错误: {debugData.error}
                </div>
              ) : (
                <div className="storage-info">
                  <div className="info-grid">
                    <div className="info-item">
                      <span className="label">存储时间:</span>
                      <span className="value">{new Date(debugData.versionInfo.lastModified).toLocaleString()}</span>
                    </div>
                    <div className="info-item">
                      <span className="label">SVG元素(存储):</span>
                      <span className="value">{debugData.statistics.svgElementsCount} 个</span>
                    </div>
                    <div className="info-item">
                      <span className="label">设计规则:</span>
                      <span className="value">{debugData.statistics.designRulesCount} 个</span>
                    </div>
                    <div className="info-item">
                      <span className="label">画布大小:</span>
                      <span className="value">
                        {debugData.statistics.canvasSize ? 
                          `${debugData.statistics.canvasSize.width}×${debugData.statistics.canvasSize.height}` : 
                          'N/A'
                        }
                      </span>
                    </div>
                  </div>

                  {/* 数据一致性检查 */}
                  <div className="consistency-check">
                    <h5>🔄 数据一致性检查</h5>
                    <div className="check-item">
                      <span className="label">SVG元素数量:</span>
                      <span className={`value ${
                        (svgElements?.length || 0) === debugData.statistics.svgElementsCount ? 
                        'success' : 'error'
                      }`}>
                        前端: {svgElements?.length || 0} 个, 
                        后端: {debugData.statistics.svgElementsCount} 个
                        {(svgElements?.length || 0) === debugData.statistics.svgElementsCount ? ' ✓' : ' ✗ 不一致!'}
                      </span>
                    </div>
                    <div className="check-item">
                      <span className="label">设计规则数量:</span>
                      <span className={`value ${
                        (designRules?.length || 0) === debugData.statistics.designRulesCount ? 
                        'success' : 'error'
                      }`}>
                        前端: {designRules?.length || 0} 个, 
                        后端: {debugData.statistics.designRulesCount} 个
                        {(designRules?.length || 0) === debugData.statistics.designRulesCount ? ' ✓' : ' ✗ 不一致!'}
                      </span>
                    </div>
                  </div>

                  {/* 存储的SVG元素详情 */}
                  {debugData.storageData.editorData.svgElements && debugData.storageData.editorData.svgElements.length > 0 && (
                    <div className="storage-elements">
                      <h5>📋 存储的SVG元素</h5>
                      <div className="elements-list">
                        {debugData.storageData.editorData.svgElements.map((element, index) => (
                          <div key={index} className="element-item">
                            <span className="element-type">{element.type}</span>
                            <span className="element-id">#{element.id}</span>
                            {element.semanticTag && (
                              <span className="element-tag">[{element.semanticTag}]</span>
                            )}
                          </div>
                        ))}
                      </div>
                    </div>
                  )}

                  {/* 存储的设计规则详情 */}
                  {debugData.storageData.designRules && debugData.storageData.designRules.length > 0 && (
                    <div className="storage-elements">
                      <h5>📋 存储的设计规则</h5>
                      <div className="elements-list">
                        {debugData.storageData.designRules.map((rule, index) => (
                          <div key={index} className="element-item">
                            <span className="element-type">{rule.type}</span>
                            <span className="element-id">#{rule.id}</span>
                            {rule.name && (
                              <span className="element-tag">[{rule.name}]</span>
                            )}
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              )
            ) : (
              <div className="loading-info">
                {isLoading ? '加载中...' : '点击刷新获取数据'}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default DebugPanel;