import React, { useState, useRef, useEffect, useCallback } from 'react';
import { IconEye, IconEyeInvisible, IconDelete } from '@arco-design/web-react/icon';
import { useLanguage } from '../../contexts/LanguageContext';
import './LayerPanel.css';

const LayerPanel = ({
  elements,
  selectedElementIds,
  selectedGroupId,
  groups,
  groupedElements,
  onSelectionChange,
  onElementUpdate,
  onDeleteElements,
  onGroupSelection, // 新增：组合选择回调
  onUngroupElements, // 新增：解散组合回调
  onElementOrderChange, // 新增：元素层级调整回调
  onElementReorder // 新增：拖拽重新排序回调
}) => {
  const { t } = useLanguage();
  const [editingLayerId, setEditingLayerId] = useState(null);
  const [editingName, setEditingName] = useState('');
  const [expandedGroups, setExpandedGroups] = useState(new Set()); // 展开的组合
  const [draggedElement, setDraggedElement] = useState(null); // 被拖拽的元素
  const [, setDragOverInfo] = useState({ insertIndex: null, showLineAt: null, position: null }); // 拖拽悬停的位置信息
  const [isDragging, setIsDragging] = useState(false); // 是否正在拖拽
  const inputRef = useRef(null);
  

  // 🔧 生成唯一的显示名称，按创建顺序（定义顺序）排列_n后缀
  const generateUniqueDisplayName = (element, index) => {
    // 直接返回原始语义标签，与Tag Preview完全一致
    if (element.semanticTag) {
      return element.semanticTag;
    }
    
    // 如果没有语义标签，使用默认名称
    return `${element.type}_${index + 1}`;
  };
  // 处理图层点击
  const handleLayerClick = (elementId, event) => {
    console.log('图层点击:', elementId);
    if (event.ctrlKey || event.metaKey) {
      // 多选
      const newSelection = selectedElementIds.includes(elementId)
        ? selectedElementIds.filter(id => id !== elementId)
        : [...selectedElementIds, elementId];
      onSelectionChange(newSelection);
    } else {
      // 单选
      onSelectionChange([elementId]);
    }
  };

  // 改进的拖拽处理 - 更稳定和直观
  const handleInteractionStart = (elementId, event) => {
    console.log('🎯 [拖拽] 交互开始:', elementId);
    
    event.preventDefault();
    event.stopPropagation();
    
    let startY = event.clientY;
    let startTime = Date.now();
    let isDragging = false;
    let dragIndicatorElement = null;
    
    // 创建拖拽指示器 - 限制在图层面板内
    const createDragIndicator = () => {
      const layerPanel = document.querySelector('.layer-panel');
      if (!layerPanel) return null;
      
      const indicator = document.createElement('div');
      indicator.style.position = 'absolute';
      indicator.style.height = '2px';
      indicator.style.backgroundColor = '#165dff';
      indicator.style.zIndex = '1000';
      indicator.style.pointerEvents = 'none';
      indicator.style.borderRadius = '1px';
      
      // 限制指示器在图层面板范围内
      const panelRect = layerPanel.getBoundingClientRect();
      indicator.style.left = `${panelRect.left}px`;
      indicator.style.width = `${panelRect.width}px`;
      
      return indicator;
    };
    
    const handleMove = (e) => {
      const currentY = e.clientY;
      const deltaY = Math.abs(currentY - startY);
      const deltaTime = Date.now() - startTime;
      
      // 更严格的拖拽触发条件
      if (!isDragging && (deltaY > 8 && deltaTime > 100)) {
        isDragging = true;
        console.log('🔥 [拖拽] 开始拖拽:', elementId);
        setDraggedElement(elementId);
        setIsDragging(true);
        
        // 创建拖拽指示器
        dragIndicatorElement = createDragIndicator();
        document.body.appendChild(dragIndicatorElement);
        
        // 添加拖拽中的视觉状态
        document.body.style.cursor = 'grabbing';
      }
      
      if (isDragging && dragIndicatorElement) {
        // 简化的插入位置计算
        const targetInfo = getSimpleDropTarget(currentY);
        
        if (targetInfo) {
          // 显示插入指示器
          dragIndicatorElement.style.top = `${targetInfo.y}px`;
          dragIndicatorElement.style.display = 'block';
          
          // 更新状态
          setDragOverInfo({
            insertIndex: targetInfo.insertIndex,
            showLineAt: targetInfo.displayIndex,
            position: targetInfo.position
          });
        } else {
          dragIndicatorElement.style.display = 'none';
        }
      }
    };
    
    const handleEnd = (e) => {
      console.log('🏁 [拖拽] 交互结束, isDragging:', isDragging);
      
      // 清理事件监听器
      document.removeEventListener('mousemove', handleMove);
      document.removeEventListener('mouseup', handleEnd);
      document.removeEventListener('touchmove', handleMove);
      document.removeEventListener('touchend', handleEnd);
      
      // 清理拖拽指示器
      if (dragIndicatorElement) {
        document.body.removeChild(dragIndicatorElement);
        dragIndicatorElement = null;
      }
      document.body.style.cursor = '';
      
      if (isDragging) {
        // 执行拖拽重排
        const targetInfo = getSimpleDropTarget(e.clientY);
        if (targetInfo && onElementReorder) {
          const draggedIndex = elements.findIndex(el => el.id === elementId);
          if (draggedIndex !== -1 && draggedIndex !== targetInfo.insertIndex) {
            console.log(`🚀 [拖拽] 重新排序: 当前位置=${draggedIndex}, 目标位置=${targetInfo.insertIndex}`);
            console.log(`🚀 [拖拽] 元素数组长度=${elements.length}, 显示索引=${targetInfo.displayIndex}`);
            onElementReorder(elementId, targetInfo.insertIndex);
          }
        }
      } else {
        // 普通点击
        handleLayerClick(elementId, event);
      }
      
      // 重置状态
      setTimeout(() => {
        setDraggedElement(null);
        setDragOverInfo({ insertIndex: null, showLineAt: null, position: null });
        setIsDragging(false);
      }, 50);
    };
    
    // 添加事件监听器
    document.addEventListener('mousemove', handleMove, { passive: false });
    document.addEventListener('mouseup', handleEnd);
    document.addEventListener('touchmove', handleMove, { passive: false });
    document.addEventListener('touchend', handleEnd);
  };

  // 简化的拖拽目标计算 - 更直观和准确
  const getSimpleDropTarget = useCallback((mouseY) => {
    const layerList = document.querySelector('.layer-list');
    if (!layerList) return null;
    
    const layerItems = layerList.querySelectorAll('.layer-item:not(.group-item)');
    if (layerItems.length === 0) return null;
    
    // 找到最接近的图层项
    let closestItem = null;
    let closestDistance = Infinity;
    let closestIndex = -1;
    
    for (let i = 0; i < layerItems.length; i++) {
      const item = layerItems[i];
      const rect = item.getBoundingClientRect();
      const itemCenterY = rect.top + rect.height / 2;
      const distance = Math.abs(mouseY - itemCenterY);
      
      if (distance < closestDistance) {
        closestDistance = distance;
        closestItem = item;
        closestIndex = i;
      }
    }
    
    if (!closestItem) return null;
    
    const rect = closestItem.getBoundingClientRect();
    const isUpperHalf = mouseY < (rect.top + rect.height / 2);
    
    // 计算实际的数组插入位置
    // 显示顺序是反序的，所以需要转换
    let insertIndex;
    let indicatorY;
    
    if (isUpperHalf) {
      // 插入到当前元素之前（在显示中是上方）
      // 显示索引 closestIndex 对应的数组索引是 elements.length - 1 - closestIndex
      // 要插入到它前面，就是插入到更大的索引位置
      insertIndex = elements.length - closestIndex;
      indicatorY = rect.top;
    } else {
      // 插入到当前元素之后（在显示中是下方）
      // 要插入到它后面，就是插入到更小的索引位置
      insertIndex = elements.length - 1 - closestIndex;
      indicatorY = rect.bottom;
    }
    
    // 确保插入索引在有效范围内
    insertIndex = Math.max(0, Math.min(elements.length, insertIndex));
    
    console.log(`📍 [计算] 显示索引=${closestIndex}, 数组索引=${elements.length - 1 - closestIndex}, ${isUpperHalf ? '上半部' : '下半部'}, 插入索引=${insertIndex}`);
    
    return {
      insertIndex,
      displayIndex: closestIndex,
      position: isUpperHalf ? 'top' : 'bottom',
      y: indicatorY
    };
  }, [elements]);

  // 处理组合点击
  const handleGroupClick = (groupId, event) => {
    if (onGroupSelection) {
      onGroupSelection(groupId);
    }
  };

  // 切换组合展开/收起状态
  const toggleGroupExpansion = (groupId, event) => {
    event.stopPropagation();
    const newExpanded = new Set(expandedGroups);
    if (newExpanded.has(groupId)) {
      newExpanded.delete(groupId);
    } else {
      newExpanded.add(groupId);
    }
    setExpandedGroups(newExpanded);
  };

  // 检查元素是否在组合中 (当前未使用，为未来功能预留)
  // const isElementInGroup = (elementId) => {
  //   return groupedElements && groupedElements.has(elementId);
  // };

  // 获取元素所在的组合ID (当前未使用，为未来功能预留)
  // const getElementGroupId = (elementId) => {
  //   return groupedElements ? groupedElements.get(elementId) : null;
  // };

  // 构建层次化的图层结构（反转顺序，顶层元素显示在上方）
  const buildLayerHierarchy = () => {
    if (!groups || !groupedElements) {
      return elements.map((element, index) => ({
        type: 'element',
        element,
        index
      })).reverse(); // 反转数组，让顶层元素显示在面板顶部
    }

    const hierarchy = [];
    const processedElements = new Set();
    const processedGroups = new Set();

    // 首先处理所有组合
    for (const [groupId, group] of groups) {
      if (processedGroups.has(groupId)) continue;
      
      hierarchy.push({
        type: 'group',
        groupId,
        group,
        expanded: expandedGroups.has(groupId),
        elements: group.elements.map(elementId => {
          const element = elements.find(el => el.id === elementId);
          const index = elements.findIndex(el => el.id === elementId);
          processedElements.add(elementId);
          return { element, index };
        }).filter(item => item.element)
      });
      
      processedGroups.add(groupId);
    }

    // 然后处理未组合的元素
    elements.forEach((element, index) => {
      if (!processedElements.has(element.id)) {
        hierarchy.push({
          type: 'element',
          element,
          index
        });
      }
    });

    return hierarchy.reverse(); // 反转整个层级结构，确保顶层元素在面板顶部
  };

  const toggleVisibility = (elementId) => {
    const element = elements.find(el => el.id === elementId);
    if (element) {
      onElementUpdate(elementId, { 
        opacity: element.opacity === 0 ? 1 : 0 
      });
    }
  };

  const deleteLayer = (elementId) => {
    if (onDeleteElements) {
      onDeleteElements([elementId]);
    }
  };

  // 双击开始编辑图层名称
  const handleLayerNameDoubleClick = (elementId, currentName) => {
    setEditingLayerId(elementId);
    setEditingName(currentName);
  };

  // 保存图层名称编辑
  const saveLayerName = (elementId) => {
    if (editingName.trim() && onElementUpdate) {
      onElementUpdate(elementId, { semanticTag: editingName.trim() });
    }
    setEditingLayerId(null);
    setEditingName('');
  };

  // 取消编辑
  const cancelEditing = () => {
    setEditingLayerId(null);
    setEditingName('');
  };

  // 处理输入框键盘事件
  const handleInputKeyDown = (e, elementId) => {
    if (e.key === 'Enter') {
      saveLayerName(elementId);
    } else if (e.key === 'Escape') {
      cancelEditing();
    }
  };

  // 输入框获得焦点后选中文本
  useEffect(() => {
    if (editingLayerId && inputRef.current) {
      inputRef.current.focus();
      inputRef.current.select();
    }
  }, [editingLayerId]);

  // 组件卸载时清理（预留，实际清理在每个事件处理器中完成）
  useEffect(() => {
    return () => {
      // 由于事件监听器是动态添加和移除的，不需要额外清理
    };
  }, []);

  const getLayerIcon = (element) => {
    switch (element.type) {
      case 'rect': return '▭';
      case 'circle': return '●';
      case 'ellipse': return '⬭';
      case 'polygon':
        if (element.shapeType === 'triangle') return '△';
        if (element.shapeType === 'diamond') return '◆';
        if (element.shapeType === 'star') return '★';
        return '⬟';
      case 'line': return '│';
      case 'path': 
        if (element.shapeType === 'arc') return '◜';
        return '✎';
      default: return '?';
    }
  };



  // 简化的拖拽样式 - 只需要基础的拖拽状态
  const getDragOverClass = (displayIndex) => {
    // 新的实现使用动态创建的指示器，不需要复杂的CSS类
    return '';
  };

  // 处理点击空白区域退出编辑模式
  const handlePanelClick = (e) => {
    // 如果点击的不是输入框或图层名称，则退出编辑模式
    if (editingLayerId && !e.target.closest('.layer-name-input')) {
      cancelEditing();
    }
  };

  return (
    <div className={`layer-panel ${isDragging ? 'dragging' : ''}`} onClick={handlePanelClick}>
      <div className="layer-content">
        <div className="layer-header" style={{ display: 'none' }}>
          <span>图层列表</span>
        </div>
        
        <div className="layer-list">
          {buildLayerHierarchy().map((item) => {
            if (item.type === 'group') {
              return (
                <div key={item.groupId} className="group-container">
                  {/* 组合标题行 */}
                  <div
                    className={`layer-item group-item ${selectedGroupId === item.groupId ? 'selected' : ''}`}
                    onClick={(e) => handleGroupClick(item.groupId, e)}
                  >
                    <div className="layer-info">
                      <button
                        className="group-toggle"
                        onClick={(e) => toggleGroupExpansion(item.groupId, e)}
                      >
                        {item.expanded ? '▼' : '▶'}
                      </button>
                      <span className="layer-icon">📁</span>
                      <span className="layer-name group-name">
                        组合
                      </span>
                    </div>
                    
                    <div className="layer-controls">
                      <button
                        className="ungroup-btn"
                        onClick={(e) => {
                          e.stopPropagation();
                          if (onUngroupElements) {
                            onUngroupElements(item.groupId);
                          }
                        }}
                        title={t('designerPage.layerPanel.ungroupButton')}
                      >
                        🔗
                      </button>
                    </div>
                  </div>
                  
                  {/* 组合内的元素（展开时显示） */}
                  {item.expanded && (
                    <div className="group-children">
                      {item.elements.map(({ element, index }) => (
                        <div
                          key={element.id}
                          className={`layer-item child-item ${selectedElementIds.includes(element.id) ? 'selected' : ''} ${draggedElement === element.id ? 'dragging' : ''} ${getDragOverClass(index)}`}
                          onMouseDown={(e) => handleInteractionStart(element.id, e)}
                          onTouchStart={(e) => handleInteractionStart(element.id, e)}
                        >
                          <div className="layer-info">
                            <span className="child-indent">└─</span>
                            <span className="layer-icon">{getLayerIcon(element)}</span>
                            {editingLayerId === element.id ? (
                              <input
                                ref={inputRef}
                                type="text"
                                value={editingName}
                                onChange={(e) => setEditingName(e.target.value)}
                                onKeyDown={(e) => handleInputKeyDown(e, element.id)}
                                onBlur={() => saveLayerName(element.id)}
                                className="layer-name-input"
                                onClick={(e) => e.stopPropagation()}
                              />
                            ) : (
                              <span
                                className="layer-name"
                                title={(element.semanticTag && element.semanticTag.trim()) || generateUniqueDisplayName(element, index)}
                                onDoubleClick={(e) => {
                                  e.stopPropagation();
                                  handleLayerNameDoubleClick(element.id, (element.semanticTag && element.semanticTag.trim()) || generateUniqueDisplayName(element, index));
                                }}
                              >
                                {(element.semanticTag && element.semanticTag.trim()) || generateUniqueDisplayName(element, index)}
                              </span>
                            )}
                          </div>
                          
                          <div className="layer-controls">
                            
                            <button
                              className={`visibility-btn ${element.opacity === 0 ? 'hidden' : ''}`}
                              onClick={(e) => {
                                e.stopPropagation();
                                toggleVisibility(element.id);
                              }}
                              title={element.opacity === 0 ? t('designerPage.layerPanel.show') : t('designerPage.layerPanel.hide')}
                            >
                              {element.opacity === 0 ? <IconEyeInvisible /> : <IconEye />}
                            </button>
                            <button
                              className="visibility-btn"
                              onClick={(e) => {
                                e.stopPropagation();
                                deleteLayer(element.id);
                              }}
                              title={t('designerPage.layerPanel.deleteLayer')}
                            >
                              <IconDelete />
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            } else {
              // 普通元素
              const { element, index } = item;
              return (
                <div
                  key={element.id}
                  className={`layer-item ${selectedElementIds.includes(element.id) ? 'selected' : ''} ${draggedElement === element.id ? 'dragging' : ''} ${getDragOverClass(index)}`}
                  onMouseDown={(e) => handleInteractionStart(element.id, e)}
                  onTouchStart={(e) => handleInteractionStart(element.id, e)}
                >
                  <div className="layer-info">
                    <span className="layer-icon">{getLayerIcon(element)}</span>
                    {editingLayerId === element.id ? (
                      <input
                        ref={inputRef}
                        type="text"
                        value={editingName}
                        onChange={(e) => setEditingName(e.target.value)}
                        onKeyDown={(e) => handleInputKeyDown(e, element.id)}
                        onBlur={() => saveLayerName(element.id)}
                        className="layer-name-input"
                        onClick={(e) => e.stopPropagation()}
                      />
                    ) : (
                      <span
                        className="layer-name"
                        title={(element.semanticTag && element.semanticTag.trim()) || generateUniqueDisplayName(element, index)}
                        onDoubleClick={(e) => {
                          e.stopPropagation();
                          handleLayerNameDoubleClick(element.id, (element.semanticTag && element.semanticTag.trim()) || generateUniqueDisplayName(element, index));
                        }}
                      >
                        {(element.semanticTag && element.semanticTag.trim()) || generateUniqueDisplayName(element, index)}
                      </span>
                    )}
                  </div>
                  
                  <div className="layer-controls">
                    
                    <button
                      className={`visibility-btn ${element.opacity === 0 ? 'hidden' : ''}`}
                      onClick={(e) => {
                        e.stopPropagation();
                        toggleVisibility(element.id);
                      }}
                      title={element.opacity === 0 ? '显示' : '隐藏'}
                    >
                      {element.opacity === 0 ? <IconEyeInvisible /> : <IconEye />}
                    </button>
                    <button
                      className="visibility-btn"
                      onClick={(e) => {
                        e.stopPropagation();
                        deleteLayer(element.id);
                      }}
                      title="删除图层"
                    >
                      <IconDelete />
                    </button>
                  </div>
                </div>
              );
            }
          })}
          
          {elements.length === 0 && (
            <div className="no-layers">
              暂无图层
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default LayerPanel;
