import React, { useState, useEffect } from 'react';
import { useLanguage } from '../contexts/LanguageContext';
import './ChatInterface.css';
import { getSmartBackendUrl } from '../utils/env';

// 确保API基础URL正确格式化
const API_BASE_URL = getSmartBackendUrl();

// 调试信息
const debug = {
  log: (action, message, data = null) => {
    console.log(`[${new Date().toISOString()}] ${action}:`, message, data);
  },
  error: (action, error, context = null) => {
    console.error(
      `[${new Date().toISOString()}] Error in ${action}:`,
      '\nError:', error,
      '\nContext:', context
    );
  }
};

// 添加调试信息
debug.log('Config', '使用的API基础URL', API_BASE_URL);

const ChatInterface = () => {
  const { t } = useLanguage();
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [extendedThinking, setExtendedThinking] = useState(false);
  const [thinking, setThinking] = useState(null);
  const [provider, setProvider] = useState('claude');
  const [model, setModel] = useState('');

  // 根据提供商设置默认模型
  useEffect(() => {
    setModel(provider === 'claude' ? 'claude-sonnet-4-6' : 'mistral-medium');
  }, [provider]);

  // 在组件挂载时验证API URL
  useEffect(() => {
    debug.log('Config', 'API Base URL', API_BASE_URL);
    if (!API_BASE_URL) {
      debug.error('Config', 'API Base URL is not configured');
      setError(t('chatInterface.backendNotConfigured'));
    }
    try {
      new URL(API_BASE_URL); // 验证URL格式
    } catch (e) {
      debug.error('Config', 'Invalid API Base URL', { url: API_BASE_URL, error: e });
      setError(t('chatInterface.networkError'));
    }
  }, []);

  const handleSendMessage = async (e) => {
    e.preventDefault();
    if (inputMessage.trim() && !loading) {
      setLoading(true);
      setError(null);
      setThinking(null);
      
      debug.log('Send', 'Preparing to send message', {
        messageLength: inputMessage.length,
        existingMessages: messages.length,
        provider,
        model
      });

      // 创建新的用户消息
      const userMessage = {
        role: 'user',
        content: inputMessage,
        timestamp: new Date().toISOString()
      };

      // 添加用户消息到界面
      setMessages(prevMessages => [...prevMessages, userMessage]);
      setInputMessage('');

      try {
        if (!API_BASE_URL) {
          throw new Error(t('chatInterface.backendNotConfigured'));
        }

        // 1. 首先获取对话回复
        const chatResponse = await fetch(`${API_BASE_URL}/api/chat`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            messages: [...messages, userMessage],
            extendedThinking,
            provider,
            model
          })
        });

        if (!chatResponse.ok) {
          throw new Error(`HTTP error! status: ${chatResponse.status}`);
        }

        const chatData = await chatResponse.json();
        debug.log('Chat Response', 'Received chat response', {
          messageLength: chatData.message.length,
          processingTime: chatData.processingTime,
          hasThinking: !!chatData.thinking
        });
        
        // 保存思考过程（如果有）
        if (chatData.thinking) {
          setThinking(chatData.thinking);
        }

        // 添加助手回复到消息历史
        const assistantMessage = {
          role: 'assistant',
          content: chatData.message,
          timestamp: new Date().toISOString()
        };
        setMessages(prevMessages => [...prevMessages, assistantMessage]);

        // 获取默认表情并更新
        const defaultExpression = window.getDefaultExpression?.();
        console.log('🔍 Debug: Default expression check', {
          hasDefaultExpression: !!defaultExpression,
          hasCode: !!defaultExpression?.code,
          codeLength: defaultExpression?.code?.length || 0
        });
        
        if (defaultExpression?.code) {
          // 获取 ExpressionDisplay 中的模型设置
          const expressionProvider = window.getExpressionProvider?.() || 'claude';
          const expressionModel = window.getExpressionModel?.() || 'claude-sonnet-4-6';

          // 获取Extended Thinking设置
          const expressionExtendedThinking = window.getExtendedThinking?.() || false;
          
          console.log('🔍 Debug: Expression update parameters', {
            provider: expressionProvider,
            model: expressionModel,
            extendedThinking: expressionExtendedThinking,
            messagesCount: messages.length + 2
          });

          // 获取新的SVG表情代码
          debug.log('SVG Expression Request', 'Sending request to', { 
            url: `${API_BASE_URL}/api/svg-expression/vary`,
            messagesCount: messages.length + 2,  // 包含新添加的用户消息和助手回复
            baseExpressionLength: defaultExpression.code.length,
            provider: expressionProvider,
            model: expressionModel,
            extendedThinking: expressionExtendedThinking
          });

          const expressionResponse = await fetch(`${API_BASE_URL}/api/svg-expression/vary`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({
              messages: [...messages, userMessage, assistantMessage],
              baseExpression: defaultExpression,
              provider: expressionProvider,
              model: expressionModel,
              extendedThinking: expressionExtendedThinking
            })
          });

          if (!expressionResponse.ok) {
            throw new Error(`HTTP error! status: ${expressionResponse.status}`);
          }

          const expressionData = await expressionResponse.json();
          debug.log('SVG Expression Response', 'Received SVG expression response', {
            codeLength: expressionData.expression?.code?.length || 0,
            status: expressionResponse.status,
            provider: expressionProvider,
            model: expressionModel,
            hasThinking: !!expressionData.thinking
          });

          // 更新表情
          console.log('🔍 Debug: Expression API response', {
            hasExpression: !!expressionData.expression,
            hasCode: !!expressionData.expression?.code,
            codeLength: expressionData.expression?.code?.length || 0,
            hasUpdateFunction: !!window.updateExpression
          });
          
          if (expressionData.expression?.code) {
            debug.log('SVG Expression Update', 'Updating expression with new SVG code', {
              codeLength: expressionData.expression.code.length
            });
            console.log('🔍 Debug: Calling updateExpression with:', expressionData.expression);
            window.updateExpression?.(expressionData.expression);
          } else {
            debug.error('SVG Expression Update', 'No SVG code received in response');
          }
        } else {
          debug.error('Expression Update', 'No default expression available');
        }

      } catch (error) {
        debug.error('Request', error, {
          url: `${API_BASE_URL}/api/chat`,
          inputLength: inputMessage.length,
          messagesCount: messages.length
        });
        
        setError(error.message);
        setMessages(prevMessages => [
          ...prevMessages,
          { 
            role: 'assistant', 
            content: t('chatInterface.errorMessage'),
            timestamp: new Date().toISOString()
          }
        ]);
      } finally {
        setLoading(false);
      }
    }
  };

  return (
    <div className="chat-interface">
      <div className="chat-header">
        <h2>{t('chatInterface.title')}</h2>
        <div className="session-info">
          <div>API URL: {API_BASE_URL || 'Not configured'}</div>
          <div>Messages: {messages.length}</div>
          <div className="provider-selector">
            <div className="model-group">
              <h3>{t('chatInterface.model')}</h3>
              <select
                value={provider}
                onChange={(e) => setProvider(e.target.value)}
                disabled={loading}
              >
                <option value="claude">Claude</option>
                <option value="mistral">Mistral</option>
              </select>
              <select
                value={model}
                onChange={(e) => setModel(e.target.value)}
                disabled={loading}
              >
                {provider === 'claude' ? (
                  <>
                    <option value="claude-sonnet-4-6">Claude Sonnet 4-6</option>
                    <option value="claude-opus-4-6">Claude Opus 4-6</option>
                  </>
                ) : (
                  <>
                    <option value="mistral-small">Mistral Small</option>
                    <option value="mistral-medium">Mistral Medium</option>
                    <option value="mistral-large">Mistral Large</option>
                  </>
                )}
              </select>
            </div>
          </div>
          <div className="extended-thinking-toggle">
            <label>
              <input
                type="checkbox"
                checked={extendedThinking}
                onChange={(e) => setExtendedThinking(e.target.checked)}
                disabled={provider === 'mistral'} // Mistral 不支持 Extended Thinking
              />
              {t('chatInterface.extendedThinking')}
            </label>
          </div>
          {error && <div className="error-message">{t('common.error')}: {error}</div>}
        </div>
      </div>
      
      <div className="messages-container">
        {messages.map((message, index) => (
          <div
            key={index}
            className={`message ${message.role === 'user' ? 'user-message' : 'bot-message'}`}
          >
            <div className="message-content">{message.content}</div>
            <div className="message-timestamp">{new Date(message.timestamp).toLocaleTimeString()}</div>
          </div>
        ))}
        {loading && (
          <div className="message bot-message loading">
            {t('chatInterface.thinking')}
          </div>
        )}
        {thinking && (
          <div className="message thinking-message">
            <div className="thinking-header">{t('chatInterface.extendedThinking')}:</div>
            <div className="thinking-content">{thinking}</div>
          </div>
        )}
      </div>

      <form className="input-container" onSubmit={handleSendMessage}>
        <textarea
          value={inputMessage}
          onChange={(e) => setInputMessage(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault();
              handleSendMessage(e);
            }
          }}
          placeholder={t('chatInterface.placeholder')}
          className="message-input"
          disabled={loading || !!error}
          rows="3"
        />
        <button 
          type="submit" 
          className="send-button"
          disabled={loading || !!error}
        >
          {loading ? t('chatInterface.generating') : t('chatInterface.sendButton')}
        </button>
      </form>
    </div>
  );
};

export default ChatInterface; 