// 🔧 从semanticTag推断表单字段值
const inferFormFieldsFromSemanticTag = (semanticTag) => {
  if (!semanticTag) {
    return { elementType: '器官', organType: '', moreDescription: '' };
  }
  
  // 尝试精确匹配
  const exactMatch = SEMANTIC_TAG_TO_FORM_MAPPING[semanticTag.toLowerCase()];
  if (exactMatch) {
    return { ...exactMatch, moreDescription: '' };
  }
  
  // 如果没有精确匹配，返回默认值但保留原始语义标签信息
  // 这样用户至少能看到原有的语义标签，不会被意外清空
  return { elementType: '器官', organType: '', moreDescription: '' };
};

// 工具：去除末尾重复的 -area 后缀（防双重追加）
const stripAreaSuffix = (tag = '') => {
  let out = String(tag || '');
  // 连续去除末尾的 -area（防止多次叠加）
  while (out.toLowerCase().endsWith('-area')) {
    out = out.slice(0, -5);
  }
  return out;
};

// 生成完整语义标签的函数 - 只包含器官类型，不包含描述
const generateSemanticTag = (formData, isArea = false) => {
  let baseTag = '';
  // 如果是自定义类型，返回自定义标签名称
  if (formData.organType === 'custom') {
    baseTag = stripAreaSuffix(formData.customTagName || '');
  } else {
    baseTag = formData.organType || '';
  }
  
  // 如果是区域元素，添加 -area 后缀
  if (isArea && baseTag) {
    // 避免重复追加 -area
    return baseTag.toLowerCase().endsWith('-area') ? baseTag : `${baseTag}-area`;
  }
  
  return baseTag;
};

const Inspector = ({ selectedElements = [], onElementUpdate, versionType = 'role' }) => {
  const { t, language } = useLanguage();
  const selectedElement = selectedElements.length === 1 ? selectedElements[0] : null;
  const hasSelection = selectedElements.length > 0;
  
  // 获取语义标签的显示名称 - 英文显示原始标签，中文显示翻译
  const getSemanticTagDisplayName = (semanticTag) => {
    // 英文模式下直接返回原始标签，保持与Tag Preview一致
    if (language === 'en-US') {
      return semanticTag;
    }
    
    // 中文模式下使用国际化翻译
    const keyMap = {
      'face': 'face',
      'left-eye': 'leftEye',
      'right-eye': 'rightEye',
      'nose': 'nose',
      'mouth': 'mouth',
      'left-ear': 'leftEar',
      'right-ear': 'rightEar',
      'clothing': 'clothing',
      'hat': 'hat',
      'jewellery': 'jewellery',
      'color': 'color',
      'scene-item': 'sceneItem',
      'scene': 'scene',
      'emoji': 'emoji',
      'text': 'text',
      'face-area': 'faceArea',
      'left-eye-area': 'leftEyeArea',
      'right-eye-area': 'rightEyeArea',
      'nose-area': 'noseArea',
      'mouth-area': 'mouthArea',
      'left-ear-area': 'leftEarArea',
      'right-ear-area': 'rightEarArea',
      'clothing-area': 'clothingArea',
      'hat-area': 'hatArea',
      'jewellery-area': 'jewelleryArea',
      'color-area': 'colorArea',
      'scene-item-area': 'sceneItemArea',
      'scene-area': 'sceneArea',
      'emoji-area': 'emojiArea',
      'text-area': 'textArea'
    };
    
    const key = keyMap[semanticTag];
    return key ? t(`designerPage.inspector.semanticTags.${key}`) : semanticTag;
  };
  
  // 动态语义规则映射状态
  const [semanticRuleMapping, setSemanticRuleMapping] = useState({});
  const [mappingLoading, setMappingLoading] = useState(false);
  const [mappingError, setMappingError] = useState(null);
  
  // 获取语义规则映射
  const fetchSemanticRuleMapping = useCallback(async (mode, isArea) => {
    try {
      setMappingLoading(true);
      setMappingError(null);
      
      // 使用智能后端URL，避免在HTTPS页面下请求HTTP导致的混合内容拦截
      const backendUrl = getSmartBackendUrl();
      const response = await fetch(`${backendUrl}/api/semantic-rules?mode=${mode}&isArea=${isArea}&locale=${language}`);
      
      if (!response.ok) {
        throw new Error(`${t('designerPage.inspector.fetchSemanticRuleFailed')}: ${response.status}`);
      }
      
      const data = await response.json();
      
      if (data.success) {
        setSemanticRuleMapping(data.mapping);
      } else {
        throw new Error(data.error || t('designerPage.inspector.fetchSemanticRuleFailed'));
      }
    } catch (error) {
      console.error(t('designerPage.inspector.fetchSemanticRuleFailed') + ':', error);
      setMappingError(error.message);
      // 降级使用硬编码映射表
      setSemanticRuleMapping(getLocalSemanticRuleMapping(mode, isArea));
    } finally {
      setMappingLoading(false);
    }
  }, []);
  
  // 降级方案：使用本地硬编码映射表
  const getLocalSemanticRuleMapping = (mode, isArea) => {
    if (mode === 'expression') {
      return isArea ? SEMANTIC_RULE_MAPPING_EXPRESSION_AREA : SEMANTIC_RULE_MAPPING_EXPRESSION;
    } else {
      return isArea ? SEMANTIC_RULE_MAPPING_ROLE_AREA : SEMANTIC_RULE_MAPPING_ROLE;
    }
  };
  
  // 当版本类型或选中元素变化时，获取对应的映射规则
  useEffect(() => {
    const isArea = selectedElement?.isArea || false;
    fetchSemanticRuleMapping(versionType, isArea);
  }, [versionType, selectedElement?.isArea, fetchSemanticRuleMapping]);
  
  // 表单状态
  const [elementType, setElementType] = useState('器官'); // 器官、装饰、上下文
  const [organType, setOrganType] = useState('');
  const [moreDescription, setMoreDescription] = useState('');
  const [customTagName, setCustomTagName] = useState(''); // 自定义标签名称
  
  // 🔧 添加初始化标志，防止初始化时触发不必要的更新
  const [isInitializing, setIsInitializing] = useState(false);

  // 器官类型选项 - 使用国际化
  const organOptions = {
    [t('designerPage.inspector.elementTypes.organ')]: t('designerPage.inspector.organOptions'),
    [t('designerPage.inspector.elementTypes.context')]: t('designerPage.inspector.contextOptions'),
    [t('designerPage.inspector.elementTypes.decoration')]: t('designerPage.inspector.decorationOptions')
  };

  // 🔧 当选中元素变化时，智能同步属性到表单
  useEffect(() => {
    setIsInitializing(true); // 标记开始初始化
    
    if (!selectedElement) {
      // 没有选中元素时，重置表单
      setElementType(t('designerPage.inspector.elementTypes.organ'));
      setOrganType('');
      setMoreDescription('');
      setCustomTagName('');
      setTimeout(() => setIsInitializing(false), 0); // 异步结束初始化标志
      return;
    }

    // 优先使用semanticProperties中的完整信息
    if (selectedElement.semanticProperties) {
      const props = selectedElement.semanticProperties;
      setElementType(props.elementType || t('designerPage.inspector.elementTypes.organ'));
      setOrganType(props.organType || '');
      setMoreDescription(props.moreDescription || '');
      // 如果是自定义类型，设置自定义标签名称
      if (props.organType === 'custom' && props.semanticTag) {
        setCustomTagName(stripAreaSuffix(props.semanticTag));
      } else {
        setCustomTagName('');
      }
      setTimeout(() => setIsInitializing(false), 0); // 异步结束初始化标志
      return;
    }

    // 🔧 如果没有semanticProperties，尝试从semanticTag推断
    if (selectedElement.semanticTag) {
      console.log('🔍 [Inspector] 从semanticTag推断表单字段:', selectedElement.semanticTag);
      const inferredFields = inferFormFieldsFromSemanticTag(selectedElement.semanticTag);
      setElementType(inferredFields.elementType);
      
      // 如果推断失败（organType为空），可能是自定义标签
      if (!inferredFields.organType && selectedElement.semanticTag) {
        setOrganType('custom');
        setCustomTagName(stripAreaSuffix(selectedElement.semanticTag));
      } else {
        setOrganType(inferredFields.organType);
        setCustomTagName('');
      }
      
      setMoreDescription(inferredFields.moreDescription);
      setTimeout(() => setIsInitializing(false), 0); // 异步结束初始化标志
      return;
    }

    // 🔧 如果既没有semanticProperties也没有semanticTag，才重置为空白状态
    console.log('🔍 [Inspector] 元素没有语义信息，重置表单');
    setElementType('器官');
    setOrganType('');
    setMoreDescription('');
    setCustomTagName('');
    setTimeout(() => setIsInitializing(false), 0); // 异步结束初始化标志
  }, [selectedElement]);

  // 处理字段变化并自动更新
  const handleFieldChange = useCallback((field, value) => {
    switch (field) {
      case 'elementType':
        setElementType(value);
        setOrganType(''); // 重置器官类型
        break;
      case 'organType':
        setOrganType(value);
        // 如果不是自定义，清空自定义标签名称
        if (value !== 'custom') {
          setCustomTagName('');
        }
        break;
      case 'customTagName':
        setCustomTagName(value);
        break;
      case 'moreDescription':
        setMoreDescription(value);
        break;
      default:
        break;
    }
  }, []);

  // 🔧 延迟更新元素属性 - 使用debounce避免频繁更新，并防止初始化时的意外更新
  useEffect(() => {
    // 🔧 如果正在初始化、没有选中元素或回调不存在，跳过更新
    if (isInitializing || !hasSelection || !selectedElement || !onElementUpdate) return;
    
    const timeoutId = setTimeout(() => {
      const semanticTag = generateSemanticTag({
        organType,
        customTagName
      }, selectedElement?.isArea);
      
      const semanticProperties = {
        elementType,
        organType,
        moreDescription,
        semanticTag
      };
      
      // 🔧 额外保护：如果生成的semanticTag为空，但元素原本有semanticTag，则保留原有的
      const finalSemanticTag = semanticTag || selectedElement.semanticTag || '';

      // 若无变化则跳过，避免重复更新导致的连锁反应
      const prevProps = selectedElement.semanticProperties || {};
      const noChange =
        prevProps.elementType === elementType &&
        prevProps.organType === organType &&
        prevProps.moreDescription === moreDescription &&
        (prevProps.semanticTag || '') === finalSemanticTag &&
        (selectedElement.semanticTag || '') === finalSemanticTag &&
        (selectedElement.label || '') === finalSemanticTag;

      if (noChange) return;

      console.log('🔍 [Inspector] 延迟更新元素属性:', {
        elementId: selectedElement.id,
        semanticTag: finalSemanticTag,
        semanticProperties,
        isInitializing
      });

      // 更新元素的语义属性和标签
      onElementUpdate(selectedElement.id, {
        semanticProperties,
        semanticTag: finalSemanticTag,
        label: finalSemanticTag // 同时更新label属性以保持兼容性
      });
    }, 300); // 300ms延迟
    
    return () => clearTimeout(timeoutId);
  }, [elementType, organType, moreDescription, customTagName, hasSelection, selectedElement?.id, onElementUpdate, isInitializing]);

  return (
    <div className={`inspector ${!hasSelection ? 'disabled' : ''}`}>
      <div className="inspector-content">
        {!hasSelection && (
          <div className="no-selection-message">
            <div className="message-icon">📝</div>
            <h3>{t('designerPage.panels.propertyEditor')}</h3>
            <p>{t('designerPage.inspector.selectElementMessage')}</p>
          </div>
        )}
        
        {hasSelection && selectedElements.length > 1 && (
          <div className="multi-selection-message">
            <div className="message-icon">📝</div>
            <h3>{t('designerPage.inspector.multipleElementsSelected')}</h3>
            <p>{t('designerPage.canvas.multiSelection')}</p>
          </div>
        )}

        {/* 单个元素编辑部分 */}
        {hasSelection && selectedElement && (
          <div className="element-editor">

            {/* Step1: 选择元素类型 */}
            <div className="step-section">
              <div className="step-label">{t('designerPage.inspector.addPropertyTags')}</div>
              <div className="element-type-selector">
                {(t('designerPage.inspector.typeButtons') || []).map(btn => ({
                    type: btn.type === 'organ' ? t('designerPage.inspector.elementTypes.organ') : 
                          btn.type === 'context' ? t('designerPage.inspector.elementTypes.context') :
                          t('designerPage.inspector.elementTypes.decoration'),
                    icon: btn.icon,
                    label: btn.label
                  })).map((item) => (
                  <button
                    key={item.type}
                    className={`element-type-option ${elementType === item.type ? 'active' : ''}`}
                    onClick={() => selectedElement?.semanticTag !== 'face' && handleFieldChange('elementType', item.type)}
                    disabled={selectedElement?.semanticTag === 'face'}
                    style={{
                      opacity: selectedElement?.semanticTag === 'face' ? 0.5 : 1,
                      cursor: selectedElement?.semanticTag === 'face' ? 'not-allowed' : 'pointer'
                    }}
                  >
                    <span className="element-type-icon">{item.icon}</span>
                    <span className="element-type-label">{item.label}</span>
                  </button>
                ))}
              </div>
              
              {/* 类型选择框 */}
              <div className="form-row">
                <select
                  value={organType}
                  onChange={(e) => selectedElement?.semanticTag !== 'face' && handleFieldChange('organType', e.target.value)}
                  className="form-select"
                  disabled={selectedElement?.semanticTag === 'face'}
                  style={{
                    opacity: selectedElement?.semanticTag === 'face' ? 0.5 : 1,
                    cursor: selectedElement?.semanticTag === 'face' ? 'not-allowed' : 'pointer'
                  }}
                >
                  <option value="">{t('designerPage.inspector.pleaseSelect')}</option>
                  {organOptions[elementType]?.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </div>
              
              {/* 标签示意 */}
              <div className="form-row">
                {organType === 'custom' ? (
                  <>
                    <input
                      type="text"
                      value={customTagName}
                      onChange={(e) => selectedElement?.semanticTag !== 'face' && handleFieldChange('customTagName', e.target.value)}
                      onKeyDown={(e) => {
                        // 保证删除键正常工作
                        if (e.key === 'Backspace' || e.key === 'Delete') {
                          e.stopPropagation();
                        }
                      }}
                      placeholder={t('designerPage.inspector.customTagPlaceholder')}
                      className="form-input"
                      disabled={selectedElement?.semanticTag === 'face'}
                      style={{
                        opacity: selectedElement?.semanticTag === 'face' ? 0.5 : 1,
                        cursor: selectedElement?.semanticTag === 'face' ? 'not-allowed' : 'text'
                      }}
                    />
                    <div className="custom-tag-hint" style={{
                      fontSize: '12px',
                      color: '#86909c',
                      marginTop: '13px',
                      fontStyle: 'italic'
                    }}>
                      {t('ruleEditor.hints.customTagNoRule')}
                    </div>
                  </>
                ) : null}
              </div>
            </div>

            {/* Step2: 基础设计规则或描述元素 - 只有在选择元素标签时展示 */}
            {organType && organType !== 'custom' && (
              <div className="step-section">
                {semanticRuleMapping[generateSemanticTag({ organType, customTagName }, selectedElement?.isArea)] ? (
                  // 显示基础设计规则
                  <>
                    <div className="step-label">{t('designerPage.inspector.autoAddedToSemanticRules')}</div>
                    <div className="semantic-rules-panel">
                      <div className="semantic-rules-content">
                        <div className="semantic-rules-header">
                          <span style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                            <span>🏷️</span>
                            <span>{getSemanticTagDisplayName(generateSemanticTag({ organType, customTagName }, selectedElement?.isArea))}</span>
                          </span>
                        </div>
                        <div className="semantic-rule-item">
                          <div className="semantic-rule-text">
                            {mappingLoading ? (
                              <div style={{ color: '#86909c', fontSize: '12px' }}>{t('designerPage.inspector.loadingRules')}</div>
                            ) : mappingError ? (
                              <div style={{ color: '#f53f3f', fontSize: '12px' }}>{t('designerPage.inspector.loadingFailed')}: {mappingError}</div>
                            ) : (
                              semanticRuleMapping[generateSemanticTag({ organType, customTagName }, selectedElement?.isArea)] || t('designerPage.inspector.noSemanticRule')
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  </>
                ) : (
                  // 显示传统的描述框
                  <>
                    <div className="step-label">{t('designerPage.inspector.step2DescribeElement')}</div>
                    <div className="form-row">
                      <textarea
                        value={moreDescription}
                        onChange={(e) => selectedElement?.semanticTag !== 'face' && handleFieldChange('moreDescription', e.target.value)}
                        placeholder={t('designerPage.inspector.descriptionPlaceholder')}
                        className="form-textarea"
                        rows={3}
                        disabled={selectedElement?.semanticTag === 'face'}
                        style={{
                          opacity: selectedElement?.semanticTag === 'face' ? 0.5 : 1,
                          cursor: selectedElement?.semanticTag === 'face' ? 'not-allowed' : 'text'
                        }}
                      />
                    </div>
                  </>
                )}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default Inspector;
