import React, { useState, useCallback, useEffect } from 'react';
import { getSmartBackendUrl } from '../../utils/env';
import './HistoryGeneration.css';

function HistoryGeneration({ project, isOpen, onClose, onAddToCanvas }) {
  const [historyData, setHistoryData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [selectedRole, setSelectedRole] = useState(null);
  const [previewSVG, setPreviewSVG] = useState('');
  const [showSvgCode, setShowSvgCode] = useState(false);
  const [selectedSvgCode, setSelectedSvgCode] = useState('');

  // 加载历史生成数据
  const loadHistoryData = useCallback(async () => {
    if (!project || !isOpen) return;

    setIsLoading(true);
    try {
      const response = await fetch(`${getSmartBackendUrl()}/api/designer/project/${project.id}/history`);
      const data = await response.json();
      
      if (data.success) {
        setHistoryData(data.history || []);
      } else {
        console.error('加载历史数据失败:', data.error);
        setHistoryData([]);
      }
    } catch (error) {
      console.error('加载历史数据失败:', error);
      setHistoryData([]);
    } finally {
      setIsLoading(false);
    }
  }, [project, isOpen]);

  // 在组件打开时加载数据
  useEffect(() => {
    if (isOpen) {
      loadHistoryData();
    }
  }, [isOpen, loadHistoryData]);

  // 选择角色预览
  const handleSelectRole = useCallback((roleData) => {
    setSelectedRole(roleData);
    setPreviewSVG(roleData.svgContent || '');
  }, []);

  // 添加到画布
  const handleAddToCanvas = useCallback(() => {
    if (!selectedRole) {
      alert('请先选择一个角色');
      return;
    }

    try {
      // 解析SVG内容，提取元素信息
      const parser = new DOMParser();
      const svgDoc = parser.parseFromString(selectedRole.svgContent, 'image/svg+xml');
      const svgElements = [];

      // 遍历SVG元素并转换为编辑器格式
      const elements = svgDoc.querySelectorAll('rect, circle, ellipse, path, text');
      elements.forEach((element, index) => {
        const elementData = extractElementData(element, index);
        if (elementData) {
          svgElements.push(elementData);
        }
      });

      // 调用父组件的回调函数
      if (onAddToCanvas && svgElements.length > 0) {
        onAddToCanvas(svgElements, selectedRole);
        onClose();
      } else {
        alert('无法从选定的角色中提取有效的SVG元素');
      }
    } catch (error) {
      console.error('解析SVG失败:', error);
      alert(`添加到画布失败: ${error.message}`);
    }
  }, [selectedRole, onAddToCanvas, onClose]);


  // 提取SVG元素数据
  const extractElementData = (element, index) => {
    const tagName = element.tagName.toLowerCase();
    
    // 🔧 优化ID生成：优先使用原始id，提取语义标签
    const originalId = element.getAttribute('id') || element.id || '';
    const dataSemanticAttr = element.getAttribute('data-semantic') || '';
    
    // 🔧 简化语义标签生成逻辑：严格按照用户需求
    let semanticTag = '';
    let elementId = `history_element_${Date.now()}_${index}`;
    
    // 优先级1：使用data-semantic属性
    if (dataSemanticAttr) {
      semanticTag = dataSemanticAttr;
      elementId = `history_${dataSemanticAttr}_${index}`;
    } 
    // 优先级2：如果有原始id，直接使用（不做任何推断）
    else if (originalId) {
      semanticTag = originalId.toLowerCase();
      elementId = `history_${originalId}_${index}`;
    }
    // 优先级3：没有id的元素保持空语义标签（让LayerPanel显示默认名称）
    
    console.log('🔍 SVG元素解析:', {
      tagName,
      originalId,
      dataSemanticAttr,
      extractedSemanticTag: semanticTag,
      finalElementId: elementId
    });
    
    const commonProps = {
      id: elementId,
      semanticTag: semanticTag, // 🔧 添加语义标签
      fill: element.getAttribute('fill') || '#000000',
      stroke: element.getAttribute('stroke') || '#000000',
      strokeWidth: parseFloat(element.getAttribute('stroke-width')) || 2,
      opacity: parseFloat(element.getAttribute('opacity')) || 1
    };

    switch (tagName) {
      case 'rect':
        return {
          ...commonProps,
          type: 'rectangle',
          x: parseFloat(element.getAttribute('x')) || 0,
          y: parseFloat(element.getAttribute('y')) || 0,
          width: parseFloat(element.getAttribute('width')) || 100,
          height: parseFloat(element.getAttribute('height')) || 100
        };
      
      case 'circle':
        return {
          ...commonProps,
          type: 'circle',
          cx: parseFloat(element.getAttribute('cx')) || 0,
          cy: parseFloat(element.getAttribute('cy')) || 0,
          r: parseFloat(element.getAttribute('r')) || 50
        };
      
      case 'ellipse':
        return {
          ...commonProps,
          type: 'ellipse',
          cx: parseFloat(element.getAttribute('cx')) || 0,
          cy: parseFloat(element.getAttribute('cy')) || 0,
          rx: parseFloat(element.getAttribute('rx')) || 50,
          ry: parseFloat(element.getAttribute('ry')) || 30
        };
      
      case 'path':
        return {
          ...commonProps,
          type: 'path',
          d: element.getAttribute('d') || ''
        };
      
      case 'text':
        return {
          ...commonProps,
          type: 'text',
          x: parseFloat(element.getAttribute('x')) || 0,
          y: parseFloat(element.getAttribute('y')) || 0,
          text: element.textContent || '',
          fontFamily: element.getAttribute('font-family') || 'Arial',
          fontSize: parseFloat(element.getAttribute('font-size')) || 16
          // 🔧 text元素的语义标签已在commonProps中处理，不需要特殊处理
        };
      
      default:
        return null;
    }
  };

  // 格式化时间显示
  const formatTime = useCallback((timestamp) => {
    return new Date(timestamp).toLocaleString('zh-CN', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  }, []);

  // 查看SVG代码
  const handleViewSvgCode = useCallback((svgCode) => {
    setSelectedSvgCode(svgCode);
    setShowSvgCode(true);
  }, []);

  // 关闭SVG代码查看
  const handleCloseSvgCode = useCallback(() => {
    setShowSvgCode(false);
    setSelectedSvgCode('');
  }, []);

  if (!isOpen) return null;


  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h3>历史生成 - {project.name}</h3>
          <button onClick={onClose} className="modal-close-btn">×</button>
        </div>
        
        <div className="modal-body">
          <div className="history-list-section">
            <div className="section-header">
              <h4>生成的角色</h4>
              <span className="count-badge">{historyData.length} 个角色</span>
            </div>
            
            {isLoading ? (
              <div className="loading-state">
                <p>正在加载历史数据...</p>
              </div>
            ) : historyData.length === 0 ? (
              <div className="empty-state">
                <p>暂无历史生成记录</p>
                <p>运行测试后，生成的角色将在这里显示</p>
              </div>
            ) : (
              <div className="history-list">
                {historyData.map((item) => (
                  <div 
                    key={item.id}
                    className={`history-item ${selectedRole?.id === item.id ? 'selected' : ''}`}
                    onClick={() => handleSelectRole(item)}
                  >
                    <div className="item-header">
                      <div className="item-info">
                        <span className="version-info">版本 {item.versionNumber}</span>
                        <span className="time-info">{formatTime(item.timestamp)}</span>
                      </div>
                      <div className="item-meta">
                        <span className="model-badge">{item.model}</span>
                      </div>
                    </div>
                    
                    <div className="item-content">
                      <div className="test-input">
                        <strong>输入:</strong> {item.testInput}
                      </div>
                      {item.description && (
                        <div className="description">
                          <strong>描述:</strong> {item.description}
                        </div>
                      )}
                    </div>
                    
                    <div className="item-preview">
                      {item.svgContent && (
                        <div className="svg-thumbnail" dangerouslySetInnerHTML={{ __html: item.svgContent }} />
                      )}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
          
          <div className="preview-section">
            <div className="section-header">
              <h4>预览 {selectedRole ? `- 版本 ${selectedRole.versionNumber}` : ''}</h4>
              {selectedRole && (
                <div className="preview-actions">
                  <button 
                    onClick={() => handleViewSvgCode(selectedRole.svgContent)}
                    className="view-svg-code-btn"
                    title="查看SVG代码"
                  >
                    查看SVG代码
                  </button>
                  <button 
                    onClick={handleAddToCanvas}
                    className="add-to-canvas-btn"
                  >
                    添加到画布
                  </button>
                </div>
              )}
            </div>
            
            <div className="preview-area">
              {selectedRole ? (
                <>
                  <div className="preview-info">
                    <div className="selected-role-info">
                      <h5>版本 {selectedRole.versionNumber}</h5>
                      <p><strong>输入:</strong> {selectedRole.testInput}</p>
                      <p><strong>模型:</strong> {selectedRole.model}</p>
                      <p><strong>时间:</strong> {formatTime(selectedRole.timestamp)}</p>
                    </div>
                  </div>
                  
                  <div className="preview-canvas">
                    {previewSVG ? (
                      <div 
                        className="svg-preview" 
                        dangerouslySetInnerHTML={{ __html: previewSVG }}
                      />
                    ) : (
                      <div className="no-preview">
                        <p>无预览内容</p>
                      </div>
                    )}
                  </div>
                </>
              ) : (
                <div className="select-prompt">
                  <p>选择一个角色查看预览</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
      
      {/* SVG代码查看模态框 */}
      {showSvgCode && (
        <div className="modal-overlay svg-code-overlay" onClick={handleCloseSvgCode}>
          <div className="modal-content svg-code-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>SVG代码预览</h3>
              <button 
                onClick={handleCloseSvgCode}
                className="modal-close-btn"
              >
                ×
              </button>
            </div>
            <div className="modal-body">
              <div className="svg-code-content">
                <div className="code-section">
                  <h4>SVG代码</h4>
                  <pre className="svg-code"><code>{selectedSvgCode}</code></pre>
                </div>
                <div className="preview-section">
                  <h4>预览效果</h4>
                  <div className="svg-preview-large" dangerouslySetInnerHTML={{ __html: selectedSvgCode }} />
                </div>
              </div>
              <div className="modal-actions">
                <button 
                  onClick={() => {
                    navigator.clipboard.writeText(selectedSvgCode);
                    alert('SVG代码已复制到剪贴板');
                  }}
                  className="copy-btn"
                >
                  复制SVG代码
                </button>
                <button 
                  onClick={handleCloseSvgCode}
                  className="close-btn"
                >
                  关闭
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default HistoryGeneration;