import React from 'react';
import { BrowserRouter as Router, Routes, Route, Link, useLocation } from 'react-router-dom';
import { LanguageProvider, useLanguage } from './contexts/LanguageContext';
import MainPage from './pages/MainPage';
import PromptTestPage from './pages/PromptTestPage';
import SVGTemiPage from './pages/SVGTemiPage';
import DesignerPage from './pages/DesignerPage';
import DesktopAgentPage from './pages/DesktopAgentPage';
import ServiceRobotPage from './pages/ServiceRobotPage';
import TemiVoiceTestPage from './pages/TemiVoiceTestPage';
import AiPetPage from './pages/AiPetPage';
import './App.css';

function AppContent() {
  const { t } = useLanguage();
  const location = useLocation();
  const showNavbar = location.pathname !== '/temi' && location.pathname !== '/designer' && location.pathname !== '/desktopAgent' && location.pathname !== '/aipet' && location.pathname !== '/serviceRobot';

  return (
    <>
      {showNavbar && (
        <nav className="app-nav">
          <ul>
            <li>
              <Link to="/">{t('navigation.home')}</Link>
            </li>
            <li>
              <Link to="/chat">{t('navigation.promptTest')}</Link>
            </li>
            <li>
              <Link to="/temi">{t('navigation.temi')}</Link>
            </li>
            <li>
              <Link to="/designer">{t('navigation.designer')}</Link>
            </li>
            <li>
              <Link to="/desktopAgent">{t('navigation.desktopAgent')}</Link>
            </li>
            <li>
              <Link to="/temi-voice-test">{t('navigation.temiVoiceTest')}</Link>
            </li>
          </ul>
        </nav>
      )}
      <Routes>
        <Route path="/" element={<MainPage />} />
        <Route path="/chat" element={<PromptTestPage />} />
        <Route path="/temi" element={<SVGTemiPage />} />
        <Route path="/designer" element={<DesignerPage />} />
        <Route path="/desktopAgent" element={<DesktopAgentPage />} />
        <Route path="/aipet" element={<AiPetPage />} />
        <Route path="/serviceRobot" element={<ServiceRobotPage />} />
        <Route path="/temi-voice-test" element={<TemiVoiceTestPage />} />
      </Routes>
    </>
  );
}

function App() {
  return (
    <LanguageProvider>
      <Router>
        <AppContent />
      </Router>
    </LanguageProvider>
  );
}

export default App; 
