import React, { createContext, useContext, useState, useEffect } from 'react';
import zhCN from '../locales/zh-CN.json';
import enUS from '../locales/en-US.json';

const LanguageContext = createContext();

const translations = {
  'zh-CN': zhCN,
  'en-US': enUS
};

export const LanguageProvider = ({ children }) => {
  const [language, setLanguage] = useState('zh-CN');
  const [translations_current, setTranslations] = useState(translations['zh-CN']);

  useEffect(() => {
    // 从localStorage读取保存的语言设置
    const savedLanguage = localStorage.getItem('ui_language') || 'zh-CN';
    setLanguage(savedLanguage);
    setTranslations(translations[savedLanguage] || translations['zh-CN']);
  }, []);

  const changeLanguage = (newLanguage) => {
    if (translations[newLanguage]) {
      setLanguage(newLanguage);
      setTranslations(translations[newLanguage]);
      localStorage.setItem('ui_language', newLanguage);
    }
  };

  const t = (key) => {
    const keys = key.split('.');
    let value = translations_current;
    
    for (const k of keys) {
      value = value?.[k];
      if (value === undefined) {
        console.warn(`Translation key not found: ${key}`);
        return key;
      }
    }
    
    // 确保返回正确的类型
    if (typeof value === 'string' || Array.isArray(value)) {
      return value;
    } else if (typeof value === 'object' && value !== null) {
      console.warn(`Translation key "${key}" resolves to object, not string or array:`, value);
      return key;
    }
    
    return value || key;
  };

  return (
    <LanguageContext.Provider value={{
      language,
      changeLanguage,
      t
    }}>
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a LanguageProvider');
  }
  return context;
};

export default LanguageContext;