import React, { useState } from 'react';
import './CustomizePopup.css';
import axios from 'axios';
import { getSmartBackendUrl } from '../utils/env';

const API_BASE_URL = getSmartBackendUrl();

const CustomizePopup = ({ onClose, onExpressionGenerated, customGenerate }) => {
  const [isListening, setIsListening] = useState(false);
  const [text, setText] = useState('');
  const [voiceError, setVoiceError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleVoiceClick = async () => {
    try {
      setIsListening(true);
      setVoiceError(null);
      setError(null);
      
      console.log('API_BASE_URL:', API_BASE_URL);
      const url = `${API_BASE_URL}/api/voiceInput`;
      console.log('正在发送请求到:', url);

      const response = await axios.post(url, {}, {
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      });
      
      console.log('语音输入响应:', response.data);
      
      if (response.data.result) {
        // 直接用语音识别结果更新文本框
        setText(response.data.result);
      } else {
        throw new Error('Failed to get voice input result');
      }

    } catch (error) {
      console.error('处理语音输入时出错:', error);
      setVoiceError('Voice input processing failed');
    } finally {
      setIsListening(false);
    }
  };

  const handleTextChange = (e) => {
    setText(e.target.value);
    // 清除任何错误消息
    setError(null);
    setVoiceError(null);
  };

  const generateExpression = async () => {
    if (!text.trim()) return;

    setLoading(true);
    setError(null);

    try {
      if (typeof customGenerate === 'function') {
        const expr = await customGenerate(text.trim());
        if (expr && expr.code) {
          onExpressionGenerated(expr);
          onClose();
        } else {
          throw new Error('Failed to generate SVG expression');
        }
      } else {
        console.log('正在生成SVG表情:', text);
        const url = `${API_BASE_URL}/api/svg-expression`;
        
        const response = await axios.post(url, {
          style: text,
          extendedThinking: false,
          provider: 'claude',
          model: 'claude-sonnet-4-6',
          canvasSize: { width: 400, height: 250 } // 默认画布尺寸
        }, {
          headers: {
            'Content-Type': 'application/json',
          }
        });

        console.log('SVG表情生成响应:', response.data);

        if (response.data.expression) {
          onExpressionGenerated(response.data.expression);
          onClose();
        } else {
          throw new Error('Failed to generate SVG expression');
        }
      }

    } catch (error) {
      console.error('Error generating SVG expression:', error);
      setError('Failed to generate SVG expression, please try again');
    } finally {
      setLoading(false);
    }
  };

  const handleConfirm = () => {
    if (text.trim()) {
      generateExpression();
    }
  };

  return (
    <div className="popup-overlay">
      <div className="popup-content">
        <button className="close-button" onClick={onClose}>
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
            <path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/>
          </svg>
        </button>
        <div className="customize-container">
          <h3>Customize Expression</h3>
          <div className="customize-content">
            <div className="input-section">
              <textarea
                value={text}
                onChange={handleTextChange}
                placeholder="Enter expression description or click voice input button..."
                className="customize-textarea"
              />
              <button 
                className={`voice-input-button ${isListening ? 'listening' : ''}`}
                onClick={handleVoiceClick}
                disabled={isListening || loading}
              >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">
                  <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zm5.91-3c-.49 0-.9.36-.98.85C16.52 14.2 14.47 16 12 16s-4.52-1.8-4.93-4.15c-.08-.49-.49-.85-.98-.85-.61 0-1.09.54-1 1.14.49 3 2.89 5.35 5.91 5.78V20c0 .55.45 1 1 1s1-.45 1-1v-2.08c3.02-.43 5.42-2.78 5.91-5.78.1-.6-.39-1.14-1-1.14z"/>
                </svg>
                {isListening && <span className="pulse-animation"></span>}
              </button>
            </div>
            {voiceError && <div className="voice-error">{voiceError}</div>}
            {error && <div className="error-message">{error}</div>}
            <button 
              className={`confirm-button ${(!text.trim() || loading) ? 'disabled' : ''}`}
              onClick={handleConfirm}
              disabled={!text.trim() || loading}
            >
              {loading ? 'Generating...' : 'Confirm'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default CustomizePopup; 
