import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { getSmartBackendUrl } from '../utils/env';
import { t } from '../utils/i18n';
import StepZero from '../components/aipet/StepZero';
import StepOne from '../components/aipet/StepOne';
import StepTwo from '../components/aipet/StepTwo';
import LoadingScreen from '../components/aipet/LoadingScreen';
import MagicalBackground from '../components/aipet/MagicalBackground';
import './AiPetPage.css';

const API_BASE_URL = getSmartBackendUrl();

function AiPetPage() {
  const [language, setLanguage] = useState('en');
  const [currentStep, setCurrentStep] = useState(0);
  const [showFinalLoading, setShowFinalLoading] = useState(false);
  const [isGeneratingSpirit, setIsGeneratingSpirit] = useState(false);
  const [loadingText, setLoadingText] = useState("");
  const [guardianSpiritSVG, setGuardianSpiritSVG] = useState("");
  const [loginData, setLoginData] = useState({ username: "" });
  const [userProfile, setUserProfile] = useState({ name: "" });
  const [testConfig, setTestConfig] = useState(null);
  const navigate = useNavigate();
  
  const trans = t(language);

  // Update loading text based on language
  useEffect(() => {
    setLoadingText(trans('connectingDesigner'));
  }, [language]);

  // 初始化时加载设计师配置
  useEffect(() => {
    const loadConfigData = async () => {
      try {
        // 从sessionStorage或服务器加载配置
        const configData = sessionStorage.getItem('aiPetConfig');
        if (configData) {
          const config = JSON.parse(configData);
          setTestConfig(config);
          console.log('✅ Loaded AI companion test configuration from cache');
          return;
        }

        // 从服务器加载当前配置
        const response = await fetch(`${API_BASE_URL}/api/designer/current-device-config`);
        if (response.ok) {
          const result = await response.json();
          if (result.config) {
            setTestConfig(result.config);
            sessionStorage.setItem('aiPetConfig', JSON.stringify(result.config));
            console.log('✅ Loaded AI companion test configuration from server');
          }
        } else {
          throw new Error('Cannot load configuration');
        }
      } catch (error) {
        console.error('❌ Failed to load configuration:', error);
        // 返回设计师页面
        navigate('/designer');
      }
    };

    loadConfigData();
  }, [navigate]);

  const nextStep = () => {
    setCurrentStep(prev => prev + 1);
  };

  const generateSpiritAndNextStep = async (formData) => {
    setIsGeneratingSpirit(true);
    setLoadingText(trans('generatingSpirit'));
    
    const loadingTexts = [
      trans('generatingSpirit'),
      trans('analyzingPersonality'),
      trans('designingCompanion'),
      trans('weavingPattern'),
      trans('almostDone')
    ];
    
    let textIndex = 0;
    const textInterval = setInterval(() => {
      textIndex = (textIndex + 1) % loadingTexts.length;
      setLoadingText(loadingTexts[textIndex]);
    }, 3000);
    
    try {
      if (!testConfig) {
        throw new Error('Test configuration not loaded');
      }

      // 使用设计师API生成AI伴侣形象
      const response = await fetch(`${API_BASE_URL}/api/designer/test-current-stream`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          projectId: testConfig.project?.id,
          versionId: testConfig.version?.id,
          testInput: {
            mode: 'context',
            contextInputs: formData,
            contextDefinitions: testConfig.version?.roleGenerationConfig?.contextDefinitions || []
          },
          provider: testConfig.llmConfig?.provider || 'claude',
          model: testConfig.llmConfig?.model || 'claude-sonnet-4-6',
          temperature: testConfig.llmConfig?.temperature || 0,
          currentEditorData: testConfig.currentEditorData,
          type: 'role'
        })
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      // 处理SSE流式响应
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';
      let finalSvgCode = '';
      
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          
          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';
          
          for (const line of lines) {
            if (line.startsWith('data: ') && !line.includes('[DONE]')) {
              try {
                const data = JSON.parse(line.slice(6));
                
                // 处理最终SVG结果
                if (data.type === 'final_result' && data.svgCode) {
                  finalSvgCode = data.svgCode;
                  // 终止快照也推进渲染
                  setGuardianSpiritSVG(finalSvgCode);
                } else if (data.type === 'complete' && data.success && (data.svg_result || data.svgCode)) {
                  // 兼容complete事件
                  finalSvgCode = data.svg_result || data.svgCode;
                  setGuardianSpiritSVG(finalSvgCode);
                }
                
                // 处理部分SVG内容
                else if (data.type === 'svg_partial' && data.content) {
                  finalSvgCode = data.content;
                  // 实时渲染SVG，以实现流式预览
                  setGuardianSpiritSVG(finalSvgCode);
                }
                
              } catch (parseError) {
                console.warn('Failed to parse SSE data:', parseError);
              }
            }
          }
        }
        
        if (finalSvgCode) {
          clearInterval(textInterval);
          setGuardianSpiritSVG(finalSvgCode);
          setUserProfile(prev => ({ ...prev, ...formData }));
          setIsGeneratingSpirit(false);
          nextStep();
          console.log('✅ AI companion image generated successfully');
          return;
        }
        
      } finally {
        reader.releaseLock();
      }
      
      throw new Error('Generation failed');
      
    } catch (error) {
      console.error('❌ Failed to generate AI companion image:', error);
      clearInterval(textInterval);
      setLoadingText(trans('generatingSpirit'));
      setUserProfile(prev => ({ ...prev, ...formData }));
      setIsGeneratingSpirit(false);
      nextStep();
    }
  };

  const updateProfile = (data) => {
    setUserProfile(prev => ({ ...prev, ...data }));
  };

  const updateLoginData = (data) => {
    setLoginData(data);
  };

  const completeSignin = () => {
    setShowFinalLoading(true);
  };

  const handleFinalLoadingComplete = () => {
    console.log("Login Data:", loginData);
    console.log("User Profile:", userProfile);
    console.log("Test Config:", testConfig);
    // 保持在当前页面，开始测试阶段
  };

  if (!testConfig) {
    return (
      <div className="aipet-page loading">
        <MagicalBackground />
        <div className="loading-container">
          <div className="loading-text">{trans('loadingConfig')}</div>
        </div>
      </div>
    );
  }

  if (showFinalLoading) {
    return (
      <LoadingScreen 
        onComplete={handleFinalLoadingComplete}
        text={trans('preparingTestEnv')}
        language={language}
        duration={2000}
        showMagicalBackground={true}
      />
    );
  }

  return (
    <div className="aipet-page">
      <MagicalBackground />
      {/* Language toggle button */}
      <button 
        onClick={() => setLanguage(prev => prev === 'en' ? 'zh' : 'en')}
        style={{
          position: 'fixed',
          top: '20px',
          right: '20px',
          zIndex: 100,
          padding: '8px 16px',
          borderRadius: '20px',
          background: 'rgba(255, 255, 255, 0.9)',
          border: '1px solid rgba(102, 126, 234, 0.3)',
          cursor: 'pointer',
          fontSize: '14px',
          fontWeight: '600',
          color: '#667eea'
        }}
      >
        {language === 'en' ? '中文' : 'EN'}
      </button>
      {currentStep === 0 && (
        <StepZero 
          onNext={nextStep}
          onLoginData={updateLoginData}
          language={language}
        />
      )}
      {currentStep === 1 && (
        <StepOne 
          userProfile={userProfile}
          testConfig={testConfig}
          onNext={generateSpiritAndNextStep}
          onUpdate={updateProfile}
          language={language}
        />
      )}
      {(currentStep === 1 && isGeneratingSpirit) && (
        <LoadingScreen 
          onComplete={() => {}}
          text={loadingText}
          duration={60000}
          showMagicalBackground={true}
          isIndefinite={true}
          language={language}
        />
      )}
      {currentStep >= 2 && (
        <StepTwo 
          userProfile={userProfile}
          testConfig={testConfig}
          guardianSpiritSVG={guardianSpiritSVG}
          onComplete={completeSignin}
          language={language}
        />
      )}
    </div>
  );
}

export default AiPetPage;