import React from 'react';
import { 
  IconUndo, 
  IconRedo, 
  IconCopy, 
  IconDelete
} from '@arco-design/web-react/icon';
import alignLeftIcon from '../../assets/icons/align-left.png';
import alignCenterHIcon from '../../assets/icons/align-center-h.png';
import alignRightIcon from '../../assets/icons/align-right.png';
import alignTopIcon from '../../assets/icons/align-top.png';
import alignCenterVIcon from '../../assets/icons/align-center-v.png';
import alignBottomIcon from '../../assets/icons/align-bottom.png';
import { useLanguage } from '../../contexts/LanguageContext';
import './Toolbar.css';

// 内联 SVG 图标以提升辨识度
const ToolIcon = ({ id }) => {
  const common = { stroke: 'currentColor', fill: 'none', strokeWidth: 1.6, strokeLinecap: 'round', strokeLinejoin: 'round' };
  switch (id) {
    case 'select':
      // 虚线选择框 + 简化指针
      return (
        <svg viewBox="0 0 24 24" aria-hidden>
          <rect x="5" y="5" width="10" height="10" rx="2" strokeDasharray="3 3" {...common} />
          <path d="M14.5 14.5 L18.5 18.5" {...common} />
          <path d="M16.8 18.2 L18.6 18.6 L18.2 16.8" {...common} />
        </svg>
      );
    case 'area':
      // 虚线区域框 - 实心填充
      return (
        <svg viewBox="0 0 24 24" aria-hidden>
          <rect x="4" y="4" width="16" height="16" rx="2" strokeDasharray="4 4" stroke="currentColor" fill="currentColor" fillOpacity="0.3" strokeWidth="2" />
        </svg>
      );
    case 'rect':
      // 明确的矩形轮廓 + 淡填充，避免像直线
      return (
        <svg viewBox="0 0 24 24" aria-hidden>
          <rect x="5" y="5" width="14" height="14" rx="2" stroke="currentColor" fill="currentColor" fillOpacity="0.15" strokeWidth="1.8" />
        </svg>
      );
    case 'circle':
      return (
        <svg viewBox="0 0 24 24" aria-hidden>
          <circle cx="12" cy="12" r="7" stroke="currentColor" fill="currentColor" fillOpacity="0.15" strokeWidth="1.8" />
        </svg>
      );
    case 'ellipse':
      return (
        <svg viewBox="0 0 24 24" aria-hidden>
          <ellipse cx="12" cy="12" rx="8" ry="6" stroke="currentColor" fill="currentColor" fillOpacity="0.15" strokeWidth="1.8" />
        </svg>
      );
    // no default shape icon
    default:
      return <svg viewBox="0 0 24 24" aria-hidden><circle cx="12" cy="12" r="1" {...common} /></svg>;
  }
};

const SELECTION_TOOLS = [
  { id: 'select', nameKey: 'toolbar.tools.select', shortcut: 'V' }
];

const AREA_TOOLS = [
  { id: 'area', nameKey: 'toolbar.tools.area', shortcut: 'A' }
];

const SHAPE_TOOLS = [
  { id: 'rect', nameKey: 'toolbar.tools.rectangle', shortcut: 'R' },
  { id: 'circle', nameKey: 'toolbar.tools.circle', shortcut: 'C' },
  { id: 'ellipse', nameKey: 'toolbar.tools.ellipse', shortcut: 'E' }
];

const Toolbar = ({
  activeTool,
  onToolChange,
  toolSettings,
  onToolSettingsChange,
  selectedElements = [],
  onElementUpdate,
  canvasSize = { width: 800, height: 500 },
  onUndo,
  onRedo,
  onCopy,
  onDelete,
  onGroup,
  canUndo = false,
  canRedo = false
}) => {
  const { t } = useLanguage();
  
  // 获取选中元素的属性
  const getSelectedElementProperties = () => {
    if (selectedElements.length === 0) return null;
    if (selectedElements.length === 1) {
      const element = selectedElements[0];
      return {
        x: element.x || element.cx || 0,
        y: element.y || element.cy || 0,
        width: element.width || element.r * 2 || element.rx * 2 || 0,
        height: element.height || element.r * 2 || element.ry * 2 || 0
      };
    }
    return { x: '', y: '', width: '', height: '' }; // 多选时显示
  };
  
  const selectedProps = getSelectedElementProperties();

  const handleToolClick = (toolId) => {
    onToolChange(toolId);
  };

  // 处理颜色变更 - 应用到选中的元素
  const handleColorChange = (color) => {
    if (selectedElements.length === 0 || !onElementUpdate) return;
    
    selectedElements.forEach(element => {
      // 仅更新填充相关，设置80%不透明度；同时确保整体不透明度为1以避免描边被影响
      onElementUpdate(element.id, { fill: color, fillOpacity: 0.8, opacity: 1 }, { isUserAction: true });
    });
  };

  // 处理位置和大小更新
  const handlePropertyUpdate = (property, value) => {
    if (selectedElements.length === 1 && onElementUpdate) {
      const element = selectedElements[0];
      const numericValue = parseFloat(value);
      if (isNaN(numericValue)) return;
      
      let updates = {};
      if (property === 'x') {
        if (element.type === 'circle' || element.type === 'ellipse') {
          updates.cx = numericValue;
        } else {
          updates.x = numericValue;
        }
      } else if (property === 'y') {
        if (element.type === 'circle' || element.type === 'ellipse') {
          updates.cy = numericValue;
        } else {
          updates.y = numericValue;
        }
      } else if (property === 'width') {
        if (element.type === 'circle') {
          updates.r = numericValue / 2;
        } else if (element.type === 'ellipse') {
          updates.rx = numericValue / 2;
        } else {
          updates.width = numericValue;
        }
      } else if (property === 'height') {
        if (element.type === 'circle') {
          updates.r = numericValue / 2;
        } else if (element.type === 'ellipse') {
          updates.ry = numericValue / 2;
        } else {
          updates.height = numericValue;
        }
      }
      
      // 工具栏的输入是用户操作，需要保存历史
      onElementUpdate(element.id, updates, { isUserAction: true });
    }
  };

  // 获取元素的中心点和边界
  const getElementBounds = (element) => {
    if (element.type === 'rect') {
      return {
        x: element.x,
        y: element.y,
        width: element.width,
        height: element.height,
        centerX: element.x + element.width / 2,
        centerY: element.y + element.height / 2
      };
    } else if (element.type === 'circle') {
      return {
        x: element.cx - element.r,
        y: element.cy - element.r,
        width: element.r * 2,
        height: element.r * 2,
        centerX: element.cx,
        centerY: element.cy
      };
    } else if (element.type === 'ellipse') {
      return {
        x: element.cx - element.rx,
        y: element.cy - element.ry,
        width: element.rx * 2,
        height: element.ry * 2,
        centerX: element.cx,
        centerY: element.cy
      };
    } else if (element.type === 'line') {
      const minX = Math.min(element.x1, element.x2);
      const maxX = Math.max(element.x1, element.x2);
      const minY = Math.min(element.y1, element.y2);
      const maxY = Math.max(element.y1, element.y2);
      return {
        x: minX,
        y: minY,
        width: maxX - minX,
        height: maxY - minY,
        centerX: (element.x1 + element.x2) / 2,
        centerY: (element.y1 + element.y2) / 2
      };
    }
    // 其他类型暂时返回默认值
    return {
      x: 0,
      y: 0,
      width: 0,
      height: 0,
      centerX: 0,
      centerY: 0
    };
  };

  // 处理对齐操作 - 支持单个元素对画布对齐和多个元素相互对齐
  const handleAlign = (alignType) => {
    if (selectedElements.length === 0 || !onElementUpdate) return;
    
    if (selectedElements.length === 1) {
      // 单个元素：对齐到画布
      const canvasWidth = canvasSize.width;
      const canvasHeight = canvasSize.height;
      const element = selectedElements[0];
      let updates = {};
      
      switch (alignType) {
        case 'left':
          // 对齐到画布左边缘
          if (element.type === 'circle' || element.type === 'ellipse') {
            const radius = element.r || element.rx || 0;
            updates.cx = radius;
          } else {
            updates.x = 0;
          }
          break;
        case 'center-h':
          // 对齐到画布水平中央
          if (element.type === 'circle' || element.type === 'ellipse') {
            updates.cx = canvasWidth / 2;
          } else {
            const elementWidth = element.width || 0;
            updates.x = (canvasWidth - elementWidth) / 2;
          }
          break;
        case 'right':
          // 对齐到画布右边缘
          if (element.type === 'circle' || element.type === 'ellipse') {
            const radius = element.r || element.rx || 0;
            updates.cx = canvasWidth - radius;
          } else {
            const elementWidth = element.width || 0;
            updates.x = canvasWidth - elementWidth;
          }
          break;
        case 'top':
          // 对齐到画布顶部
          if (element.type === 'circle' || element.type === 'ellipse') {
            const radius = element.r || element.ry || 0;
            updates.cy = radius;
          } else {
            updates.y = 0;
          }
          break;
        case 'center-v':
          // 对齐到画布垂直中央
          if (element.type === 'circle' || element.type === 'ellipse') {
            updates.cy = canvasHeight / 2;
          } else {
            const elementHeight = element.height || 0;
            updates.y = (canvasHeight - elementHeight) / 2;
          }
          break;
        case 'bottom':
          // 对齐到画布底部
          if (element.type === 'circle' || element.type === 'ellipse') {
            const radius = element.r || element.ry || 0;
            updates.cy = canvasHeight - radius;
          } else {
            const elementHeight = element.height || 0;
            updates.y = canvasHeight - elementHeight;
          }
          break;
        default:
          break;
      }
      
      if (Object.keys(updates).length > 0) {
        onElementUpdate(element.id, updates, { isUserAction: true });
      }
    } else {
      // 多个元素：相互对齐
      const bounds = selectedElements.map(getElementBounds);
      
      if (alignType === 'center-h') {
        // 水平居中对齐：以所有元素的平均中心X为基准
        const avgCenterX = bounds.reduce((sum, bound) => sum + bound.centerX, 0) / bounds.length;
        
        selectedElements.forEach((element, index) => {
          const bound = bounds[index];
          const offsetX = avgCenterX - bound.centerX;
          let updates = {};
          
          if (element.type === 'rect') {
            updates.x = element.x + offsetX;
          } else if (element.type === 'circle' || element.type === 'ellipse') {
            updates.cx = element.cx + offsetX;
          } else if (element.type === 'line') {
            updates.x1 = element.x1 + offsetX;
            updates.x2 = element.x2 + offsetX;
          }
          
          if (Object.keys(updates).length > 0) {
            onElementUpdate(element.id, updates, { isUserAction: true });
          }
        });
      } else if (alignType === 'center-v') {
        // 垂直居中对齐：以所有元素的平均中心Y为基准
        const avgCenterY = bounds.reduce((sum, bound) => sum + bound.centerY, 0) / bounds.length;
        
        selectedElements.forEach((element, index) => {
          const bound = bounds[index];
          const offsetY = avgCenterY - bound.centerY;
          let updates = {};
          
          if (element.type === 'rect') {
            updates.y = element.y + offsetY;
          } else if (element.type === 'circle' || element.type === 'ellipse') {
            updates.cy = element.cy + offsetY;
          } else if (element.type === 'line') {
            updates.y1 = element.y1 + offsetY;
            updates.y2 = element.y2 + offsetY;
          }
          
          if (Object.keys(updates).length > 0) {
            onElementUpdate(element.id, updates, { isUserAction: true });
          }
        });
      } else if (alignType === 'left') {
        // 左对齐：以最左边元素的左边缘为基准
        const minLeft = Math.min(...bounds.map(bound => bound.x));
        
        selectedElements.forEach((element, index) => {
          const bound = bounds[index];
          const offsetX = minLeft - bound.x;
          let updates = {};
          
          if (element.type === 'rect') {
            updates.x = element.x + offsetX;
          } else if (element.type === 'circle' || element.type === 'ellipse') {
            updates.cx = element.cx + offsetX;
          } else if (element.type === 'line') {
            updates.x1 = element.x1 + offsetX;
            updates.x2 = element.x2 + offsetX;
          }
          
          if (Object.keys(updates).length > 0) {
            onElementUpdate(element.id, updates, { isUserAction: true });
          }
        });
      } else if (alignType === 'right') {
        // 右对齐：以最右边元素的右边缘为基准
        const maxRight = Math.max(...bounds.map(bound => bound.x + bound.width));
        
        selectedElements.forEach((element, index) => {
          const bound = bounds[index];
          const offsetX = maxRight - (bound.x + bound.width);
          let updates = {};
          
          if (element.type === 'rect') {
            updates.x = element.x + offsetX;
          } else if (element.type === 'circle' || element.type === 'ellipse') {
            updates.cx = element.cx + offsetX;
          } else if (element.type === 'line') {
            updates.x1 = element.x1 + offsetX;
            updates.x2 = element.x2 + offsetX;
          }
          
          if (Object.keys(updates).length > 0) {
            onElementUpdate(element.id, updates, { isUserAction: true });
          }
        });
      } else if (alignType === 'top') {
        // 顶部对齐：以最上方元素的顶边为基准
        const minTop = Math.min(...bounds.map(bound => bound.y));
        
        selectedElements.forEach((element, index) => {
          const bound = bounds[index];
          const offsetY = minTop - bound.y;
          let updates = {};
          
          if (element.type === 'rect') {
            updates.y = element.y + offsetY;
          } else if (element.type === 'circle' || element.type === 'ellipse') {
            updates.cy = element.cy + offsetY;
          } else if (element.type === 'line') {
            updates.y1 = element.y1 + offsetY;
            updates.y2 = element.y2 + offsetY;
          }
          
          if (Object.keys(updates).length > 0) {
            onElementUpdate(element.id, updates, { isUserAction: true });
          }
        });
      } else if (alignType === 'bottom') {
        // 底部对齐：以最下方元素的底边为基准
        const maxBottom = Math.max(...bounds.map(bound => bound.y + bound.height));
        
        selectedElements.forEach((element, index) => {
          const bound = bounds[index];
          const offsetY = maxBottom - (bound.y + bound.height);
          let updates = {};
          
          if (element.type === 'rect') {
            updates.y = element.y + offsetY;
          } else if (element.type === 'circle' || element.type === 'ellipse') {
            updates.cy = element.cy + offsetY;
          } else if (element.type === 'line') {
            updates.y1 = element.y1 + offsetY;
            updates.y2 = element.y2 + offsetY;
          }
          
          if (Object.keys(updates).length > 0) {
            onElementUpdate(element.id, updates, { isUserAction: true });
          }
        });
      }
    }
  };

  return (
    <div className="toolbar">
      {/* 工具按钮 */}
      <div className="tool-section">
        <div className="toolbar-section-title">{t('designerPage.toolbar.sections.selection')}:</div>
        <div className="tools-grid">
          {SELECTION_TOOLS.map(tool => (
            <button
              key={tool.id}
              className={`tool-button ${activeTool === tool.id ? 'active' : ''}`}
              data-tool={tool.id}
              onClick={() => handleToolClick(tool.id)}
              title={`${t(tool.nameKey)} (${tool.shortcut})`}
            >
              <span className="tool-icon"><ToolIcon id={tool.id} /></span>
            </button>
          ))}
        </div>
      </div>

      {/* 区域工具 */}
      <div className="tool-section">
        <div className="toolbar-section-title">{t('designerPage.toolbar.sections.area')}:</div>
        <div className="tools-grid">
          {AREA_TOOLS.map(tool => (
            <button
              key={tool.id}
              className={`tool-button ${activeTool === tool.id ? 'active' : ''}`}
              data-tool={tool.id}
              onClick={() => handleToolClick(tool.id)}
              title={`${t(tool.nameKey)} (${tool.shortcut})`}
            >
              <span className="tool-icon"><ToolIcon id={tool.id} /></span>
            </button>
          ))}
        </div>
      </div>

      {/* 形状工具 */}
      <div className="tool-section">
        <div className="toolbar-section-title">{t('designerPage.toolbar.sections.shapes')}:</div>
        <div className="tools-grid">
          {SHAPE_TOOLS.map(tool => (
            <button
              key={tool.id}
              className={`tool-button ${activeTool === tool.id ? 'active' : ''}`}
              data-tool={tool.id}
              onClick={() => handleToolClick(tool.id)}
              title={`${t(tool.nameKey)} (${tool.shortcut})`}
            >
              <span className="tool-icon"><ToolIcon id={tool.id} /></span>
            </button>
          ))}
        </div>
      </div>

      {/* 颜色设置 */}
      <div className="tool-section">
        <div className="toolbar-section-title">{t('designerPage.toolbar.sections.colors')}:</div>
        
        <div className="color-grid">
          {[
            { nameKey: 'toolbar.colors.black', color: '#000000' },
            { nameKey: 'toolbar.colors.darkGray', color: '#333333' },
            { nameKey: 'toolbar.colors.mediumGray', color: '#808080' },
            { nameKey: 'toolbar.colors.lightGray', color: '#D9D9D9' },
            { nameKey: 'toolbar.colors.white', color: '#FFFFFF' }
          ].map(colorItem => (
            <button
              key={colorItem.color}
              className={`color-preset-button ${colorItem.color === '#FFFFFF' ? 'white-color' : ''}`}
              style={{ 
                backgroundColor: colorItem.color,
                border: colorItem.color === '#FFFFFF' ? '1px solid #ccc' : 'none'
              }}
              onClick={() => handleColorChange(colorItem.color)}
              title={t(`designerPage.${colorItem.nameKey}`)}
              disabled={selectedElements.length === 0}
            />
          ))}
        </div>
      </div>

      {/* 位置调整 */}
      <div className="tool-section">
        <div className="toolbar-section-title">{t('designerPage.toolbar.sections.position')}:</div>
        
        <div className="property-group">
          <div className="property-item">
            <label className="property-label">X</label>
            <input
              type="number"
              className="property-input"
              value={selectedProps ? (selectedProps.x === '' ? '' : Math.round(selectedProps.x)) : ''}
              onChange={(e) => handlePropertyUpdate('x', e.target.value)}
              disabled={!selectedProps || selectedProps.x === ''}
              placeholder=""
            />
          </div>
          <div className="property-item">
            <label className="property-label">Y</label>
            <input
              type="number"
              className="property-input"
              value={selectedProps ? (selectedProps.y === '' ? '' : Math.round(selectedProps.y)) : ''}
              onChange={(e) => handlePropertyUpdate('y', e.target.value)}
              disabled={!selectedProps || selectedProps.y === ''}
              placeholder=""
            />
          </div>
        </div>
      </div>

      {/* 大小调整 */}
      <div className="tool-section">
        <div className="toolbar-section-title">{t('designerPage.toolbar.sections.size')}:</div>
        
        <div className="property-group">
          <div className="property-item">
            <label className="property-label">W</label>
            <input
              type="number"
              className="property-input"
              value={selectedProps ? (selectedProps.width === '' ? '' : Math.round(selectedProps.width)) : ''}
              onChange={(e) => handlePropertyUpdate('width', e.target.value)}
              disabled={!selectedProps || selectedProps.width === ''}
              placeholder=""
            />
          </div>
          <div className="property-item">
            <label className="property-label">H</label>
            <input
              type="number"
              className="property-input"
              value={selectedProps ? (selectedProps.height === '' ? '' : Math.round(selectedProps.height)) : ''}
              onChange={(e) => handlePropertyUpdate('height', e.target.value)}
              disabled={!selectedProps || selectedProps.height === ''}
              placeholder=""
            />
          </div>
        </div>
      </div>

      {/* 对齐功能 */}
      <div className="tool-section">
        <div className="toolbar-section-title">{t('designerPage.toolbar.sections.alignment')}:</div>
        
        <div className="align-group">
          <button 
            className="align-button" 
            onClick={() => handleAlign('left')}
            disabled={!selectedProps}
            title={t('designerPage.toolbar.alignment.alignLeft')}
          >
            <img src={alignLeftIcon} alt="align left" style={{width: '18px', height: '18px', opacity: 0.8}} />
          </button>
          <button 
            className="align-button" 
            onClick={() => handleAlign('center-h')}
            disabled={!selectedProps}
            title={t('designerPage.toolbar.alignment.alignCenter')}
          >
            <img src={alignCenterHIcon} alt="align center" style={{width: '18px', height: '18px', opacity: 0.8}} />
          </button>
          <button 
            className="align-button" 
            onClick={() => handleAlign('right')}
            disabled={!selectedProps}
            title={t('designerPage.toolbar.alignment.alignRight')}
          >
            <img src={alignRightIcon} alt="align right" style={{width: '18px', height: '18px', opacity: 0.8}} />
          </button>
          <button 
            className="align-button" 
            onClick={() => handleAlign('top')}
            disabled={!selectedProps}
            title={t('designerPage.toolbar.alignment.alignTop')}
          >
            <img src={alignTopIcon} alt="align top" style={{width: '18px', height: '18px', opacity: 0.8}} />
          </button>
          <button 
            className="align-button" 
            onClick={() => handleAlign('center-v')}
            disabled={!selectedProps}
            title={t('designerPage.toolbar.alignment.alignMiddle')}
          >
            <img src={alignCenterVIcon} alt="align center vertical" style={{width: '18px', height: '18px', opacity: 0.8}} />
          </button>
          <button 
            className="align-button" 
            onClick={() => handleAlign('bottom')}
            disabled={!selectedProps}
            title={t('designerPage.toolbar.alignment.alignBottom')}
          >
            <img src={alignBottomIcon} alt="align bottom" style={{width: '18px', height: '18px', opacity: 0.8}} />
          </button>
        </div>
      </div>

      {/* 快捷操作 */}
      <div className="tool-section">
        <div className="toolbar-section-title">{t('designerPage.toolbar.sections.actions')}:</div>
        
        <button 
          className="action-button" 
          title={t('designerPage.toolbar.actions.undo')}
          onClick={onUndo}
          disabled={!canUndo}
        >
          <IconUndo />
        </button>
        
        <button 
          className="action-button" 
          title={t('designerPage.toolbar.actions.redo')}
          onClick={onRedo}
          disabled={!canRedo}
        >
          <IconRedo />
        </button>
        
        <button 
          className="action-button" 
          title={t('designerPage.toolbar.actions.copy')}
          onClick={onCopy}
          disabled={selectedElements.length === 0}
        >
          <IconCopy />
        </button>
        
        <button 
          className="action-button" 
          title={t('designerPage.toolbar.actions.delete')}
          onClick={onDelete}
          disabled={selectedElements.length === 0}
        >
          <IconDelete />
        </button>
      </div>
    </div>
  );
};

export default Toolbar;
