// Get translation by key path (e.g., 'stepOne.title')
export const getTranslation = (language, keyPath) => {
  const lang = translations[language] || translations.zh;
  const keys = keyPath.split('.');
  let value = lang;
  
  for (const key of keys) {
    value = value[key];
    if (!value) return keyPath; // Return key if not found
  }
  
  return value;
};

// Translation helper
export const t = (language) => (key) => {
  const lang = translations[language] || translations.zh;
  return lang[key] || key;
};